| 连通分量 | — | 无向图中极大的连通子图 |
| 强连通分量 | SCC | 有向图中极大的强连通子图 |

## 复杂度分析

概念本身不涉及具体算法，没有可以分析的复杂度。这里只交代后文算法普遍使用的规模记号，以及握手定理给出的一个恒等式：

- 点数记作 $n = \lvert V \rvert$，边数记作 $m = \lvert E \rvert$，后续所有图论算法的复杂度都用这两个量表示。
- 握手定理：$\sum_{v \in V} d(v) = 2m$。因此把每个点的度数都扫一遍只需要 $O(n)$ 次加法，累计结果恰好是 $2m$。
- 推论「度数为奇数的点有偶数个」在判断欧拉回路、二分图等问题里会反复用到。

## 适用场景

- 它是所有图论算法的**前置概念**：遍历、最短路、最小生成树、连通分量……都作用在「图」这一结构上。
- 看清题目给的是有向图还是无向图、有没有权、允不允许自环重边，直接决定了后面该选哪套算法。
- 判断连通性、统计度数、用握手定理做奇偶性检查，是很多构造题、判定题的突破口。

## 常见陷阱与注意事项

1. **默认允许自环和重边**：OI 题目没特殊说明时，图是可以有自环和重边的，写邻接矩阵或统计度数时要考虑进来。
2. **“路径”的定义不统一**：有的教材把「途径」也叫路径，看到题目里的“路径”“简单路径”最好确认具体指什么。
3. **连通 vs 强连通 vs 弱连通**：无向图谈「连通」，有向图才谈「强连通 / 弱连通」，别混用。
4. **入度和出度**：有向图才有出度、入度之分；无向图只有「度」。
5. **特殊顶点的名字容易记混**：孤立点是 $d = 0$，叶节点是 $d = 1$，支配点是 $d = \lvert V \rvert - 1$。$AKB205$, '图论', array['图论', '基础概念', '度数', '连通性', '握手定理'], null, null, 'knowledge'),
('world-needs-sunday', 'col-graph-bellman-ford', 'Bellman-Ford 单源最短路（含负权）', $AKB206$## 算法原理

Bellman-Ford 算法是求解**含负权边**图中单源最短路的经典算法，基于动态规划思想：最短路最多经过 $n-1$ 条边（$n$ 为节点数），因此只需对所有边进行 $n-1$ 轮松弛操作即可收敛。

与 Dijkstra 的贪心策略不同，Bellman-Ford 不依赖"已确定节点不会被更新"这一假设。它反复遍历所有边，尝试通过每条边 $(u, v, w)$ 松弛 $A[v] = \min(A[v], A[u] + w)$。在非负权图中，Dijkstra 的贪心选择保证每轮确定一个节点，但负权边的存在可能使已"看似确定"的节点获得更短路径，因此贪心失效，必须用 Bellman-Ford 的全量松弛策略。

算法的核心定理：若图中不存在从源点可达的负环（总权为负的环），则最短路最多经过 $n-1$ 条边。证明：若最短路经过 $\geq n$ 条边，由鸽巢原理必存在重复节点，即存在环；最短路中的环权值必为 $0$（正权环可去掉，负权环则无最短路），因此去掉环后边数 $\leq n-1$。故 $n-1$ 轮松弛后所有最短路必然收敛。

本代码使用邻接表存储图，遍历所有节点的出边等价于遍历所有边。松弛前用 `if (A[i] == INF) continue` 跳过尚未到达的节点，防止 `INT_MAX` 参与加法运算而溢出；并额外引入了**提前终止优化**：若某一轮松弛无任何更新（`tmp` 保持 `true`），说明所有距离已收敛，提前 `break`，避免剩余无意义的迭代轮次。

## 状态定义与转移方程

距离数组定义：

$$A[v] = \text{从源点 } s \text{ 到节点 } v \text{ 的当前最短距离估计值}$$

初始化：

$$A[s] = 0, \quad A[v] = +\infty \quad (v \neq s)$$

松弛转移方程（对每条边 $(u, v, w)$）：

$$A[v] = \min\big(A[v],\; A[u] + w\big)$$

迭代轮数：外层循环执行 $n-1$ 次（$n$ 为节点数），每轮对所有 $m$ 条边做一次松弛。

收敛性保证：若图中无负环，$n-1$ 轮后必有 $A[v] = \text{dist}(s, v)$（最短路长度）。

负环检测（扩展）：若第 $n$ 轮仍有松弛发生，则图中存在从源点可达的负环，此时最短路无定义（可以无限变短）。

提前终止条件：

$$\text{若第 } t \text{ 轮中所有边均未能松弛} \;\Rightarrow\; \forall v,\; A[v] \text{ 已收敛} \;\Rightarrow\; \text{break}$$

## 数据结构图示

```
输入示例：n=4, m=5, s=1（含负权有向图）

  边: 1→2(2)  1→3(6)  2→3(-3)  3→4(1)  4→2(-1)

  邻接表：
  edges[1] = {(2,2), (3,6)}
  edges[2] = {(3,-3)}
  edges[3] = {(4,1)}
  edges[4] = {(2,-1)}

  执行过程（n-1 = 3 轮松弛）：

  初始:  A = [INF, 0, INF, INF, INF]

  第 1 轮（遍历节点 1→4 的所有出边）:
    1→2: A[2] = min(INF, 0+2) = 2        ← 更新
    1→3: A[3] = min(INF, 0+6) = 6        ← 更新
    2→3: A[3] = min(6, 2+(-3)) = -1      ← 更新
    3→4: A[4] = min(INF, (-1)+1) = 0     ← 更新
    4→2: A[2] = min(2, 0+(-1)) = -1      ← 更新
    tmp=false → 继续

  第 2 轮:
    1→2: A[2] = min(-1, 0+2) = -1        无变化
    1→3: A[3] = min(-1, 0+6) = -1        无变化
    2→3: A[3] = min(-1, (-1)+(-3)) = -4  ← 更新
    3→4: A[4] = min(0, (-4)+1) = -3      ← 更新
    4→2: A[2] = min(-1, (-3)+(-1)) = -4  ← 更新
    tmp=false → 继续

  第 3 轮:
    1→2: 无变化, 1→3: 无变化
    2→3: A[3] = min(-4, (-4)+(-3)) = -7  ← 更新
    3→4: A[4] = min(-3, (-7)+1) = -6     ← 更新
    4→2: A[2] = min(-4, (-6)+(-1)) = -7  ← 更新
    tmp=false → 继续
    （此例含负环 2→3→4→2，总权 -3，实际不会收敛）

  正常无负环的情况：最多 n-1 轮收敛
```

## 核心操作详解

### 建图：邻接表

- **数据结构**：`vector<vector<pair<int,int>>> edges(n+1)`，`edges[u]` 存储 $u$ 的所有出边 `(v, w)`。
- **关键细节**：Bellman-Ford 需要遍历所有边，用邻接表存储时通过双重循环（外层遍历节点、内层遍历出边）实现。也可用边集数组 `struct Edge { int u, v, w; }` 存储，遍历更直接但需要额外结构。

### 松弛操作

- **条件**：`A[j.first] > A[i] + j.second`，即通过边 $i \to j$ 能否缩短 $A[v]$。
- **执行**：`A[j.first] = A[i] + j.second; tmp = false;`
- **前置判断**：遍历节点 $i$ 前先 `if(A[i] == INF) continue;`，跳过尚未到达的节点，避免 `INT_MAX + 负数` 溢出造成错误松弛。
- **关键细节**：松弛是 Bellman-Ford 的唯一操作，每轮对所有边做一次松弛尝试。`tmp` 标记本轮是否有更新，若全轮无更新则提前终止。松弛的顺序不影响最终结果（但影响收敛速度）。

### 提前终止优化

- **策略**：每轮开始前 `tmp = true`，若松弛发生则 `tmp = false`，轮末检查 `if(tmp) break`。
- **效果**：若图的最短路在第 $k$ 轮就收敛（$k < n-1$），则提前退出，避免 $n-1-k$ 轮无意义遍历。实际场景中多数图在远少于 $n-1$ 轮就收敛。
- **关键细节**：提前终止不改变最坏复杂度（仍为 $O(VE)$），但平均情况下显著加速。

### 负环检测（扩展用法）

- **方法**：在 $n-1$ 轮松弛后再执行第 $n$ 轮，若仍有松弛发生，则存在从源点可达的负环。
- **关键细节**：本代码未实现负环检测（仅执行 $n-1$ 轮），但扩展时只需在循环后加一轮检查。注意负环必须从源点可达才影响最短路定义。

## 逐行代码解析

下面按模块拆解整份代码：各模块的代码块按顺序拼接后，与 `codePath` 指向的 `.cpp` 完全一致（仅多出 `//` 注释）。

### 全局变量与头文件

```cpp
#include<bits/stdc++.h>
using namespace std;
const long long INF = INT_MAX;          // 用 long long 存距离，INF 取 INT_MAX
```

- `#include<bits/stdc++.h>` 是竞赛常用万能头，一次引入 `vector`、`pair`、`iostream` 等全部所需设施。
- `const long long INF = INT_MAX`：距离数组用 `long long` 存储，避免负权运算中的溢出。`INF` 取 `INT_MAX` 时，未到达节点若直接参与加法会溢出，因此代码在松弛前用 `if(A[i] == INF) continue` 跳过未到达节点（见「常见陷阱与注意事项」第 1 条）。

### main 开头与读入建图

```cpp
int main()
{
    ios::sync_with_stdio(false);        // 加速 I/O
    cin.tie(nullptr);cout.tie(nullptr);
    int n,m,s;
    cin >> n >> m >> s;                 // n 个节点，m 条边，源点 s

    vector<vector<pair<int,int>>> edges(n + 1);  // 邻接表
    for(int i = 1;i <= m;i++)
    {
        int u,v,w;
        cin >> u >> v >> w;
        edges[u].emplace_back(v,w);    // 有向边 u→v，权重 w
    }
```

- `ios::sync_with_stdio(false)` 关闭 C/C++ 输入同步，`cin.tie(nullptr)` 解除与 `cout` 的绑定，显著加快大量读入。
- `edges(n + 1)` 分配 $1 \sim n$ 编号的邻接表；循环 `i <= m` 恰好读入 $m$ 条边。
- `edges[u].emplace_back(v, w)` 构建有向边 $u \to v$；若为无向图需再补 `edges[v].emplace_back(u, w)`。

### 距离数组初始化

```cpp
    vector<long long> A(n + 1,INF);     // 距离数组，long long 防负权溢出
    A[s] = 0;                           // 源点距离为 0
```

- `A` 大小为 $n+1$、初值全为 `INF`，对应「除源点外所有点初始为无穷」的状态定义。
- `A[s] = 0` 设定源点到自身的距离为 0，作为松弛的起点。

### 核心松弛循环（n−1 轮）

```cpp
    for(int t = 1;t < n;t++)           // n-1 轮松弛
    {
        bool tmp = true;                // 标记本轮是否有更新
        for(int i = 1;i <= n;i++)       // 遍历每个节点
        {
            if(A[i] == INF) continue;   // 跳过未到达节点，防 INF 溢出
            for(pair<int,int> j : edges[i])  // 遍历 i 的所有出边
            {
                if(A[j.first] > A[i] + j.second)  // 松弛条件
                {
                    A[j.first] = A[i] + j.second;  // 更新距离
                    tmp = false;                    // 标记有更新
                }
            }
        }
        if(tmp) break;                 // 本轮无更新 → 已收敛，提前退出
    }
```

- 外层 `t < n` 执行 $n-1$ 轮：最短路最多经过 $n-1$ 条边，每轮松弛使最短路边数上限 $+1$。
- 内层双重循环遍历每个节点 $i$ 及其出边 `(j.first, j.second)`，等价于遍历全部 $m$ 条边。
- `if(A[i] == INF) continue` 先跳过尚未到达的节点：未到达时 `A[i] = INF`，直接参与 `A[i] + j.second` 会因 `INT_MAX + 负数` 溢出而错误松弛，跳过既安全又省去无谓遍历。
- `A[j.first] > A[i] + j.second` 是松弛判断：`j.first` 为终点 $v$、`j.second` 为边权 $w$，若经 $u$ 到 $v$ 更短则更新。
- `bool tmp = true` 是提前终止标记：任一边被更新即置 `false`，轮末 `if(tmp) break` 表示所有最短路已收敛。

### 输出与返回

```cpp
    for(int i = 1;i <= n;i++) cout << A[i] << ' ';  // 输出各点最短距离
    return 0;
}
```

- 按 $1 \sim n$ 顺序输出每个点到源点的最短距离，以空格分隔。
- 不可达节点的 `A[i]` 仍为 `INF`（即输出 `INT_MAX`），需根据题目约定决定是否改为特殊输出。

## 复杂度分析

- **时间复杂度**：外层 $n-1$ 轮，每轮遍历所有 $m$ 条边（通过遍历所有节点的出边实现），最坏时间复杂度为 $O(V \times E)$。提前终止优化使平均情况更优：若图在第 $k$ 轮收敛（$k \ll n-1$），实际时间为 $O(k \times E)$。
- **空间复杂度**：邻接表 $O(V + E)$，距离数组 $O(V)$，总空间复杂度为 $O(V + E)$。

与堆优化 Dijkstra（$O((V+E)\log V)$）相比，Bellman-Ford 在非负权图中明显更慢，但能处理 Dijkstra 无法应对的负权边。与 SPFA（Bellman-Ford 的队列优化版）相比，SPFA 均摊 $O(kE)$（$k$ 为平均入队次数，通常 $k \approx 2\sim3$），但最坏退化为 $O(VE)$，且 SPFA 容易被构造数据卡到最坏。

## 适用场景

含负权边的单源最短路问题、需要检测负环的场景（如差分约束系统求解、最短路可行性判断）、图规模不大且边权可能为负的通用最短路问题。常见于竞赛中的负权最短路模板题（如洛谷 P3385），也是差分约束系统建模后求解的标准工具。

## 常见陷阱与注意事项

1. **INF 溢出（本代码已处理）**：`INF = INT_MAX` 时，松弛 `A[i] + j.second` 可能溢出。当 `A[i] = INF` 且 `j.second < 0` 时，`INT_MAX + 负数` 可能溢出为正大值，导致错误松弛。本代码已在松弛前加 `if(A[i] == INF) continue` 跳过未到达节点，避免溢出；等价方案是把 `INF` 设为 `1e18`（`long long` 范围内安全）。
2. **负环检测遗漏**：本代码仅执行 $n-1$ 轮松弛，不检测负环。若图中存在从源点可达的负环，输出的距离值无意义（会持续变小但未收敛）。需在第 $n$ 轮额外检查：若仍有松弛，则存在负环。
3. **无向图负权**：无向图中一条负权边等价于一个负权环（来回走），因此无向图中存在负权边即存在负环，Bellman-Ford 不会收敛。
4. **松弛顺序影响效率**：虽然松弛顺序不影响最终结果（$n-1$ 轮必收敛），但影响收敛速度。若按最短路顺序松弛，1 轮即可收敛；若逆序松弛，需 $n-1$ 轮。提前终止优化在多数情况下能自动处理这一问题。
5. **long long 与 int 混用**：`A` 是 `long long` 数组，但 `j.second`（边权）是 `int`。运算 `A[i] + j.second` 会隐式提升为 `long long`，安全。但若边权也用 `long long`，需确保输入读取正确。
6. **节点编号从 1 开始**：代码中节点编号为 $1 \sim n$，邻接表和距离数组大小为 $n+1$。若题目编号从 $0$ 开始，需调整循环范围和数组大小。

## 对比与扩展

与堆优化 Dijkstra（$O((V+E)\log V)$）相比，Bellman-Ford 能处理负权边但复杂度更高（$O(VE)$），适合图规模不大或含负权的场景。与 SPFA 相比，SPFA 是 Bellman-Ford 的队列优化版，只松弛"上轮有更新的节点的出边"，均摊更快但最坏复杂度相同且易被构造数据卡。与 Floyd（$O(V^3)$ 全源最短路）相比，Bellman-Ford 求单源最短路，规模互补。

扩展方向包括：① **负环检测**：在 $n-1$ 轮后加第 $n$ 轮检查，若有更新则存在负环；② **差分约束系统**：将不等式 $x_v - x_u \leq w$ 建为边 $u \to v$ 权 $w$，跑 Bellman-Ford 后 $A[v]$ 即为满足约束的解；③ **SPFA 优化**：用队列仅存储上轮更新的节点，避免全量遍历；④ **Bellman-Ford 的队列优化（SPFA）** 在实践中更常用，但需注意构造数据下的退化风险；⑤ **Johnson 全源最短路**：先用 Bellman-Ford 求各点到虚拟源点的最短路 $h(v)$（并检测负环），再用 $h$ 对边重赋权（$w'(u,v) = w(u,v) + h(u) - h(v) \geq 0$），最后对每个点跑 Dijkstra。$AKB206$, '图论', array['图论', '最短路', 'Bellman-Ford', '负权边', '松弛', '动态规划', '负环检测'], 'col-graph-shortest-overview', null, 'knowledge'),
('world-needs-sunday', 'col-graph-bipartite-dfs-coloring', '二分图（判定与最大匹配）', $AKB207$## 算法原理

二分图（Bipartite Graph）是一种特殊的无向图，其顶点可以划分为两个**互不相交**的集合，使得图中每条边的两个端点分别属于不同的集合。换句话说，同一集合内的顶点之间没有边相连。

### 什么是二分图

设无向图 $G = (V, E)$，若存在顶点集的一个划分 $V = A \cup B$，满足 $A \cap B = \emptyset$，且对任意边 $(u, v) \in E$，都有 $u \in A, v \in B$ 或 $u \in B, v \in A$，则称 $G$ 为二分图。

**核心性质**：一个无向图是二分图，**当且仅当图中不存在长度为奇数的环（奇环）**。

### 染色法思想

染色法是判定二分图最直观的方法：用两种颜色（如颜色 1 和颜色 2）给图中顶点染色，要求相邻顶点颜色不同。如果能成功完成染色，则是二分图；如果在染色过程中发现相邻顶点颜色相同，则存在奇环，不是二分图。

具体步骤：
1. 任选一个起点，染成颜色 1
2. 从该点出发进行 DFS 遍历
3. 对当前节点的每个邻接点：
   - 若未染色：染成与当前节点相反的颜色，继续 DFS
   - 若已染色且颜色与当前节点相同：说明存在奇环，不是二分图
   - 若已染色且颜色不同：无需处理

### 为什么等价于无奇环

- **必要性**：若图中有奇环，则环上顶点交替染色时，绕奇环一圈后首尾颜色相同，产生矛盾
- **充分性**：若图中无奇环，则从任意点出发 BFS/DFS 交替染色不会产生冲突

## 核心状态定义与转移

### 状态定义

| 变量 | 含义 |
|------|------|
| `vis[u]` | 节点 $u$ 的染色状态：$0$ 表示未染色，$1$ 表示颜色 1，$2$ 表示颜色 2 |
| `node[0]` | 颜色为 1 的所有节点（即集合 $A$） |
| `node[1]` | 颜色为 2 的所有节点（即集合 $B$） |
| `ans` | 全局标记，表示当前是否仍为二分图 |

### 染色转移规则

DFS 函数签名：`dfs(idx, k)` —— 将节点 `idx` 染为颜色 `k`

**三种情况的处理**：

$$
\text{dfs}(u, c) =
\begin{cases}
\text{跳过} & \text{ans = false（已发现矛盾）} \\
\text{染色 u 为 c，递归所有邻接点为 } 3-c & \text{vis}[u] = 0 \text{（未染色）} \\
\text{返回（一致）} & \text{vis}[u] = c \text{（颜色相同）} \\
\text{ans = false（矛盾）} & \text{vis}[u] + c = 3 \text{（颜色冲突）}
\end{cases}
$$

其中 $3-c$ 是"取反色"的技巧：颜色 1 的反色是 2，颜色 2 的反色是 1，即 $3-1=2, 3-2=1$。

## 逐行代码解析

### 全局变量定义

```cpp
vector<vector<int>> edges;  // 邻接表
vector<int> vis, node[2];   // 染色数组 / 两个集合的节点列表
bool ans;                   // 是否为二分图的标记
```

- `edges`：邻接表存图，`edges[u]` 存储所有与 $u$ 相连的节点
- `vis`：染色数组，0 表示未访问/未染色，1 和 2 表示两种颜色
- `node[0]`、`node[1]`：分别存储染成颜色 1 和颜色 2 的节点，用于最后输出划分结果
- `ans`：全局布尔标记，一旦发现矛盾立即设为 `false`，后续 DFS 直接返回

### 初始化函数

```cpp
void init(int n)
{
	edges.assign(n + 1, vector<int>());
	vis.assign(n + 1, 0);
	node[0].clear(), node[1].clear();
	ans = true;
}
```

- `edges.assign(n + 1, vector<int>())`：为 n 个节点（编号 1~n）分配邻接表
- `vis.assign(n + 1, 0)`：所有节点初始化为未染色（0）
- `node[0].clear(), node[1].clear()`：清空两个集合
- `ans = true`：初始假设是二分图

### 加边函数

```cpp
void add(int u, int v)
{
	edges[u].emplace_back(v);
	edges[v].emplace_back(u);
}
```

无向图需要双向加边：$u$ 的邻接表加入 $v$，$v$ 的邻接表加入 $u$。

### DFS 染色核心函数

```cpp
void dfs(int idx, int k)
{
	if (!ans) return;                    // 已发现矛盾，直接返回
	if (vis[idx] == 0)                   // 情况1：未染色
	{
		vis[idx] = k;                    // 染成颜色 k
		node[k - 1].emplace_back(idx);   // 加入对应集合
		for (int i : edges[idx])         // 遍历所有邻接点
			dfs(i, 3 - k);               // 邻接点染成相反颜色
	}
	else if (vis[idx] == k) return;      // 情况2：颜色相同，无冲突
	else if (vis[idx] + k == 3)          // 情况3：颜色不同，冲突
	{
		ans = false;                     // 标记为非二分图
		return;
	}
}
```

关键要点：

1. **提前返回**：`if (!ans) return;` 是重要的优化。一旦发现矛盾，所有递归分支都无需继续
2. **染色与记录**：`vis[idx] = k` 标记颜色，同时将节点加入 `node[k-1]` 集合
3. **反色技巧**：`3 - k` 巧妙地实现颜色翻转（1→2, 2→1），比 `if/else` 更简洁
4. **冲突判定**：`vis[idx] + k == 3` 等价于"已染色且颜色不同"，因为 $1+2=3$

### 主函数

```cpp
int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr); cout.tie(nullptr);
	int n, m;
	cin >> n >> m;
	init(n);
	for (int i = 1; i <= m; i++)
	{
		int u, v;
		cin >> u >> v;
		add(u, v);
	}
	dfs(1, 1);          // 从节点1开始，染成颜色1
	if (ans)
	{
		cout << "Yes\n";
		for (int i : node[0]) cout << i << ' ';
		cout << '\n';
		for (int i : node[1]) cout << i << ' ';
		cout << '\n';
	}
	else cout << "No\n";
	return 0;
}
```

注意：代码注释中说明"所有的点都是联通的"，因此只需要从节点 1 启动一次 DFS。如果图可能不连通，则需要遍历所有节点，对每个未染色的连通分量分别调用 DFS。

## 复杂度分析

### 时间复杂度：$O(n+m)$

- 每个节点最多被染色一次，即每个节点最多进入一次 DFS
- 每条边最多被访问两次（无向图双向），即每个邻接关系被检查一次
- 总操作量与顶点数 $n$ 和边数 $m$ 成线性关系

### 空间复杂度：$O(n+m)$

- 邻接表存储：$O(n+m)$
- 染色数组 `vis`：$O(n)$
- 结果数组 `node[0]` 和 `node[1]`：合计 $O(n)$
- DFS 递归栈深度：最坏 $O(n)$（链状图）

## 适用场景

### 适用场景

1. **二分图判定**：判断一个无向图是否为二分图，是许多图论问题的前置步骤
2. **二部划分输出**：不仅判定是否为二分图，还输出具体的顶点划分方案
3. **匹配问题前置**：最大匹配、最小顶点覆盖等问题需要先确认图是二分图
4. **奇偶环检测**：利用"二分图等价于无奇环"的性质，检测图中是否存在奇环

### 不适用场景

1. **有向图**：二分图定义针对无向图，有向图的"二分"需另行定义
2. **需要最大匹配**：本算法只做判定和划分，不求解最大匹配（需用匈牙利算法等）
3. **图不连通且只调用一次 DFS**：需要确保对每个连通分量都进行染色

## 常见陷阱与注意事项

### 1. 图不连通的情况

代码假设图是连通的（注释中明确说明）。如果图可能有多个连通分量，必须遍历所有节点：

```cpp
for (int i = 1; i <= n; i++)
{
    if (vis[i] == 0)
    {
        dfs(i, 1);
        if (!ans) break;
    }
}
```

否则某些连通分量未被染色，可能漏判奇环。

### 2. 起点颜色的选择

从哪个点开始、初始染成什么颜色不影响判定结果。二分图的两个集合是对称的，交换颜色 1 和 2 仍然是合法划分。

### 3. ans 标记的全局传递

`ans` 是全局变量，一旦变为 `false`，所有递归分支应立即返回。代码开头的 `if (!ans) return;` 是必要的剪枝，避免无效搜索。

### 4. 反色技巧的正确性

`3 - k` 只在颜色取值为 1 和 2 时成立。如果颜色用 0 和 1 表示，则反色应为 `1 - k`。

### 5. 节点编号从 1 开始

代码中节点编号从 1 开始（`init` 中分配 `n+1` 个空间，主函数从节点 1 开始 DFS）。如果题目中节点从 0 开始，需要调整数组大小和遍历范围。

### 6. 自环的情况

如果图中存在自环（节点到自身的边），则一定不是二分图。从节点 $u$ 出发遍历到邻接点 $u$（自环）时，`vis[u] == k`，而邻接点本应染成 `3-k`；代码先判断 `vis[idx] == k` 并直接返回，因此**自环不会被检测为冲突**，需要在加边时或 DFS 前单独判断。

这是一个需要注意的边界情况。如果图中可能有自环，需要在加边时或 DFS 前单独判断。

## 对比与扩展

### 与 BFS 染色法对比

| 对比维度 | DFS 染色法 | BFS 染色法 |
|----------|-----------|-----------|
| 遍历方式 | 深度优先，递归或栈实现 | 广度优先，队列实现 |
| 时间复杂度 | $O(n+m)$ | $O(n+m)$ |
| 空间复杂度 | $O(n+m)$，递归栈最坏 $O(n)$ | $O(n+m)$，队列最坏 $O(n)$ |
| 实现难度 | 递归实现简洁直观 | 迭代实现稍长但无栈溢出风险 |
| 栈溢出风险 | 链状图可能栈溢出（n 极大时） | 无栈溢出风险 |
| 适用场景 | 图规模不大、递归深度可控 | 大规模图、避免栈溢出 |

### 扩展：带权二分图

本算法处理的是无权二分图的判定。带权二分图的经典问题包括：
- **二分图最大匹配**：匈牙利算法，时间复杂度 $O(nm)$
- **二分图最大权匹配**：KM 算法，时间复杂度 $O(n^3)$
- **二分图最小顶点覆盖**：Konig 定理，等于最大匹配数
- **二分图最大独立集**：等于顶点数减去最小顶点覆盖

### 扩展：二分图与 2-SAT

2-SAT 问题可以通过构造蕴含图并求强连通分量来解决，而二分图判定和 2-SAT 有着深刻的联系：二分图的染色约束本质上就是一种"二选一"的约束关系，类似 2-SAT 中的变量赋值。

## 附：匈牙利算法（二分图最大匹配）

匈牙利算法（Hungarian Algorithm）由匈牙利数学家 König 和 Egerváry 的理论发展而来，是求解**二分图最大匹配**的经典算法。核心思想基于**增广路定理**：一个匹配是最大匹配，当且仅当图中不存在增广路。

#### 基本概念

**二分图匹配**：在二分图 $G = (A \cup B, E)$ 中，选取一组边 $M \subseteq E$，使得 $M$ 中任意两条边没有公共端点，则 $M$ 称为一个匹配。边数最多的匹配称为**最大匹配**。

**增广路**：设 $M$ 是当前匹配。一条从**未匹配点**出发，交替经过**非匹配边**和**匹配边**，最终到达另一侧的**未匹配点**的路径，称为增广路（Augmenting Path）。

增广路的长度一定是奇数，且首尾都是非匹配边。

#### 增广路定理

**定理**：一个匹配 $M$ 是最大匹配 $\Leftrightarrow$ 图中不存在关于 $M$ 的增广路。

**推论**（增广路算法的正确性基础）：如果能找到一条增广路 $P$，将 $P$ 上的匹配边与非匹配边互换，匹配数增加 1。反复寻找增广路直到不存在，即得到最大匹配。

#### 算法框架

1. 初始匹配为空集
2. 遍历左部每个未匹配点 $u$，尝试从 $u$ 出发寻找增广路
3. DFS 搜索：对 $u$ 的每个邻接点 $v$
   - 若 $v$ 未被匹配：直接匹配 $u \leftrightarrow v$，增广成功
   - 若 $v$ 已匹配给 $w$：递归尝试为 $w$ 寻找新的匹配，若成功则将 $v$ 让给 $u$
4. 若所有左部点都尝试完毕，当前匹配即为最大匹配

#### 时间戳优化

朴素实现中，每次 DFS 前需要清空 `vis` 数组标记右侧节点的访问状态。本代码使用**时间戳优化**：用整数 `t` 标记当前轮次，`vis[i] == t` 表示节点 $i$ 在本轮 DFS 中已访问，无需每次清空数组，将每次增广的初始化代价从 $O(m)$ 降为 $O(1)$。

### 核心公式/状态定义与转移方程

#### 状态定义

| 变量 | 含义 |
|------|------|
| `edges[u]` | 左部点 $u$ 的邻接表，存储所有可到达的右部点 |
| `match[v]` | 右部点 $v$ 当前匹配的左部点编号，0 表示未匹配 |
| `vis[v]` | 右部点 $v$ 的访问时间戳，记录是第几轮 DFS 访问的 |
| `t`（DFS 参数） | 当前轮次标识，等于当前左部点编号 $i$ |

#### 转移方程

对左部点 `idx`，DFS 寻找增广路的递归逻辑：

$$
\text{dfs}(u, t) =
\begin{cases}
\text{true} & \exists\, v \in \text{edges}[u],\; \text{vis}[v] \neq t,\; \text{match}[v] = 0 \\
\text{true} & \exists\, v \in \text{edges}[u],\; \text{vis}[v] \neq t,\; \text{dfs}(\text{match}[v], t) = \text{true} \\
\text{false} & \text{否则}
\end{cases}
$$

成功时更新 `match[v] = u`。

#### 增广路的结构

一条增广路形如：

$$
u_0 \xrightarrow{\text{非匹配}} v_0 \xrightarrow{\text{匹配}} u_1 \xrightarrow{\text{非匹配}} v_1 \xrightarrow{\text{匹配}} \cdots \xrightarrow{\text{非匹配}} v_k
$$

其中 $u_0$ 和 $v_k$ 是未匹配点。取反后匹配数 $+1$。

### 逐行代码解析

#### 全局变量定义

```cpp
vector<vector<int>> edges;  // 左边点的邻接表
vector<int> match;           // 右边节点配对的左边点
vector<int> vis;             // 右边节点访问时间戳
int top;                      // （未使用）
```

- `edges`：只存**左部→右部**的有向边（二分图匹配中边是单向使用的）
- `match`：下标是右部点，值是左部点，`match[v] = u` 表示 $v$ 匹配了 $u$，0 表示未匹配
- `vis`：时间戳数组，`vis[v] = t` 表示 $v$ 在第 $t$ 轮 DFS 中被访问过

#### 初始化函数

```cpp
void init(int n, int m)
{
	edges.assign(n + 1, vector<int>());
	vis.assign(m + 1, false);
	match.assign(m + 1, 0);
	top = 0;
}
```

- `edges.assign(n + 1, ...)`：为 $n$ 个左部点分配邻接表
- `vis.assign(m + 1, false)`：时间戳初始化为 0（所有轮次标识都大于 0，故等价于"未访问"）
- `match.assign(m + 1, 0)`：所有右部点初始未匹配

#### DFS 增广核心函数

```cpp
bool dfs(int idx, int t)
{
	for (int i : edges[idx])
	{
		if (vis[i] == t) continue;    // 本轮已访问，跳过
		vis[i] = t;                    // 标记本轮已访问
		if (!match[i] || dfs(match[i], t))  // 右部点未匹配 或 其匹配者可换边
		{
			match[i] = idx;            // 将右部点 i 匹配给左部点 idx
			return true;               // 增广成功
		}
	}
	return false;                      // 所有邻接点都无法增广
}
```

逐行分析关键行：

1. **`if (vis[i] == t) continue;`**：时间戳判重。若 $i$ 在本轮已被访问，说明从 $i$ 出发的递归增广已经失败过，无需重复尝试。这一步保证了每个右部点在单轮 DFS 中最多被访问一次。

2. **`vis[i] = t;`**：在递归前标记访问，防止递归过程中形成环（同一右部点被多次访问导致死循环）。

3. **`if (!match[i] || dfs(match[i], t))`**：增广的两种成功情况：
   - `!match[i]`：右部点 $i$ 未匹配，直接匹配，增广成功
   - `dfs(match[i], t)`：右部点 $i$ 已匹配给 `match[i]`，递归尝试为 `match[i]` 寻找新的匹配。若成功，则 $i$ 让给当前节点 `idx`

4. **`match[i] = idx;`**：更新匹配关系。注意此时可能已经递归修改了 `match[i]` 原匹配者的匹配关系，所以这里只需设置 $i$ 的新匹配。

#### 主函数

```cpp
int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr); cout.tie(nullptr);
	int n, m, e;
	cin >> n >> m >> e;
	init(n, m);
	for (int i = 1; i <= e; i++)
	{
		int u, v;
		cin >> u >> v;
		edges[u].emplace_back(v);
	}
	int cnt = 0;
	for (int i = 1; i <= n; i++)
	{
		if (dfs(i, i)) ++cnt;
	}
	cout << cnt;
	return 0;
}
```

关键点：

- **输入**：$n$ 个左部点，$m$ 个右部点，$e$ 条边。边只从左到右添加（单向）
- **`dfs(i, i)`**：第 $i$ 轮 DFS 的时间戳就是 $i$ 本身，这样每轮的时间戳天然唯一，无需额外维护计数器
- **`cnt`**：统计成功增广的次数，即最大匹配数

### 复杂度分析

#### 时间复杂度：$O(nm)$

- 外层循环遍历 $n$ 个左部点，每次调用 DFS
- 单次 DFS 最坏情况遍历所有 $m$ 条边（递归深度可达 $n$）
- 总复杂度 $O(n \cdot m)$，其中 $n$ 为左部点数，$m$ 为边数

实际运行中，由于时间戳判重使每个右部点在单轮 DFS 中最多访问一次，单轮 DFS 的实际复杂度更接近 $O(m)$ 而非 $O(nm)$，但最坏上界仍为 $O(nm)$。

#### 空间复杂度：$O(n + m)$

- 邻接表 `edges`：$O(n + m)$（$n$ 个左部点的邻接表，共 $m$ 条边）
- `match` 数组：$O(m)$
- `vis` 数组：$O(m)$
- DFS 递归栈深度：最坏 $O(n)$

### 适用场景

#### 适用场景

1. **二分图最大匹配**：最基本的用途，如任务分配、人员调度
2. **二分图最小点覆盖**：由 König 定理，最小点覆盖数 = 最大匹配数
3. **二分图最大独立集**：最大独立集 = 顶点总数 $-$ 最大匹配数
4. **最小路径覆盖**：将 DAG 拆分为最少路径，需先拆点二分图化再用匈牙利算法
5. **棋盘问题**：将棋盘黑白染色后建二分图，求解最多放置互不攻击的棋子数

#### 不适用场景

1. **一般图最大匹配**：匈牙利算法仅适用于二分图，一般图需用带花树（Blossom Algorithm）
2. **带权最大匹配**：需要最大权匹配时，应使用 KM 算法（Kuhn-Munkres）
3. **超大规模二分图**：$n, m$ 极大（如 $10^6$ 级）时，$O(nm)$ 可能超时，需考虑 Hopcroft-Karp 算法

### 常见陷阱与注意事项

#### 1. 建图方向

二分图匹配中，邻接表**只需从左部到右部单向建边**。如果双向建边，DFS 时可能错误地从右部走回左部，导致逻辑混乱。代码中 `edges[u].emplace_back(v)` 只加了左→右的边。

#### 2. 时间戳的唯一性

代码中 `dfs(i, i)` 直接用左部点编号 $i$ 作为时间戳。这要求左部点编号从 1 开始且互不相同。如果左部点编号有特殊含义（如从 0 开始），需要改为 `dfs(i, i + 1)` 或使用独立的时间戳计数器，确保时间戳不为 0（因为 `vis` 初始值为 0 表示未访问）。

#### 3. match 数组的语义

`match[v]` 存的是右部点 $v$ 匹配的**左部点编号**，不是反过来。如果混淆左右部语义，会导致输出结果错误。

#### 4. 多组数据的初始化

如果有多组测试数据，每次必须调用 `init` 清空 `edges`、`match`、`vis`。忘记初始化是常见的 WA 原因。

#### 5. 自环边和重边

二分图中不应有自环（左部和右部是不同集合，自环无意义）。重边不影响正确性但浪费空间，可以在加边时去重。

#### 6. 左右部点数不对称

代码中 $n$（左部）和 $m$（右部）可以不相等。遍历左部点 $1 \sim n$ 即可，不需要遍历右部点。最大匹配数 $\leq \min(n, m)$。

#### 7. `top` 变量未使用

代码中全局变量 `top` 声明了但未使用，属于冗余代码，可以删除。

### 对比与扩展

#### 与 Hopcroft-Karp 算法对比

| 对比维度 | 匈牙利算法 | Hopcroft-Karp |
|----------|-----------|----------------|
| 核心思想 | 单条增广路逐次增广 | 每轮找一组最短增广路批量增广 |
| 时间复杂度 | $O(nm)$ | $O(m\sqrt{n})$ |
| 实现难度 | 简单，DFS 递归 | 较复杂，需 BFS 分层 + DFS |
| 适用规模 | $n, m \leq 500$ | $n, m \leq 10^5$ |
| 常数因子 | 小 | 稍大（BFS 分层开销） |

#### 与 KM 算法对比

| 对比维度 | 匈牙利算法 | KM 算法 |
|----------|-----------|---------|
| 问题类型 | 无权最大匹配 | 带权最大权匹配 |
| 时间复杂度 | $O(nm)$ | $O(n^3)$ |
| 核心思想 | 增广路 | 顶标 + 相等子图 + 增广 |
| 适用场景 | 无权二分图 | 每条边有权值，求权值和最大的匹配 |

#### 扩展：Konig 定理

二分图中有三个经典等式：

- **最小点覆盖 = 最大匹配数**：选择最少的顶点覆盖所有边
- **最大独立集 = 顶点总数 $-$ 最大匹配数**：选择最多的互不相邻的顶点
- **最小路径覆盖 = 顶点总数 $-$ 最大匹配数**（DAG 上，拆点后）

这些定理使匈牙利算法成为解决二分图各类覆盖、独立集问题的核心工具。

#### 扩展：一般图最大匹配

一般图（非二分图）的最大匹配需要处理**奇环**（花，Blossom）的情况。带花树算法（Edmonds' Blossom Algorithm）通过"缩花"操作将奇环收缩为一个点，时间复杂度 $O(n^3)$，是匈牙利算法在一般图上的推广。$AKB207$, '图论', array['图论', '二分图', 'DFS', '染色法', '奇偶环'], null, null, 'knowledge'),
('Fohen', 'col-graph-boruvka--fenfeng', 'Borůvka 最小生成树 · Fohen', $AKB208$## 算法原理

Borůvka 算法是求解**最小生成树**（Minimum Spanning Tree, MST）的经典算法，也是历史上最早提出的 MST 算法之一。与 Kruskal 的"全局最小边优先"、Prim 的"从一点向外扩展"不同，Borůvka 采用**多路并行收缩**的策略：每一轮让当前每个连通块**同时**选出自己连向其他连通块的最小边，然后把所有选中的边一次性加入生成树，使多个连通块合并成更大的连通块。

核心过程（初始时每个节点自成一个连通块）：

1. 对每个连通块，扫描所有边，找出它连向"外部"（即另一个连通块）的**最小边**；
2. 将所有连通块选出的最小边**同时**加入生成树，并用并查集把对应端点合并；
3. 由于每个连通块都会通过一条最小出边与至少另一个块合并，连通块数量每轮**至少减半**；
4. 重复上述过程，直到只剩一个连通块，得到最小生成树。

**正确性**：每个连通块与"其余部分"构成一个**切**，该连通块选出的最小出边正是横跨这个切的最小边。由切定理（Cut Property），横跨切的最小边一定属于某棵最小生成树，因此每轮选出的边都可以被安全加入，最终必然得到 MST。

**复杂度思想**：连通块数每轮至少减半，因此至多 $O(\log n)$ 轮；每轮扫描全部 $m$ 条边，故总复杂度为 $O(m \log n)$。

## 核心公式 / 状态定义与转移方程

### 状态定义

$$\text{fa}[i] = \text{节点 } i \text{ 在并查集中的父节点（根代表其所在连通块）}$$

$$\text{best}[r] = \text{当前轮中，以根 } r \text{ 为代表的连通块连向其他连通块的最小边权，初始为 } +\infty$$

$$\text{bestEdge}[r] = \text{当前轮中连通块 } r \text{ 选出的最小出边}$$

### 每轮扫描：求每个块的最小出边

对每条边 $(u, v, w)$，先求其端点所在连通块的根：

$$r_u = \text{find}(u), \qquad r_v = \text{find}(v)$$

若 $r_u \neq r_v$（该边连接两个不同连通块），则同时更新两端连通块的最小出边：

$$\text{best}[r_u] = \min(\text{best}[r_u],\ w), \qquad \text{best}[r_v] = \min(\text{best}[r_v],\ w)$$

### 合并转移

对每个仍存在最小出边的连通块，将其最小出边的两端点合并，并累加边权：

$$\text{union}(u, v), \qquad \text{ans} \leftarrow \text{ans} + w$$

### 轮数上界

设第 $k$ 轮结束后连通块数为 $C_k$，初始 $C_0 = n$。每个连通块都通过其最小出边与至少一个其他连通块合并，故连通块数至少减半：

$$C_k \le \frac{C_{k-1}}{2} \implies \text{轮数} \le \lceil \log_2 n \rceil$$

### 总复杂度

$$\text{总复杂度} = \text{轮数} \times \text{每轮扫描代价} = O(\log n \cdot m) = O(m \log n)$$

## 逐行代码解析

Borůvka 算法在朋友资料中未给出完整代码，以下是其核心过程的伪代码。

### 第 1 段：初始化与主循环框架

```cpp
// 伪代码：初始化
for i in 1..n:
    fa[i] = i              // 每个节点自成一个连通块
ans = 0                    // 最小生成树边权和
while 连通块数量 > 1:
    for 每个根 r:
        best[r] = INF      // 本轮到其他连通块的最小出边权
        bestEdge[r] = 空   // 对应的最小出边
```

- **`fa`**：并查集父节点数组，初始每个点指向自己，代表 $n$ 个独立的连通块。
- **`ans`**：MST 边权和，随合并不断累加。
- **每轮开始先清空 `best` / `bestEdge`**：因为它们只记录"当前轮"的最小出边，下一轮连通块已变化，必须重新计算。
- **循环终止条件**：连通块数量降到 $1$，说明所有点已连通，MST 完成。

### 第 2 段：扫描所有边，为每个块求最小出边

```cpp
    // 扫描所有边，为每个连通块找最小出边
    for 每条边 (u, v, w):
        ru = find(u); rv = find(v)
        if ru != rv:                    // 该边连接两个不同连通块
            if w < best[ru]:
                best[ru] = w; bestEdge[ru] = (u, v)
            if w < best[rv]:
                best[rv] = w; bestEdge[rv] = (u, v)
```

- **`find` 判断两端点是否同块**：`ru != rv` 说明边 $(u,v)$ 跨两个连通块，才可能是某块的最小出边；同块内部的边直接跳过。
- **双向更新**：一条跨块边对两个端点所在的连通块都是候选出边，因此 `best[ru]` 和 `best[rv]` 都要尝试更新。
- **取 $\min$**：一个连通块可能有多条出边，只保留权值最小的一条。
- **复杂度**：这一轮扫描所有 $m$ 条边，每次 `find` 均摊 $O(\alpha(n))$，故一轮为 $O(m)$。

### 第 3 段：同时合并所有选出的最小出边

```cpp
    // 把所有连通块选出的最小出边同时加入生成树
    for 每个连通块（以根 r 为代表）:
        if best[r] != INF:
            (u, v, w) = bestEdge[r]
            if find(u) != find(v):      // 可能已被其他块提前合并
                union(u, v)
                ans += w
                连通块数量 -= 1
```

- **只有存在最小出边的块才参与合并**：`best[r] == INF` 表示该块没有连向其他块的边，说明图不连通，无生成树。
- **合并前再次 `find` 判重**：两个连通块可能互相选中同一条边，或某块已被本轮其他合并先收缩，因此合并前必须确认两端点仍不在同一块，避免重复累加边权。
- **"同时"加入**：先整体扫出每块的最小出边，再统一合并，是本轮收缩的语义；若边扫边合并会破坏"每个块的最小出边"这一轮的定义。
- **连通块数减半**：每个有出边的块都会与至少另一个块合并，因此本轮结束时连通块数量至多减半。

## 复杂度分析

### 时间复杂度

| 阶段 | 复杂度 |
|---|---|
| 并查集初始化 | $O(n)$ |
| 每一轮扫描全部边 | $O(m)$ |
| 每一轮合并 | $O(n)$ |
| 轮数 | $O(\log n)$ |
| **总计** | $O(m \log n)$ |

每轮连通块数至少减半，故最多进行 $O(\log n)$ 轮；每轮需扫描全部 $m$ 条边并做 $O(1)$ 均摊的并查集操作，总时间复杂度为 $O(m \log n)$。

### 空间复杂度

| 数据结构 | 空间 |
|---|---|
| 边集存储 | $O(m)$ |
| 并查集 `fa` | $O(n)$ |
| 最小出边数组 `best` / `bestEdge` | $O(n)$ |
| **总计** | $O(n + m)$ |

## 适用场景

- **常规题目中较少使用**：Borůvka 在一般 MST 题目里不如 Kruskal（实现简单）或 Prim（稠密图友好）常用，因此普通求 MST 优先考虑前两者。
- **完全图 / 稠密到无法显式存边的图**：当 $m \approx n^2$ 甚至边无法全部显式列出时，Borůvka 的"每轮扫一遍候选"框架可以配合数据结构，只处理"可能成为最小出边"的少数边，从而避免 $O(n^2)$ 甚至更大的枚举。
- **边权由某种规则动态生成的图**：若边权不是显式给出，而是由节点编号、坐标、函数等规则计算得到，可以在每轮扫描时按需计算候选边权，Borůvka 天然适合这种"边在需要时才生成"的场景。
- **结合数据结构优化的 MST**：例如完全图上用 Borůvka 每轮为每个连通块求最小出边时，可借助线段树、堆、分治等结构把单轮降到 $O(n \log n)$ 或 $O(n)$，总复杂度优于直接枚举。
- **需要并行或分层的场景**：每轮各连通块相互独立地选最小出边，天然适合并行处理。

## 常见陷阱与注意事项

1. **每轮必须重新初始化最小出边数组**
   - `best` / `bestEdge` 只对应当前轮，上一轮的值已失效（连通块已经变化）。若不清空会导致沿用旧边、错误合并。

2. **跨块边要双向更新**
   - 一条边 $(u,v,w)$ 对 $u$ 和 $v$ 所在的连通块都是候选出边，只更新一端会漏掉另一块的最小出边。

3. **合并前必须再次判重**
   - 两个连通块可能互相选中同一条边（即同一轮里 $A$ 选 $B$、$B$ 也选 $A$），或某块已被本轮其他合并先收缩。合并前必须再 `find` 一次，确认两端点不在同一块，否则会重复累加边权甚至形成自环。

4. **图不连通的判定**
   - 若某轮存在连通块 `best == INF`（没有连向其他块的边），说明图不连通，不存在最小生成树，应输出无解，而非继续循环。

5. **轮数边界**
   - 连通块数每轮"至少减半"是上界保证，实际轮数可能更少；但需保证循环能正确收敛到只剩一个块，避免死循环或提前退出。

6. **与 Kruskal / Prim 的差异**
   - Borůvka 是"每块同时选最小出边"的并行收缩，不是 Kruskal 的"全局最小边优先"，也不是 Prim 的"从一点扩展"。三者都能得到 MST，但 Borůvka 的价值主要在于特殊图上的可优化性。

## 对比与扩展

### 三种经典 MST 算法对比

| 维度 | Borůvka | Kruskal | Prim |
|---|---|---|---|
| 策略 | 每块同时选最小出边（并行收缩） | 全局最小边优先（边贪心） | 从一点向外扩展最近点（点贪心） |
| 核心数据结构 | 并查集 + 每块最小出边数组 | 并查集 + 边集排序 | 优先队列 / 邻接矩阵 |
| 时间复杂度 | $O(m \log n)$ | $O(m \log m)$ | $O(m \log n)$ / $O(n^2)$ |
| 轮数 / 过程 | $O(\log n)$ 轮，每轮扫全部边 | 排序后一趟选边 | 逐步扩展 $n$ 个点 |
| 稀疏图 | 一般 | 优 | 一般 |
| 稠密图 | 可结合数据结构优化 | 排序开销大 | 矩阵版 $O(n^2)$ |
| 适用场景 | 完全图、边动态生成、需并行 | 常规稀疏图 | 稠密图、有起点要求 |

### 扩展：完全图上的优化

完全图中边数 $m = \frac{n(n-1)}{2}$ 显式存储不可行。Borůvka 每轮只需为每个连通块找到"跨块最小边"，可以按点权、坐标或规则在 $O(n \log n)$ 甚至 $O(n)$ 内完成，从而把整体复杂度压到远低于 $O(n^2)$。这正是朋友资料强调的"完全图、边权由规则动态生成"时 Borůvka 的价值所在。

### 扩展：最小生成森林

图不连通时，Borůvka 的收缩过程自然停在"每个连通分量各成一个块"的状态，即得到最小生成森林，无需额外外层循环。

### 扩展：并行与历史意义

Borůvka 算法（1926 年）早于 Kruskal（1956 年）和 Prim（1957 年），最初用于求解电网的最经济布线问题。其"每块独立选最小出边"的特性使它在并行计算、分布式图处理以及某些离线数据流场景中仍有应用价值。$AKB208$, '图论', array['图论', '最小生成树', 'Borůvka', '并查集', '贪心'], 'col-graph-mst-overview', null, 'knowledge'),
('Xesir', 'col-graph-boruvka--xesir', 'Borůvka 最小生成树 · Xesir', $AKB209$## 算法原理

Borůvka 是一种比 Kruskal、Prim 都**古老**的最小生成树（MST）算法，思路特别「集体主义」：

**每个连通块各自去找一条伸向块外的最小边，然后所有连通块把自己选出的那条边同时加进来。**

妙就妙在「同时」两个字——一次操作下来，每个块都会跟至少另外一个块连上，于是连通块数量**至少减半**。从 $n$ 个块一路减到 $1$ 个块，最多也就 $O(\log n)$ 轮。代价是每轮都得把所有边扫一遍，所以总复杂度 $O(m \log n)$。

一句话概括：**每块选最小出边，同时加边，块数减半，轮数 $O(\log n)$。**

## 逐行代码解析

这篇不给代码（`noCode`），只把上面那句话展开成能照着做的步骤：

```
初始：每个点自成一个连通块

重复以下过程，直到只剩一个连通块：
    ① 对每个连通块，扫描所有边，找出它连向「块外」的最小边
    ② 把所有连通块选出的最小边「同时」加入生成树，并合并对应连通块
```

- ① 是「各扫各的」，每个块只关心自己那条最小出边。
- ② 的关键词是「**同时**」：先把边全部选出来，再统一合并，而不是边选边并。
- 轮数上界来自「块数至少减半」，不是靠某一步的优化技巧抠出来的。

## 复杂度分析

- **时间复杂度**：$O(m \log n)$。轮数为 $O(\log n)$（块数每轮至少减半），每轮扫描全部 $m$ 条边。
- **空间复杂度**：$O(n + m)$，存下边集和连通性标记即可。

## 适用场景

- **常规题目里基本见不到它。** 求 MST 默认还是 Kruskal（好写）或 Prim（稠密图友好），Borůvka 属于「知道有这么个东西」的级别。
- 在**完全图**、或者**边权由某种规则动态生成**的特殊场景下，Borůvka 可以结合数据结构一起优化，跑出很漂亮的效果——这才是它真正的主场。

## 常见陷阱与注意事项

1. **别拿它去做普通 MST**：一般题里用 Kruskal / Prim 更省事，硬上 Borůvka 属于自找麻烦。
2. **复杂度是「每轮扫全边」堆出来的**：$O(m \log n)$ 里的 $\log n$ 是轮数、$m$ 是每轮扫描的代价，边多的时候并不便宜。
3. **它的价值在「能配合优化」**：只有在完全图、或边权按规则动态生成的图里，把「找每块最小出边」交给合适的数据结构，才可能有奇效；普通实现并没有优势。
4. **图不连通时没有生成树**：某一轮里若有连通块找不到连向块外的边，说明图不连通，此时得到的是生成森林。$AKB209$, '图论', array['图论', '最小生成树', 'Borůvka', '贪心'], 'col-graph-mst-overview', null, 'knowledge'),
('world-needs-sunday', 'col-graph-centroid', '树的重心 — 一次DFS回溯法、两次DFS判断法、沿重子树移动法', $AKB210$## 算法原理

### 什么是树的重心

树的重心（Centroid），也叫树的质心，是树中的一个节点。满足：**删掉这个节点后，剩下的各个连通块的大小都不超过整棵树大小的一半**。

换句话说，重心是树中最"居中"的节点——以它为根时，所有子树的大小都不超过 $n/2$。

### 统一符号约定

| 符号 | 含义 |
|------|------|
| $n$ | 整棵树的节点数 |
| $sz[u]$ | 以 $u$ 为根的子树大小 |
| $fa$ | 当前节点的父节点 |
| $v$ | 当前节点的孩子 |
| 孩子方向 | 每个孩子 $v$ 对应的子树，大小为 $sz[v]$ |
| 父亲方向 | 整棵树去掉"以 $u$ 为根的子树"后剩下的部分，大小为 $n - sz[u]$ |

### 核心判断公式

删掉节点 $u$ 后，剩下的连通块分成两类：

1. 每个孩子 $v$ 对应的子树，大小是 $sz[v]$
2. 父亲方向那一块，大小是 $n - sz[u]$

所以，删掉 $u$ 后，最大连通块大小为：

$$
\max\Big(n - sz[u],\ \max_{v \text{ 是 } u \text{ 的孩子}} sz[v]\Big)
$$

如果这个最大值不超过 $n/2$，那么 $u$ 就是树的一个重心。

**重心条件：**

$$
\max\Big(n - sz[u],\ \max_{v \text{ 是 } u \text{ 的孩子}} sz[v]\Big) \le \frac{n}{2}
$$

这是所有求重心方法的共同判断标准。

---

## 三种求法详解

### 方法一：一次 DFS 回溯判断法

#### 核心思想

在 DFS 过程中，当递归到某个节点 $u$，并且它的所有孩子都已经处理完、准备回溯时：

- 每个孩子的 $sz[v]$ 已经算出来了
- $sz[u]$ 也已经算出来了
- 整棵树大小 $n$ 是已知的
- 父亲方向大小 $n - sz[u]$ 也可以算出来

所以在这个时刻，已经有足够信息判断 $u$ 是不是重心，不需要第二次 DFS。

#### 为什么判断必须在回溯阶段？

刚进入 $u$ 时，孩子的子树还没有被 DFS 处理，$sz[v]$ 还不知道，$sz[u]$ 也还没算完。只有等所有孩子都处理完、准备回溯时，才能知道每个孩子子树多大、以 $u$ 为根的子树多大、父亲方向多大。

**判断时机：处理完所有孩子之后，离开 $u$ 之前。**

#### 算法流程

1. 任选一个节点作为根，比如 1
2. 从根开始 DFS
3. 对于当前节点 $u$：
   - 刚进入时，令 $sz[u] = 1$
   - 遍历所有孩子 $v$：递归 DFS 处理 $v$，回溯回来后 $sz[u] += sz[v]$，同时记录最大的 $sz[v]$（记为 $maxChild$）
   - 所有孩子处理完后：计算 $fatherPart = n - sz[u]$，如果 $\max(maxChild, fatherPart) \le n/2$，则 $u$ 是重心
4. DFS 结束后，记录的节点就是所有重心

#### 优缺点

| 优点 | 缺点 |
|------|------|
| 只需要一次 DFS | 判断放在 DFS 回溯里，初学时容易把时机写错 |
| 时间复杂度 $O(n)$ | 变量多，容易把父亲方向写成 $n - sz[fa]$ |
| 可以找到所有重心 | |
| 思路直接，边算边判断 | |

---

### 方法二：两次 DFS / 遍历所有节点判断法

#### 核心思想

先做一次 DFS，只求所有节点的子树大小 $sz[u]$。然后遍历每一个节点 $u$，用统一公式判断它是不是重心。

#### 算法流程

1. 任选根，做一次 DFS，求出所有节点的 $sz[u]$ 和 $parent[u]$
2. 遍历所有节点 $u$：
   - 遍历 $u$ 的所有邻居 $v$，如果 $v$ 是孩子（$v \ne parent[u]$），更新 $maxChild$
   - 计算 $fatherPart = n - sz[u]$
   - 如果 $\max(maxChild, fatherPart) \le n/2$，则 $u$ 是重心

#### 优缺点

| 优点 | 缺点 |
|------|------|
| 思路最直观，完全按定义来 | 需要两次扫描：一次 DFS + 一次遍历 |
| 容易理解，容易讲 | 常数比一次 DFS 回溯法稍大 |
| 可以找到所有重心 | |
| 时间复杂度 $O(n)$ | |

> **与方法一的关系**：判断公式完全一样，区别只是判断时机不同。方法一在 DFS 回溯时顺手判断，方法二先全部求完再统一判断。

---

### 方法三：沿重子树移动法

#### 核心思想

先做一次 DFS 求出所有 $sz[u]$。然后从根开始，如果某个孩子 $v$ 满足 $sz[v] > n/2$，说明 $v$ 那边的节点太多，重心一定在 $v$ 的子树里，于是移动到 $v$。重复直到当前节点的所有孩子都满足 $sz[v] \le n/2$，此时停下来的节点就是一个重心。

#### 为什么父亲方向不用检查？

因为一路走下来，当前节点 $c$ 的 $sz[c]$ 一定满足 $sz[c] > n/2$，所以父亲方向大小 $n - sz[c] < n/2$，父亲方向一定不会超过一半，因此只需要检查孩子方向。

#### 算法流程

1. 任选根，做一次 DFS 求所有 $sz[u]$
2. 令当前节点 $cur = root$
3. 检查 $cur$ 的所有孩子 $v$：
   - 如果存在 $v$ 满足 $sz[v] > n/2$，则 $cur = v$，继续检查
   - 如果不存在这样的孩子，停止
4. 停下来的 $cur$ 就是一个重心

#### 优缺点

| 优点 | 缺点 |
|------|------|
| 点分治中非常常用 | 通常只找到一个重心 |
| 只需要一个重心时非常快 | 如果有两个重心，需额外检查 $sz[v] = n/2$ 的孩子 |
| 沿着一条路走，常数小 | 不如方法一、二直观 |
| 时间复杂度 $O(n)$ | |

---

## 三种方法对比

| 方法 | 扫描次数 | 能否找所有重心 | 适用场景 | 复杂度 |
|------|----------|----------------|----------|--------|
| 一次 DFS 回溯判断 | 1 次 DFS | 能 | 通用，想一次搞定 | $O(n)$ |
| 两次 DFS / 遍历判断 | 1 次 DFS + 1 次遍历 | 能 | 教学，最直观 | $O(n)$ |
| 沿重子树移动 | 1 次 DFS + 沿路移动 | 通常一个 | 点分治 | $O(n)$ |

---

## 重心的性质

1. 一棵树至少有一个重心，至多有两个重心
2. 如果有两个重心，它们一定相邻
3. 如果有两个重心，它们之间的边会把树分成两个大小各为 $n/2$ 的部分
4. 奇数个节点的树通常只有一个重心
5. 偶数个节点的树可能有两个重心
6. 如果已经找到一个重心 $u$，发现它的某个孩子 $v$ 满足 $sz[v] = n/2$，那么 $v$ 也是重心

---

## 逐行代码解析

以下代码实现的是**方法一：一次 DFS 回溯判断法**。

```cpp
#include<bits/stdc++.h>
using namespace std;

int n;                        // 树的节点数
vector<vector<int>> edges;    // 邻接表存图
vector<int> ans;              // 存储所有重心

// 初始化：清空答案和邻接表
void init()
{
    ans.clear();
    edges.assign(n + 1, vector<int>());
}

// DFS：返回以 rt 为根的子树大小，同时在回溯时判断 rt 是否为重心
int dfs(int rt, int fa)
{
    int rt_sz = 1;           // 当前子树大小，初始为 1（自己）
    int max_rt = 0, max_sz = 0;  // max_sz：最大孩子子树大小
    for (int i : edges[rt])  // 遍历所有邻居
    {
        if (i == fa) continue;        // 跳过父节点
        int k = dfs(i, rt);           // 递归处理孩子
        rt_sz += k;                   // 累加子树大小
        if (k > max_sz)               // 更新最大孩子
        {
            max_sz = k;
            max_rt = i;
        }
    }
    // ===== 回溯时判断：当前节点是否为重心 =====
    // 条件：父亲方向 <= n/2 且 最大孩子方向 <= n/2
    if (n - rt_sz <= n / 2 && max_sz <= n / 2)
        ans.emplace_back(rt);
    return rt_sz;    // 返回子树大小给父节点
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr); cout.tie(nullptr);
    cin >> n;
    init();
    for (int i = 1; i < n; i++)
    {
        int u, v;
        cin >> u >> v;
        edges[u].emplace_back(v);
        edges[v].emplace_back(u);
    }
    dfs(1, -1);                 // 从节点 1 开始 DFS
    for (int i : ans) cout << i << ' ';  // 输出所有重心
    return 0;
}
```

### 关键变量说明

| 变量 | 含义 |
|------|------|
| `rt` | 当前 DFS 的节点 |
| `fa` | 当前节点的父节点，用于防止走回头路 |
| `rt_sz` | 以 `rt` 为根的子树大小 |
| `max_sz` | 所有孩子中子树最大的那个的大小 |
| `n - rt_sz` | 父亲方向那块的大小 |
| `ans` | 存储所有重心的结果数组 |

### 判断条件解读

```cpp
if (n - rt_sz <= n / 2 && max_sz <= n / 2)
```

- `n - rt_sz <= n / 2`：父亲方向不超过一半
- `max_sz <= n / 2`：最大的孩子子树也不超过一半
- 两个条件同时满足 → 所有方向都不超过一半 → 当前节点是重心

---

## 复杂度分析

### 时间复杂度

- 每个节点恰好被访问一次
- 每条边恰好被遍历两次（来回各一次）
- 总时间：$O(n)$

### 空间复杂度

- 邻接表：$O(n)$
- DFS 递归栈：最坏 $O(n)$（链状树），平均 $O(\log n)$
- 结果数组：$O(1)$（最多 2 个重心）
- 总空间：$O(n)$

---

## 适用场景

1. **点分治**：每次找重心作为分治中心，保证递归深度为 $O(\log n)$
2. **树的最优根**：求使最大子树最小的根节点
3. **树的中位数**：所有节点到重心的距离之和最小
4. **树上博弈**：某些树上博弈问题的最优策略在重心
5. **树的分解**：将树分解为多个子问题的分治框架

---

## 常见陷阱与注意事项

### 1. 父亲方向大小写错

父亲方向是 $n - sz[u]$，不是 $n - sz[fa]$。$sz[u]$ 是以 $u$ 为根的子树大小，整棵树去掉这个子树就是父亲方向。

### 2. 判断时机错误（方法一）

必须在 DFS 回溯时判断（所有孩子处理完之后），不能刚进入节点时判断。刚进入时孩子的 $sz$ 还没算出来。

### 3. 条件是 $\le$ 不是 $<$

判断条件是**不超过一半**，即 $\le n/2$，不是严格小于。等于 $n/2$ 也算满足。

### 4. 两个重心的情况

如果 $n$ 是偶数，且某个孩子的 $sz[v] = n/2$，那么当前节点和这个孩子都是重心。方法一、二会自然找到两个，但方法三需要额外检查。

### 5. 点分治中的重心

点分治中，当前处理的是一棵子树，不是整棵树。此时判断重心要用当前连通块大小 $total$，不是整棵树的 $n$。

### 6. 变量不要混

- $u$：当前节点
- $fa$：父节点
- $v$：孩子
- $sz[u]$：以 $u$ 为根的子树大小

### 7. 点分治中已删除的节点不能再访问

在点分治的递归过程中，已经处理过的重心需要标记为"已删除"，下次找重心时不能再经过这些节点。

### 8. 邻接表初始化

每次测试用例前要重新初始化邻接表，注意大小是 $n+1$（节点从 1 开始编号）。

---

## 一句话总结

- **一次 DFS 回溯判断法**：DFS 回溯时，孩子大小已算完，算最大块，不超过 $n/2$ 就记成重心。
- **两次 DFS 判断法**：先 DFS 求 $sz$，再逐个节点按公式判断。
- **沿重子树移动法**：哪边孩子超过一半就往哪边走，走到没有超过一半的孩子，当前节点就是重心。

三种方法本质都基于同一个判断公式：

$$
\max\Big(n - sz[u],\ \max_{v \text{ 是 } u \text{ 的孩子}} sz[v]\Big) \le \frac{n}{2}
$$$AKB210$, '图论', array['树', 'DFS', '重心', '子树大小', '点分治'], null, null, 'knowledge'),
('stripe-python', 'col-graph-congruence-shortest-path--stripe-python', '同余最短路 · stripe-python', $AKB211$> 本文由 stripe-python 授权合并，正文保留原文结构与表述；原文为《OI 中的数学基础》（[博客版](https://stripepython.github.io/2025/10/05/OI%20%E4%B8%AD%E7%9A%84%E6%95%B0%E5%AD%A6%E5%9F%BA%E7%A1%80/)），本页按主题拆分。

## 25. 同余最短路

同余最短路是一个使用图论方法解决数论问题的 trick。

## 25.1 适用范围

当题目中存在类似 $f(i+x)=f(i)+x$ 的转移关系时，可以考虑利用同余的性质建立图论模型，在上面跑最短路求解。

常见的同余最短路的模型有：

1. 给出 $n$ 个数 $a_i$，求有多少个 $b \in [0,T]$ 且满足 $\sum_{i=1}^n a_ix_i=b$ 有非负整数解。
2. 体积模 $m$ 意义下的完全背包问题。

由于这个说法过于抽象，因此下面给出一些例题，请读者结合例题学习。另外，这里不讲转圈 trick。

## 25.2 例题

### P3403 跳楼机

就是求 $k \in [0,h)$ 时有多少个 $k$ 满足不定方程 $ax+by+cz=k$。

观察到，若 $k$ 合法，则 $k+ap < h$ 也合法。证明：$k+ap=a(x+p)+by+cz$。

注意到 $k \equiv k+ap \pmod a$，则对于合法的 $k$，满足 $k \equiv k' \pmod a$ 的所有 $k' < h$ 合法，数目为 $\lfloor \dfrac{h-k}{a} \rfloor+1$。

设 $d_i$ 表示模 $a$ 余 $i$ 的 $k$ 中的最小值，只要求出 $d_0 \sim d_{a-1}$。到这里用数论方法就做不下去了。

考虑一个数 $k$，且 $r=k \bmod a$。

- $k \gets k+a$，$r$ 不变。
- $k \gets k+b$，$r \gets (r+b) \bmod a$。
- $k \gets k+c$，$r \gets (r+c) \bmod a$。

显然第一条转移对于 $d_i$ 无影响。考虑剩下两条转移，可以写成这个形式：

$$
d_r \to d_{(r+b) \bmod a}\\
d_r \to d_{(r+c) \bmod a}\\
$$

将 $d$ 作为单源最短路的距离数组，将 $d_i$ 视为一个点，进行图论建模：

- $d_0=0$。
- $d_{1},d_{2},\cdots,d_{a-1}=+\infty$。
- $x \to (x+b) \bmod a$，边权为 $b$。
- $x \gets (x+c) \bmod c$，边权为 $c$。

由 $0$ 开始跑最短路，即可得到所有的 $d$。

到这里我们可以解释同余最短路名字的来源：一个点代表一个同余类，通过同余关系建边求得某种最小值，进而计算答案。

需要注意，由于同余最短路中是根据同余关系建边，无法使得 SPFA 达到最坏复杂度 $O(nm)$，因此可以在同余最短路中使用 SPFA 求最短路。下面给出一个省略 SPFA 板子的代码。

```cpp
#define int long long
const int N = 1e5 + 5;
int h, s[3], a, b, c;

void _main() {
	cin >> h >> s[0] >> s[1] >> s[2];
	sort(s, s + 3), a = s[0], b = s[1], c = s[2], h--;
	for (int i = 0; i < a; i++) {
		add_edge(i, (i + c) % a, c);
		add_edge(i, (i + b) % a, b);
	}
	SPFA::spfa(0);
	int res = 0;
	for (int i = 0; i < a; i++) {
		if (h >= SPFA::dis[i]) res += (h - SPFA::dis[i]) / a + 1;
	}
	cout << res;
}
```

### P2371 [国家集训队] 墨墨的等式

注意到这是上一题的 $n$ 元版本，并且对于 $b$ 有约束 $b \in [l,r]$。利用 $[l,r]=[1,r]-[1,l-1]$ 就能去掉这个限制。

先对 $a$ 排序，以 $a_1$ 为模数建立同余关系：

- $x \to (x+a_i) \bmod a_1$。其中 $i \in [2,n], x \in [0,a)$，边权为 $a_i$。

跑 SPFA 即可。注意特判 $a_i=0$，并且开大空间。

这里需要注意一个点：模数应该选的尽量小。在同余最短路的题目中，边数常常为 $O(nM)$ 级别，其中 $M$ 是模数。这里我们就取 $M=\min a_i$ 最好。

```cpp
#define int long long
const int N = 6e6 + 5;

int m, n, l, r, x, a[N];
long long query(long long x) {
	long long res = 0;
	for (int i = 0; i < a[1]; i++) {
		if (x >= SPFA::dis[i]) res += (x - SPFA::dis[i]) / a[1] + 1;
	} return res;
}

void _main() {
	cin >> m >> l >> r;
	for (int i = 1; i <= m; i++) {
		cin >> x;
		if (x != 0) a[++n] = x;
	}
	sort(a + 1, a + n + 1);
	for (int x = 0; x < a[1]; x++) {
		for (int i = 2; i <= n; i++) add_edge(x, (x + a[i]) % a[1], a[i]);
	}
	SPFA::spfa(0);
	cout << query(r) - query(l - 1);
}
```

### [模拟赛] 星际保安

> 给你一个由四个节点组成的环，求从节点 $2$ 出发，回到节点 $2$ 的不小于 $k$ 的最短路。
>
> $k \le 10^{18}$，环的边权 $\le 3 \times 10^4$。

赛时整了一个假的裴蜀定理解七元不定方程做法水过去了，喜提全场唯一 AK。赛后被 hack 了。

设从 $2$ 到 $2$ 的最短路为 $d$，$2$ 号节点连接的两条边的较小边权为 $w=\min(d_{1,2},d_{2,3})$，则可以进行 $x$ 次往返使得 $d+2wx \ge k$。其他往返方案也类似，这样就是一个不定方程问题。

以 $2w$ 为模数尝试同余最短路。设 $f_{x,i}$ 表示最短路模 $2w$ 的余数为 $x$，到达 $i$ 点的最短路，可以在 Dijkstra 中直接处理。此时点数为 $8w$，复杂度为 $O(w \log w)$，可以通过。最后的答案就是 $f_{x,2}$ 取合法最小值即可。

赛后改题代码。

```cpp
#define int long long
const int N = 60005;
int m, k, d[10], dis[5][N];

int tot = 0, head[N];
struct Edge {
	int next, to, dis;
} edge[N << 1];
inline void add_edge(int u, int v, int w) {
	edge[++tot].next = head[u];
	edge[tot].to = v, edge[tot].dis = w;
	head[u] = tot;
}

struct node {
	int to, dis;
	node(int x = 0, int y = 0) : to(x), dis(y) {}
	bool operator< (const node& other) const {return dis > other.dis;}
};
priority_queue<node> q;
inline void dijkstra() {
	memset(dis, 0x3f, sizeof(dis));
	dis[2][0] = 0, q.emplace(2, 0);
	while (!q.empty()) {
		int u = q.top().to, d = q.top().dis; q.pop();
		for (int j = head[u]; j != 0; j = edge[j].next) {
			int v = edge[j].to, w = edge[j].dis, c = dis[u][d % m] + w;
			if (dis[v][c % m] > c) dis[v][c % m] = c, q.emplace(v, c);
		}
	}
}

void _main() {
	cin >> k >> d[1] >> d[2] >> d[3] >> d[4];
	add_edge(1, 2, d[1]), add_edge(2, 1, d[1]);
	add_edge(2, 3, d[2]), add_edge(3, 2, d[2]);
	add_edge(3, 4, d[3]), add_edge(4, 3, d[3]);
	add_edge(4, 1, d[4]), add_edge(1, 4, d[4]);
	m = min(d[1], d[2]) * 2;
	memset(dis, 0x3f, sizeof(dis));
	dijkstra();
	int res = LLONG_MAX;
	for (int i = 0; i < m; i++) {
		if (dis[2][i] >= k) res = min(res, dis[2][i]);
		else {
			int x = k - dis[2][i], t = x / m * m + m * (x % m != 0);
			res = min(res, t + dis[2][i]);
		}
	} cout << res;
}
```

### P2662 [WC2002] 牛场围栏

还是不定方程问题。

设可以使用的木料长度的集合为 $S$，则 $S=\{l_i-j \mid i \in [1,n], j\in [0,\min(l_i,m)] \}$，记 $\min S=p$。

观察到，$p=1$ 时不存在最大值。设 $d_i$ 表示满足 $k \equiv i \pmod p$ 的最小的 $k$。

建图：对于 $u \in [a_i-m,a_i], v \in [0,p)$，建一条 $v \to (v+u) \pmod p$ 且边权为 $u$ 的边即可。用同余最短路求出 $d_i$，答案为 $\max(d_i-m)$。如果图不连通必然无解。

实现时，并不需要求出 $S$，只要对 $a$ 排序并取 $p=\max(1,a_1-m)$ 即可。

```cpp
#define int long long
const int N = 1e6 + 5;
int n, m, p, a[N];
void _main() {
	cin >> n >> m;
	for (int i = 1; i <= n; i++) cin >> a[i];
	sort(a + 1, a + n + 1);
	int p = max<int>(1, a[1] - m);
	if (p == 1) return cout << -1, void();
	for (int i = 1; i <= n; i++) {
		for (int j = max(a[i - 1] + 1, a[i] - m); j <= a[i]; j++) {
			if (j == p) continue;
			for (int k = 0; k < p; k++) add_edge(k, (k + j) % p, j);
		}
	} SPFA::spfa(0);
	int res = 0;
	for (int i = 0; i < p; i++) {
		if (SPFA::dis[i] >= 0x3f3f3f3f3f3f3f3f) return cout << -1, void();
		res = max(res, SPFA::dis[i] - p);
	} cout << res;
}
```

### AT_arc084_b [ABC077D] Small Multiple

这题做法比较多，同余最短路是经典解法。

注意到，任何一个正整数都可以由 $1$ 开始，按顺序执行若干次 $\times 10, +1$ 的操作得到，且 $+1$ 的次数就是数位和。

建立图论模型：

- $k \to 10k \bmod n$，边权为 $0$。
- $k \to (k+1) \bmod n$，边权为 $1$。

从 $1$ 走到 $0$ 的最短路即为答案。注意到连续走 $10$ 条 $+1$ 其实是不合法的，但是这个题里答案一定不优。使用 01-BFS 可得到 $O(n)$ 复杂度。

### *P9140 [THUPC 2023 初赛] 背包

同余最短路的第二类例题。

由于 $V$ 很大，$v_i$ 很小，大部分背包体积都消耗在了性价比最高的物品上。将物品按性价比排序，我们只要求出余量即可。

一个贪心的想法是，先用 $\lfloor \dfrac{V}{v_1} \rfloor$ 个 $k_1$ 填满大部分，剩下的 $V \bmod v_1$ 的体积再找其他物品填充。但事实上我们可以舍弃一些 $1$ 号物品使得代价更小。

通过这个讨论，实际上问题已经转化为体积模 $v_1$ 意义下的完全背包。记 $d_i$ 表示模 $v_1$ 余 $i$ 的最优解，建立图论模型：

- $i \to (i+v_j) \bmod v_1$，边权为 $c_j-c_1\lfloor \dfrac{i+v_j}{v_1} \rfloor$。

用 SPFA 跑出**最长路**即可，答案即为 $\lfloor \dfrac{V}{v_1} \rfloor c_1 +d_{V \bmod v_1}$。

```cpp
#define int long long
const int N = 5e6 + 5;
int n, q, x;
struct node {
	int v, c;
} a[N];

void _main() {
	cin >> n >> q;
	for (int i = 1; i <= n; i++) cin >> a[i].v >> a[i].c;
	sort(a + 1, a + n + 1, [](const node& a, const node& b) -> bool {
		return a.c * b.v > b.c * a.v;
	});
	int m = a[1].v;
	for (int i = 0; i <= m; i++) {
		for (int j = 1; j <= n; j++) add_edge(i, (i + a[j].v) % m, a[j].c - (i + a[j].v) / m * a[1].c);
	} SPFA::spfa(0);
	while (q--) {
		cin >> x;
		if (SPFA::dis[x % m] < -1e17) {cout << -1 << '\n'; continue;}
		cout << x / m * a[1].c + SPFA::dis[x % m] << '\n';
	}
}
```$AKB211$, '图论', array['同余最短路', '最短路', '同余', '最短路径树'], 'col-graph-shortest-overview', null, 'knowledge'),
('stripe-python', 'col-graph-cyclic-tree--stripe-python', '基环树 · stripe-python', $AKB212$> 本文由 stripe-python 授权合并，保留原文结构与表述。
## 介绍

基环树，一般有 $n$ 个点 $n$ 条边的无向连通图，比如：

![](https://cdn.luogu.com.cn/upload/image_hosting/bnwp8b9x.png)

环用红色标出，可以看到基环树就是一个环上挂了若干子树。特别地，基环树也可以退化为一个单环。

解决基环树的问题有两种思路：

1. 对环上每棵子树先处理，再处理环，最后合并答案；
2. 将基环树拆成树 + 一条边，即断环为链。

因此，基环树问题需要树上问题和环上问题的良好基础。

## 例题

## P8655 [蓝桥杯 2017 国 B] 发现环

【模板】基环树找环。

采用缩圈算法，每次删去最外圈，比如说：

![](https://cdn.luogu.com.cn/upload/image_hosting/559rbb5o.png)

这个图里黄色是第一轮删点，绿色是第二轮，最后剩的就是环了。

考虑一下怎么代码实现。发现当前入度为 $1$ 的点就是最外圈，删掉就行，写一个拓扑排序即可。复杂度 $O(n+m)$。

```cpp
const int N = 1e5 + 5;
int tot = 0, head[N];
struct Edge {
	int next, to;
} edge[N << 1];
inline void add_edge(int u, int v) {
	edge[++tot].next = head[u], edge[tot].to = v, head[u] = tot;
}
int n, u, v, deg[N], tag[N];
queue<int> q;
void bfs() {
	for (int i = 1; i <= n; i++) {
		if (deg[i] == 1) q.emplace(i), tag[i] = true;
	}
	while (!q.empty()) {
		int u = q.front(); q.pop();
		for (int j = head[u]; j != 0; j = edge[j].next) {
			int v = edge[j].to;
			if (--deg[v] == 1) q.emplace(v), tag[v] = true;
		}
	}
}

void _main() {
	cin >> n;
	for (int i = 1; i <= n; i++) {
		cin >> u >> v;
		add_edge(u, v), add_edge(v, u);
		deg[u]++, deg[v]++;
	}
	bfs();
	for (int i = 1; i <= n; i++) if (!tag[i]) cout << i << ' ';
}
```

## P5022 [NOIP 2018 提高组] 旅行

抽象题。先考虑树怎么做，由于要求字典序最小，于是在 DFS 时按儿子编号从小到大走就行了。

对于基环树来说，把环找见以后采用处理方法 2，也就是枚举删去一条边，然后套用树的做法。复杂度 $O(n^2)$ 卡一卡能过，就做完了。

```cpp
const int N = 5005;
int tot = 1, head[N];  // 这里tot=1，则j和j^1互为反边
struct Edge {
	int next, to;
} edge[N << 1];
inline void add_edge(int u, int v) {
	edge[++tot].next = head[u], edge[tot].to = v, head[u] = tot;
}
int n, m, u, v, deg[N], tag[N];
queue<int> q;
void bfs() {
	for (int i = 1; i <= n; i++) {
		if (deg[i] == 1) q.emplace(i), tag[i] = true;
	}
	while (!q.empty()) {
		int u = q.front(); q.pop();
		for (int j = head[u]; j != 0; j = edge[j].next) {
			int v = edge[j].to;
			if (--deg[v] == 1) q.emplace(v), tag[v] = true;
		}
	}
}

void dfs(int u, int fa) {
	cout << u << ' ';
	vector<int> son;
	for (int j = head[u]; j != 0; j = edge[j].next) {
		int v = edge[j].to;
		if (v == fa) continue;
		son.emplace_back(v);
	}
	sort(son.begin(), son.end());
	for (int v : son) dfs(v, u);
}

int e;  // 删掉的边
int cnt, cur[N], ans[N];
void dfs2(int u, int fa) {
	cur[++cnt] = u;
	vector<int> son;
	for (int j = head[u]; j != 0; j = edge[j].next) {
		int v = edge[j].to;
		if (v == fa || j == e || j == (e ^ 1)) continue;
		son.emplace_back(v);
	}
	sort(son.begin(), son.end());
	for (int v : son) dfs2(v, u);
}
void update() {
	for (int i = 1; i <= n; i++) {
		if (cur[i] > ans[i]) return;
		if (cur[i] < ans[i]) break;
	}
	memcpy(ans, cur, sizeof(cur));
}

void _main() {
	cin >> n >> m;
	for (int i = 1; i <= m; i++) {
		cin >> u >> v;
		add_edge(u, v), add_edge(v, u);
		deg[u]++, deg[v]++;
	}
	if (m == n - 1) return dfs(1, -1), void();
	bfs();
	unordered_set<int> ring;  // 存环上的点
	for (int i = 1; i <= n; i++) {
		if (!tag[i]) ring.emplace(i);
	}
	fill(ans + 1, ans + n + 1, 0x3f3f3f3f);
	unordered_set<long long> vis;  // 防止重复删边
	for (int u : ring) {
		for (int j = head[u]; j != 0; j = edge[j].next) {
			int v = edge[j].to;
			if (vis.count(1LL * u * INT_MAX + v) || vis.count(1LL * v * INT_MAX + u)) continue;
			vis.emplace(1LL * u * INT_MAX + v);
			if (!ring.count(v)) continue;
			cnt = 0, e = j, fill(cur + 1, cur + n + 1, 0x3f3f3f3f);
			dfs2(1, -1), update();
		}
	}
	for (int i = 1; i <= n; i++) cout << ans[i] << ' ';
}
```

## P1453 城市环路

这题要是在树上很好做，用 $dp_{0/1,u}$ 表示以 $u$ 为根的子树或不选的贡献，然后对于儿子 $v$，若 $u$ 选 $v$ 一定不能选，否则可选可不选。转移：

$$
dp_{0,u}=\sum _{v \in son(u)} \max(dp_{0,v},dp_{1,v})\\
dp_{1,u}=p_u+\sum _{v \in son(u)} dp_{0,v}
$$

如果只有这样这题只有黄，但是它上了基环树。

那就断环为链，找环上两点 $x,y$，各以 $x,y$ 为根跑一次 dp，然后答案在 $dp_{0,x},dp_{0,y}$ 中取最大值。

分析一下正确性：不妨设答案就是 $dp_{0,x}$，则 $x$ 不选，而 $y$ 可选可不选，与题目相符。因为这题的限制只针对相邻两点而不像上一题针对整个路径，所以也不用全部枚举一遍，仅删一条即可。

这题找环就不要用缩圈了，只需要求任意一组 $x,y$，直接维护个并查集即可。

```cpp
const int N = 1e5 + 5;
int tot = 0, head[N];
struct Edge {
	int next, to;
} edge[N << 1];
inline void add_edge(int u, int v) {
	edge[++tot].next = head[u], edge[tot].to = v, head[u] = tot;
}
int n, u, v, p[N];
double k;

int fa[N];
int find(int x) {return x == fa[x] ? x : fa[x] = find(fa[x]);}

int dp[2][N];
void dfs(int u, int fa) {
	dp[1][u] = p[u];
	for (int j = head[u]; j != 0; j = edge[j].next) {
		int v = edge[j].to;
		if (v == fa) continue;
		dfs(v, u);
		dp[0][u] += max(dp[0][v], dp[1][v]), dp[1][u] += dp[0][v];
	}
}

void _main() {
	cin >> n;
	iota(fa, fa + n + 1, 0);
	for (int i = 1; i <= n; i++) cin >> p[i];
	int x = -1, y = -1;
	for (int i = 1; i <= n; i++) {
		cin >> u >> v; u++, v++;
		int fu = find(u), fv = find(v);
		if (fu == fv) x = u, y = v;  // 删去这条边
		else fa[fu] = fv, add_edge(u, v), add_edge(v, u);
	} cin >> k;
	dfs(x, -1);
	int res = dp[0][x];
	memset(dp, 0, sizeof(dp)), dfs(y, -1);
	cout << fixed << setprecision(1) << k * max(res, dp[0][y]);
}
```

## P4381 [IOI 2008] Island

题目翻译：求一个基环树森林中每课基环树的直径（即最长链）长度之和。

基环树的直径有两种可能：

1. 位于挂在环上的一棵子树中；
2. 穿过环，位于挂在环上的两棵子树中。

第一种情况就是树的直径求法，再处理一下第 $x$ 棵子树中离 $x$ 最远点的距离，记作 $d_x$。

则第二种情况的答案为：

$\max (d_x+d_y+dis_{x,y})$其中 $x, y$ 为环上两点，$dis_{x,y}$ 表示这两点环上距离。对环上的边权作一个前缀和记为 $pre$，则 $dis_{x,y}=pre_x-pre_y$ 或 $tot-(pre_x-pre_y)$，其中 $tot$ 为环上边权之和。则答案为

$\max \{d_x+pre_x+d_y-pre_y, d_x-pre_x+d_y+pre_y-tot\}$由于两部分贡献独立，直接求 $\max(d_x + pre_x)$ 与 $\max(d_y - pre_y)$ 即可。最后一二种情况取最大。

细节上，注意求直径不能用 `dfs(u, fa)` 的写法，而是要记录 `vis` 数组防止在环里一直绕。

至于代码在哪，别问，问就是[没调出来](https://www.luogu.com.cn/discuss/1106524)。

## P2607 [ZJOI2008] 骑士

题意：求基环树森林中每棵基环树树上最大独立集之和。

不会树的最大独立集可以看[模板题](https://www.luogu.com.cn/problem/P1352)。考虑环上的一条边 $(u,v)$，这两个点一定不能同时取得，则用这两个点为根跑树形 dp，记为 $f_{0/1,u},g_{0/1,v}$，则贡献为 $\max(f_{0,u},g_{0,v})$，可以证明环上任意边贡献相同。$AKB212$, '图论', array['基环树', '环', '树', '图论'], null, null, 'knowledge'),
('world-needs-sunday', 'col-graph-dag-shortest-path', 'DAG 最短路（拓扑排序）', $AKB213$## 算法原理

对于**有向无环图（DAG）**，求单源最短路可以通过**拓扑排序**在 $O(n+m)$ 时间内完成，比 Dijkstra 的 $O(m \log n)$ 更快，且能处理**负权边**（只要图中没有环）。

### 核心思想

在 DAG 中，所有路径都沿着拓扑序单向延伸。当处理节点 $u$ 时，所有能到达 $u$ 的前驱节点都已经被处理完毕，因此 $u$ 的最短距离已经确定，可以直接用它去松弛后继节点。

换句话说：**按拓扑序依次松弛每条边，每个节点入队时其最短路值就已经是最终答案**。

### 为什么正确

- DAG 中没有环，所以存在拓扑序
- 对于任意边 $u \to v$，在拓扑序中 $u$ 一定出现在 $v$ 之前
- 当处理 $u$ 时，$dis[u]$ 已经是从源点到 $u$ 的最短距离（所有到达 $u$ 的路径都已被考虑）
- 用 $dis[u]$ 松弛 $v$，即考虑了经过 $u$ 到达 $v$ 的路径
- 当 $v$ 的入度减为 0 时，所有能到达 $v$ 的前驱都已处理完毕，$dis[v]$ 就是最终最短路

## 算法步骤

以 Kahn 拓扑排序为基础，在出队时松弛邻边：

1. **建图**：读入 $n$ 个点、$m$ 条有向边，建邻接表并记录入度
2. **找源点**：入度为 0 的节点即为 DAG 入口（本题假设唯一）
3. **初始化距离**：源点距离为 0，其余为无穷大
4. **拓扑排序 + 松弛**：
   - 入度为 0 的节点入队
   - 取出队首节点 $u$，遍历所有出边 $u \to v$，权值 $w$
   - 松弛：$dis[v] = \min(dis[v], dis[u] + w)$
   - $v$ 的入度减 1，若入度变为 0 则入队
5. **输出结果**：遍历所有节点，输出最短距离

## 逐行代码解析

### 找入口节点

```cpp
int idx = 1;
while (in[idx]) idx++;  // 找到第一个入度为 0 的节点
```

DAG 中入度为 0 的节点是起点。本题假设入口唯一，若有多个源点需全部入队。

### 拓扑排序 + 松弛

```cpp
vector<int> que(n + 5);
vector<long long> dis(n + 1, 1e18);
dis[idx] = 0;
int l = 0, r = 0;
que[r++] = idx;
while (l != r)
{
    int top = que[l++];
    for (pair<int, long long> i : edges[top])
    {
        dis[i.first] = min(dis[top] + i.second, dis[i.first]); // 松弛
        if (!(--in[i.first])) que[r++] = i.first;              // 入度为0则入队
    }
}
```

注意：松弛操作在入度减 1 之前进行，**无论入度是否为 0 都要松弛**。入度减为 0 只是判断该节点是否可以入队（即其所有前驱都已处理完毕）。

## 复杂度分析

- **时间复杂度**：$O(n+m)$
  - 每个节点入队一次、出队一次：$O(n)$
  - 每条边被松弛一次：$O(m)$
  - 比 Dijkstra（$O(m \log n)$）更快，且无需堆
- **空间复杂度**：$O(n+m)$
  - 邻接表：$O(m)$
  - 入度数组、距离数组、队列：$O(n)$

## 适用场景

1. **DAG 上的最短路/最长路**：可以处理负权边（DAG 中无负环）
2. **DAG 上的 DP**：很多 DAG DP 本质上就是拓扑排序上的递推
3. **关键路径**：DAG 最长路的经典应用
4. **有多个源点的情况**：只需将所有入度为 0 的节点初始距离设为 0 并全部入队

## 与其他最短路算法对比

| 算法 | 适用图 | 时间复杂度 | 负权边 | 实现难度 |
|------|--------|-----------|--------|---------|
| Dijkstra（堆优化） | 非负权图 | $O(m \log n)$ | ❌ | 中等 |
| Bellman-Ford | 任意图（无负环） | $O(nm)$ | ✅ | 简单 |
| SPFA | 稀疏图（无负环） | $O(km)$ 平均 | ✅ | 中等 |
| Floyd-Warshall | 任意图（无负环） | $O(n^3)$ | ✅ | 简单 |
| **DAG 拓扑排序** | **DAG** | **$O(n+m)$** | **✅** | **简单** |

DAG 上的最短路是所有最短路算法中**时间复杂度最优**的，前提是图必须是 DAG。

## 常见陷阱与注意事项

1. **必须是 DAG**：有环的图不能用此方法，拓扑排序无法完成
2. **松弛时机**：每条出边都要松弛，不管后继节点入度是否为 0；入度为 0 只是入队条件
3. **多个源点**：如果 DAG 有多个入度为 0 的节点，要全部初始化为距离 0 并入队
4. **数据类型**：路径可能很长，距离数组用 `long long`，无穷大设为 `1e18` 或 `LLONG_MAX`
5. **最长路变体**：把 `min` 改成 `max`、初始值改成 `-INF`，就是 DAG 最长路（关键路径）
6. **不可达节点**：距离仍为无穷大的节点表示从源点不可达，输出 -1

## 扩展：DAG 最长路（关键路径）

只需要改三处即可求 DAG 最长路：
- 距离数组初始化为 $-\infty$
- 源点距离为 $0$
- 松弛条件从 `min` 改为 `max`

```cpp
dis[v] = max(dis[v], dis[u] + w);  // 最长路松弛
```

关键路径问题（项目调度中各活动的最早完成时间）就是 DAG 最长路的典型应用。$AKB213$, '图论', array['图论', '最短路', 'DAG', '拓扑排序', 'Kahn算法'], 'col-graph-shortest-overview', null, 'knowledge'),
