## P4926 [1007] 倍杀测量者

题意：给出 $s$ 个形如

$x_a \ge (k-T) x_b$或者

$(k+T)x_a  > x_b$的不等式以及 $t$ 个 $x_i$ 的值。求最大的 $T$ 使不等式组无解。

注意到 $T$ 有单调性，进行实数二分。然后我们发现这题最大的不同在于加减变成了乘除，取一个 $\log$ 即可转化为加减形式。具体地：

$$
x_a \ge (k-T) x_b \rightarrow x_a-x_b \ge \ln(k-T)\\
(k+T)x_a  > x_b \rightarrow x_a-x_b \ge -\ln(k+T)\\
x_i = c \rightarrow x_i-x_0=\ln(c)
$$

接下来就是板子了。

```cpp
const double eps = 1e-6;
int n, s, t, c;
double b[N], x;
struct node {
	int opt, a, b;
	double k;
} a[N];

inline bool check(double x) {
	SDC<double, N> sdc;
	for (int i = 1; i <= s; i++) {
		if (a[i].opt == 1) sdc.add_ge(a[i].a, a[i].b, log(a[i].k - x));
		else sdc.add_ge(a[i].a, a[i].b, -log(a[i].k + x));
	}
	for (int i = 1; i <= n; i++) {
		if (b[i]) sdc.add_eq(i, 0, log(b[i]));
	}
	return !sdc.solve(n);
}

void _main() {
	double l = 0.0, r = 1e18, res = -1;
	cin >> n >> s >> t;
	for (int i = 1; i <= s; i++) {
		cin >> a[i].opt >> a[i].a >> a[i].b >> a[i].k;
		if (a[i].opt == 1) r = min<double>(r, a[i].k);
	}
	for (int i = 1; i <= t; i++) cin >> c >> x, b[c] = x;
	while (r - l > eps) {
		double mid = (l + r) / 2;
		if (check(mid)) l = mid + eps, res = mid;
		else r = mid - eps;
	}
	if (res == -1) cout << -1;
	else cout << fixed << setprecision(12) << res;
}
```

## P3275 [SCOI2011] 糖果

**本题 SPFA 差分约束并非正解。**

我们用 $x,y$ 表示第 $A,B$ 个小朋友分到的糖果。

1. $x=y$，直接建约束；
2. $x<y$，转化为 $y - x \ge 1$；
3. $x\ge y$，转化为 $x-y \ge 0$；
4. $x>y$，转化为 $x-y \ge 1$；
5. $x \le y$，转化为 $y - x \ge 0$。

同时 $x$ 都是正整数，则 $x-x_0 \ge 1$，其中 $x_0=0$。

```cpp
SDC<int, N> sdc;
int n, m, opt, x, y;

void _main() {
	cin >> n >> m;
	for (int i = 1; i <= m; i++) {
		cin >> opt >> x >> y;
		if (opt == 1) sdc.add_eq(x, y);
		else if (opt == 2) sdc.add_ge(y, x, 1);
		else if (opt == 3) sdc.add_ge(x, y, 0);
		else if (opt == 4) sdc.add_ge(x, y, 1);
		else if (opt == 5) sdc.add_ge(y, x, 0);
	}
	for (int i = 1; i <= n; i++) sdc.add_ge(i, 0, 1);
	if (!sdc.solve(n)) return cout << -1, void();
	long long res = 0;
	for (int i = 1; i <= n; i++) res += sdc[i];
	cout << res;
}
```

SLF+LLL 只有 90pts，正解为 tarjan 缩点 + DAG 上 dp。[双倍经验](https://www.luogu.com.cn/problem/P10935)。

## SP116 INTERVAL - Intervals

这题需要建模了。还是前缀和思想，用 $x_i$ 表示区间 $[0,i]$ 最少选几个数，则对于每条约束，有 $d_{b}-d_a \ge c$。而且每个数要么选，要么不选，这说明 $x_i$ 的差分数组中的元素 $\in \{0,1\}$，即约束 $x_i-x_{i-1} \ge 0$ 和 $x_{i-1}-x_i \ge -1$，然后差分约束即可。细节上，由于本题是 0-index 的，要把下标加一处理。

```cpp
int n, l, r, c;
SDC<int, N> sdc;

void _main(int t) {
	cin >> n; int m = -1;
	sdc.clear();
	for (int i = 1; i <= n; i++) {
		cin >> l >> r >> c, m = max(m, r);
		sdc.add_ge(r + 1, l, c);
	}
	for (int i = 1; i <= m + 1; i++) sdc.add_ge(i, i - 1, 0), sdc.add_ge(i - 1, i, -1);
	sdc.solve(m + 1);
	cout << sdc[m + 1];
	if (t) cout << '\n';
}
```

另外本题有[多倍经验](https://www.luogu.com.cn/discuss/984130)。

## P11453 [USACO24DEC] Deforestation S

和上一题一样建模，用 $pre_i$ 表示选 / 不选的前缀和，有 $pre_r - pre_{l-1} \ge t$，并且 $0 \le pre_i - pre_{i-1} \le 1$。注意下标离散化处理。跑完最长路 $n-pre_n$ 即为答案。

```cpp
SDC<int, N> sdc;
int n, k, d[N], x[N], l, r, c;

void _main() {
	sdc.clear(), memset(d, 0, sizeof(d));
	cin >> n >> k;
	for (int i = 1; i <= n; i++) cin >> x[i], d[i] = x[i];
	sort(d + 1, d + n + 1);
	int m = unique(d + 1, d + n + 1) - d - 1;
	for (int i = 1; i <= n; i++) x[i] = lower_bound(d + 1, d + m + 1, x[i]) - d;
	for (int i = 1; i <= k; i++) {
		cin >> l >> r >> c;
		l = lower_bound(d + 1, d + m + 1, l) - d, r = upper_bound(d + 1, d + m + 1, r) - d - 1;
		sdc.add_ge(r, l - 1, c);
	}
	for (int i = 1; i <= n; i++) sdc.add_ge(i, i - 1, 0), sdc.add_ge(i - 1, i, -1);
	sdc.solve(n);
	cout << n - sdc[n] << '\n';
}
```

## P11232 [CSP-S 2024] 超速检测

这题细节多的一批。样例给了提示每辆车有且仅有一段超速区间，那考虑把这段区间处理出来，分类讨论：

- 若 $a=0$：
  - 若 $v>V$，该车一直超速，超速区间 $[d,L]$；
  - 若 $v \le V$，该车不超速。

- 若 $a > 0$：
  - 若 $v>V$，该车一直超速，超速区间 $[d,L]$；
  - 若该车在 $L$ 处速度 $v' \le V$，该车不超速；
  - 否则，超速区间 $[d + \lfloor \dfrac{V^2-v^2}{2a} \rfloor,L]$。

- 若 $a<0$：
  - 若 $v \le V$，该车不超速。
  - 若该车在 $L$ 处速度 $v' > V$，该车一直超速，超速区间 $[d,L]$；
  - 否则，超速区间 $[d,\min(L,d + \dfrac{V^2-v^2}{2a}))$，可以化作 $[d,\min(L,d + \lceil \dfrac{V^2-v^2}{2a}+d \rceil)]$。

将坐标离散化，第一问跑前缀和即可，第二问与上题相同。但是本题卡 spfa，只有 80pts。第二问正解是贪心。

```cpp
SDC<int, N> sdc;
int n, m, l0, v0, p[N], d[N], pre[N];
struct car {
	int d, v, a, l, r;
	int get(int s) {return v * v + 2 * a * s;}
	void calc() {
		// 分类讨论超速区间起止点
		d++;
		if (a == 0) {  // 匀速
			if (v > v0) l = d, r = l0;
			else l = r = -1;
		} else if (a > 0) {   // 匀加速
			if (v > v0) l = d, r = l0;
			else if (get(l0 - d) <= v0 * v0) l = r = -1;
			else l = d + (v0 * v0 - v * v) / (2 * a) + 1, r = l0;
		} else {   // 匀减速
			if (v <= v0) l = r = -1;
			else if (get(l0 - d) > v0 * v0) l = d, r = l0;
			else l = d, r = min<int>(l0, ceil(d + 1.0 * (v0 * v0 - v * v) / (2 * a) - 1));
		}
	}
} a[N];

void _main() {
	read(n, m, l0, v0); l0++;
	for (int i = 1; i <= n; i++) read(a[i].d, a[i].v, a[i].a), a[i].calc();
	for (int i = 1; i <= m; i++) read(p[i]), d[i] = ++p[i];
	sort(d + 1, d + m + 1);
	int tot = unique(d + 1, d + m + 1) - d - 1;
	for (int i = 1; i <= m; i++) p[i] = lower_bound(d + 1, d + tot + 1, p[i]) - d;

	for (int i = 1; i <= m; i++) pre[p[i]]++;
	for (int i = 1; i <= m; i++) pre[i] += pre[i - 1];
	int cnt = 0;
	for (int i = 1; i <= n; i++) {
		if (a[i].l == -1) continue;
		a[i].l = lower_bound(d + 1, d + tot + 1, a[i].l) - d;
		a[i].r = upper_bound(d + 1, d + tot + 1, a[i].r) - d - 1;
		if (pre[a[i].r] - pre[a[i].l - 1]) cnt++, sdc.add_ge(a[i].r, a[i].l - 1, 1);
	}
	for (int i = 1; i <= m; i++) sdc.add_ge(i, i - 1, 0), sdc.add_ge(i - 1, i, -1);
	sdc.solve(m);
	cout << cnt << ' ' << m - sdc[m] << '\n';

	sdc.clear(), memset(a, 0, sizeof(a)), memset(d, 0, sizeof(d)), memset(p, 0, sizeof(p));
}
```

## P12088 [RMI 2019] 还原 / Restore Arrays

套路类似，对 01 串作前缀和，记作 $pre_i$。则对于每条约束：

- 若 $val=0$，第 $k$ 小元素是 $0$，即至少前 $k$ 小都是 $0$，所以 $pre_{r}-pre_{l-1}\le r-l+1-k$。
- 若 $val=1$，第 $k$ 小元素是 $1$，即至多多 $k-1$ 小都是 $0$，所以 $pre_{r}-pre_{l-1}\ge r-l+1-(k-1)$。

别忘了下标加一和 $0 \le pre_{i}-pre_{i-1} \le 1$。本题卡常，需要用 SLF+LLL 优化的版本。

```cpp
SDC<int, N> sdc;
int n, m, l, r, k, v;

void _main() {
	cin >> n >> m;
	for (int i = 1; i <= m; i++) {
		cin >> l >> r >> k >> v; l++, r++;
		if (v == 0) sdc.add_le(r, l - 1, r - l + 1 - k);
		else sdc.add_ge(r, l - 1, r - l + 1 - (k - 1));
	}
	for (int i = 1; i <= n; i++) sdc.add_ge(i, i - 1, 0), sdc.add_ge(i - 1, i, -1);
	if (!sdc.solve(n)) return cout << -1, void();
	for (int i = 1; i <= n; i++) cout << (sdc[i] > sdc[i - 1]) << ' ';
}
```

## P10941 Cashier Employment

经典前缀和起手，用 $a_i$ 表示第 $i$ 小时开始工作人数，其前缀和记作 $s_i$。

但是我们发现有些约束带三个变量，比如一个人从 20 点开始工作，那就是

$a_{20}+a_{21}+a_{22}+a_{23}+a_0+a_1+a_2+a_3 \ge R(3)$转化为前缀和

$s_{23}-s_{19}+s_3 \ge R(3)$不过写出几个这类约束容易发现带的第三个变量都是 $s_{23}$，再加上本题数据很小，直接枚举 $s_{23}$ 的值即可。这个值也就是答案了。当然可以二分优化枚举。这实际上是断环为链的思想。

细节上注意下标 +1，以及 $s_i-s_{i-1} \ge 0$。

```cpp
int n, x, r[N], cnt[N];

inline bool check(int x) {
	SDC<int, 100> sdc;
	sdc.add_ge(24, 0, x);
	for (int i = 1; i <= 24; i++) {
		sdc.add_ge(i, i - 1, 0), sdc.add_le(i, i - 1, cnt[i]);
		if (i > 8) sdc.add_ge(i, i - 8, r[i]);
		else sdc.add_le(i + 16, i, x - r[i]);
	}
	return sdc.solve(24) && sdc[24] == x;
}

void _main() {
	for (int i = 1; i <= 24; i++) cin >> r[i];
	cin >> n;
	for (int i = 1; i <= n; i++) cin >> x, cnt[x + 1]++;
	for (int i = 0; i <= n; i++) {
		if (check(i)) return cout << i << '\n', void();
	}
	cout << "No Solution\n";
}
```

## P5590 赛车游戏

令 $d_i$ 表示从 $1$ 到 $i$ 的简单路径长度。则对于边 $(u,v,w)$，有 $d_v-d_u=w$，且 $w \in [1,9]$，故 $1 \le d_v-d_u \le 9$。而且每个 $d_i$ 只有一个值，就保证了路径长度相等。

建约束的时候跑 dfs，把在 $1$ 到 $n$ 路径上的边建进来，不在的边随便赋值。

```cpp
SDC<int, N> sdc;
int n, m, u, v;
int tot = 0, head[N];
struct Edge {
	int next, from, to;
} edge[N << 1];
inline void add_edge(int u, int v) {
	edge[++tot].next = head[u], edge[tot].from = u, edge[tot].to = v, head[u] = tot;
}

bool vis[N];
bool dfs(int u) {
	if (u == n) return true;
	bool can = false;
	for (int j = head[u]; j != 0; j = edge[j].next) {
		int v = edge[j].to;
		if (vis[v]) continue;
		vis[v] = true;
		if (dfs(v)) {
			can = true;
			sdc.add_ge(v, u, 1), sdc.add_le(v, u, 9);
		}
		vis[v] = false;
	}
	return can;
}

void _main() {
	cin >> n >> m;
	for (int i = 1; i <= m; i++) {
		cin >> u >> v;
		add_edge(u, v);
	}
	if (!dfs(1)) return cout << -1, void();
	if (!sdc.solve(n)) return cout << -1, void();
	cout << n << ' ' << m << '\n';
	for (int i = 1; i <= m; i++) {
		int u = edge[i].from, v = edge[i].to;
		cout << u << ' ' << v << ' ';
		int d = sdc[v] - sdc[u];
		if (1 <= d && d <= 9) cout << d << '\n';
		else cout << 1 << '\n';
	}
}
```

喜提 60pts。时间瓶颈在 dfs，显然有解的图无环（若有环，多走一圈边权就变了），于是在 dfs 中记忆化一下即可 AC。

```cpp
bool vis[N], can[N];
bool dfs(int u) {
	if (u == n) return can[u] = true;
	bool res = false;
	for (int j = head[u]; j != 0; j = edge[j].next) {
		int v = edge[j].to;
		if (vis[v]) continue;
		vis[v] = true;
		if (can[v] || dfs(v)) {
			res = true;
			sdc.add_ge(v, u, 1), sdc.add_le(v, u, 9);
		}
		vis[v] = false;
	}
	return can[u] = res;
}
```

## P12348 [蓝桥杯 2025 省 A 第二场] 交互

题里给的约束长的就很像标准形式。考虑一下有什么性质。既然 $\min_{l\le x\le r} a_x-\max_{p \le y \le q} a_y \ge ans$，那么对于一个更大的 $a_x$ 和一个更小的 $a_y$，显然 $a_x-a_y \ge ans$。所以一个自然的想法是直接枚举区间中的点一一连边。可以获得 [90pts](https://www.luogu.com.cn/record/219627043) 的高分。

这样的边数有 $O(nk^2)$ 条，其中 $n\le500, k\le100$。我们借鉴一下线段树优化建图中区间往区间连边的思想，建立一个虚点，用 $[l,r]$ 往虚点连边，在从虚点往 $[p,q]$ 连边，边数就被压缩到了 $O(nk)$ 级别。

用不等式解释的话，设虚点为 $h$，则对于约束 $\min_{l\le x\le r} a_x-\max_{p \le y \le q} a_y \ge ans$，则拆成 $a_h-\min_{l\le x\le r} a_x \ge ans$ 和 $\max_{p \le y \le q} a_y-a_h \ge 0$，容易证明这两种约束是等价的。

最后本题即使虚点建边，最坏复杂度也有 $O(nmk)$，只能用 SLF+LLL 优化的版本才能过。

```cpp
SDC<int, N> sdc;
int n, m, l1, r1, l2, r2, x;

void _main() {
	cin >> n >> m;
	for (int i = 1; i <= n; i++) {
		cin >> l1 >> r1 >> l2 >> r2 >> x;
		for (int j = l1; j <= r1; j++) sdc.add_ge(m + i, j, x);
		for (int j = l2; j <= r2; j++) sdc.add_ge(j, m + i, 0);
	}
	if (!sdc.solve(m + n)) return cout << "No Solution", void();
	int mx = sdc[1], mn = sdc[1];
	for (int i = 1; i <= m + n; i++) mx = max(mx, sdc[i]), mn = min(mn, sdc[i]);
	cout << mx - mn;
}
```

## UVA11671 矩阵中的符号 Sign of Matrix

设 $x_i$ 表示第 $i$ 列的增加次数，$y_i$ 表示第 $j$ 列的增加次数，我们发现每个元素的值为 $x_i+y_i$，考虑把 $y_i$ 取相反数，于是对于每个约束：

- `+`：$x_i-y_i \ge 1$；
- `-`：$x_i-y_i \le -1$；
- `=`：$x_i=y_i$。

令 $x_{i+n}=y_i$，先跑差分约束求出一组 $x_i$ 和 $y_i$ 的解。显然将它们同减一个常数仍是一组解。此时要求最小值，则问题转化为：

给定一组数 $x_i$，求出一个数 $c$ 使得 $\sum |x_i-c|$ 最小。

我们把这 $2n$ 个点放到数轴上并两两配对，如图：

![](https://cdn.luogu.com.cn/upload/image_hosting/t6grrbrd.png)

设所求点为 $P$。当 $P$ 位于 $B$ 左侧时，$P$ 向右运动 $d$ 个单位，到 $B, C, D$ 的距离都会减小，到 $a$ 的距离增加，总和减少 $2d$。$P$ 位于 $C$ 右侧同理。而 $P$ 位于 $B, C$ 之间时，$P$ 向右运动 $d$ 个单位，到 $A, B$ 的距离增加 $d$，而到 $C, D$ 的距离减少 $d$，总和不变且保持最小。由此可得，$P$ 在线段 $BC$ 上（包括端点）时最小。

于是有结论：$c$ 是 $x_i$ 的中位数。当然具体到本题，取 $c=x_n$ 即可。

```cpp
SDC<int, N> sdc;
int n, a[N]; char opt;

void _main(int kase) {
	cin >> n;
	if (n == -1) exit(0);
	cout << "Case " << kase << ": ";
	sdc.clear();
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j <= n; j++) {
			cin >> opt;
			if (opt == '+') sdc.add_le(i, j + n, -1);
			else if (opt == '-') sdc.add_ge(i, j + n, 1);
			else if (opt == '0') sdc.add_eq(i, j + n);
		}
	}
	if (!sdc.solve(n << 1)) return cout << "-1\n", void();
	for (int i = 1; i <= (n << 1); i++) a[i] = sdc[i];
	sort(a + 1, a + (n << 1) + 1);
	int res = 0;
	for (int i = 1; i <= (n << 1); i++) res += abs(a[n] - a[i]);
	cout << res << '\n';
}
```

## AT_agc056_c [AGC056C] 01 Balanced

前缀和起手，则 $pre_r-pre_{l-1}=\dfrac{r-l+1}{2}$ 且 $0 \le pre_i-pre_{i-1} \le 1$。但 $n \le 10^6$，直接上 spfa 板子会喜提 TLE。

换个转化，令 $x_i$ 表示 $[1,i]$ 中 $0$ 的个数减去 $1$ 的个数，最小化字典序等价于令 $0$ 尽量多，也就是让 $x_i$ 最小，即 $x$ 字典序最大。

> 如果这里令 $x_i$ 表示 $[1,i]$ 中 $1$ 的个数减去 $0$ 的个数，就变成 $x_i$ 最大，后期最长路不好做。

对于每条约束，有 $x_r=x_{l-1}$。同时 $|x_i-x_{i-1}| = 1$。拆成 $x_i-x_{i-1} \le 1$ 和 $x_{i-1}-x_i \le 1$。此时边权只有 $0$ 和 $1$，双端队列 01-BFS 即可。复杂度 $O(m+n)$。

$x$ 的字典序最大是由差分约束的性质决定的，而观察一下连边有 $(l-1,r,0)$ 和 $(i,i-1,1)$，则对于 $(u,v,w)$ 有 $w=(u-v) \bmod 2$，那就不会出现 $s_i=s_{i-1}$ 的情况了，所以拆分是合理的。

```cpp
int n, m, l, r;
int dis[N];
deque<int> q;
void bfs(int s) {
	memset(dis, 0x3f, sizeof(dis));
	q.emplace_front(s), dis[s] = 0;
	while (!q.empty()) {
		int u = q.front(); q.pop_front();
		for (int j = head[u]; j != 0; j = edge[j].next) {
			int v = edge[j].to, w = edge[j].dis;
			if (dis[v] > dis[u] + w) {
				dis[v] = dis[u] + w;
				(w == 0) ? q.emplace_front(v) : q.emplace_back(v);
			}
		}
	}
}

void _main() {
	cin >> n >> m;
	for (int i = 1; i <= m; i++) {
		cin >> l >> r;
		add_edge(l - 1, r, 0), add_edge(r, l - 1, 0);
	}
	for (int i = 1; i <= n; i++) add_edge(i, i - 1, 1), add_edge(i - 1, i, 1);
	bfs(0);
	for (int i = 1; i <= n; i++) cout << (dis[i] < dis[i - 1]);
}
```$AKB214$, '图论', array['差分约束', '最短路', '负环', 'SPFA'], null, null, 'knowledge'),
('world-needs-sunday', 'col-graph-difference-constraints', '差分约束系统', $AKB215$## 算法原理

差分约束系统是一组形如

$$
x_{v_i}-x_{u_i}\leq w_i \qquad (i=1,2,\dots,m)
$$

的不等式，要求给每个变量 $x$ 赋一个实数（或整数）值，使所有不等式同时成立。它的核心技巧是把每个不等式改写成一条**有向边**，再用最短路算法求解。

把 $x_v-x_u\leq w$ 移项：

$$
x_v\leq x_u+w
$$

这正是最短路的三角不等式。若图中有一条 $u\to v$、边权为 $w$ 的边，那么任意一组最短路距离 $d$ 都满足 $d_v\leq d_u+w$。因此：

- 每条约束 $x_v-x_u\leq w$ 建一条 $u\to v$、权值 $w$ 的边；
- 在图上跑最短路，得到的距离数组就是一组可行解；
- 若图中存在负环，则不等式组无解。

这个建模把「一组不等式是否有解、解是什么」转化成了「图上有无负环、最短路距离是多少」，是把代数问题转化为图问题的典型例子。

## 核心公式 / 状态定义与转移方程

**建模规则**：

$$
x_v-x_u\leq w \quad\Longleftrightarrow\quad \text{建边 } u\to v,\ \text{边权 } w
$$

**三角不等式**：对任意边 $u\to v$、权值 $w$，最短路距离满足

$$
d_v\leq d_u+w
$$

**可行性**：不等式组有解，当且仅当建出的图**不存在负环**。

**超级源点**：为了处理不连通图，可以新建源点 $S$，向每个点连一条权值 $0$ 的边，从 $S$ 跑最短路。等价写法是把所有点的距离初始化为 $0$ 并全部入队。

**最长路版本**：若约束是 $x_v-x_u\geq w$，移项得 $x_u\leq x_v-w$，可以建 $v\to u$、权值 $-w$ 的边跑最短路；也可以保留原方向、把边权取反后跑最长路。两种写法本质相同，注意不要在同一次求解中混用方向。

**解的整体平移**：若 $x$ 是一组解，则 $x+C$（所有分量加同一个常数）仍然是解，因为差分不变。因此差分约束的解不唯一，题目通常只要求输出任意一组；也正因如此，答案可以是负数。

## 逐行代码解析

本篇是纯知识条目，不附完整实现；模板题的完整代码、逐行注释与 SPFA 判负环的写法见 [P5960 【模板】差分约束](#prob-luogu-p5960)。

实现上的关键点只有四个：

1. **建边方向**：$x_v-x_u\leq w$ 建成 $u\to v$，不要把方向写反。
2. **超级源点**：把所有点初始距离设为 $0$ 并全部入队，等价于超级源点向每个点连 $0$ 权边。
3. **负环判定**：SPFA 中记录每个点当前最短路径的边数，边数达到 $n$ 即说明出现负环；Bellman-Ford 则在第 $n$ 轮仍能松弛时判定负环。
4. **输出**：有解输出距离数组，无解输出约定的无解标记（本题为 `NO`）。

如果题目要求整数解，由于边权都是整数，最短路距离自然也是整数，不需要额外处理。

## 复杂度分析

- **SPFA**：最坏 $O(nm)$，即每个点最多入队 $O(n)$ 次、每次扫描其出边；随机数据下通常更快，但可能被特殊数据卡到最坏界。
- **Bellman-Ford**：稳定 $O(nm)$，实现简单，不会被 SPFA 的入队顺序影响。
- **空间复杂度**：邻接表 $O(n+m)$，距离、计数、访问标记各 $O(n)$。

选择哪种算法取决于题目数据：模板题常用 SPFA；如果担心被卡，可以换成 Bellman-Ford 或 SPFA 的队列优化变体。

## 适用场景

- **差分约束模板题**：直接给出若干 $x_v-x_u\leq w$，要求构造一组解或判断无解。
- **区间约束**：把「区间 $[l,r]$ 的和不超过 $w$」写成前缀和之差 $S_r-S_{l-1}\leq w$。
- **调度与时间约束**：任务开始时间之间的先后关系、最短间隔等，常可写成差分形式。
- **最长路约束**：把 $\geq$ 约束转成 $\leq$ 约束，或直接跑最长路。
- **不适合**：约束不是「两个变量之差」的形式（例如 $x+y\leq w$、$xy\leq w$），此时不能直接套差分约束，需要换建模方式。

## 常见陷阱与注意事项

- **方向写反**：$x_v-x_u\leq w$ 对应 $u\to v$，写成 $v\to u$ 会解出另一组不等式。
- **忘记超级源点**：图不连通时，只从某个点出发会漏掉一些变量，输出的解可能不满足未覆盖的约束。
- **负环判定条件错误**：SPFA 中用「最短路径边数 $\geq n$」判负环；Bellman-Ford 中用「第 $n$ 轮仍可松弛」判负环。
- **多测未清空**：邻接表、距离、计数、访问标记和队列都要清空。
- **溢出**：边权叠加后可能超出 32 位整数范围，必要时使用 64 位整数。
- **误以为解唯一**：差分约束的解可以整体平移，输出任意一组即可；不要拿自己的输出与样例逐字比较。
- **把无解与「距离为负」混淆**：距离为负是正常的；只有负环才代表无解。

## 对比与扩展

- **与最短路的关系**：差分约束把不等式组变成最短路问题；所有最短路算法（SPFA、Bellman-Ford、Floyd）都可以用来求解，区别只在复杂度和实现难度。
- **与最长路的关系**：把 $\leq$ 改成 $\geq$、或把边权取反，就可以在最长路与最短路之间转换。
- **与线性规划的关系**：差分约束是线性规划中「变量差的上界」这一特殊情形；一般线性规划需要单纯形等方法，而差分约束可以利用图结构在多项式时间内求解。
- **与 2-SAT 的区别**：2-SAT 处理的是布尔变量的逻辑约束，差分约束处理的是数值变量的大小关系；两者都可以用图建模，但图的含义和求解算法不同。

模板题：[P5960 【模板】差分约束](#prob-luogu-p5960)$AKB215$, '图论', array['差分约束', '最短路', '负环', '图论建模'], null, null, 'knowledge'),
('Xesir', 'col-graph-dijkstra-heap--xesir', 'Dijkstra 最短路（堆优化） · Xesir', $AKB216$## 算法原理

Dijkstra 解决的是**非负权图**上的单源最短路。核心思想一句话：**贪心**。

我们维护一个集合 $S$，表示已经确定了最短路的点。每次从 $S$ 外的点里挑一个**距离起点最近**的点，把它塞进 $S$，然后拿它去松弛所有邻边（即更新别的点到起点的距离估计）。重复这个过程，直到所有点都进了 $S$ 就完事。

为什么贪心能成立？因为边权全是非负的，当前离起点最近的那个点，不可能再绕别的路变得更近；否则那条路线上第一个走出 $S$ 的点，距离一定比它还小，矛盾。这就是 Dijkstra 正确性的证明。

实现上用一个优先队列（堆）来维护"当前待选点"，每次取堆顶就是距离最小的那个，于是"取最小"从 $O(n)$ 降到了 $O(\log n)$。

> 注：这里的前提是"没有负权边"，因为 Dijkstra 遇到负权边时贪心就不成立了（尤其遇到负环会直接把程序跑死 ~~这回忆的旋涡快要把我吞没~~）。一般题目都是没有负权边的，所以 Dijkstra 作为复杂度最优的最短路，依然是首选。

## 核心公式 / 状态定义与转移方程

设 $d[u]$ 为源点到 $u$ 的当前最短距离估计，初始：

$$d[S] = 0, \quad d[v] = +\infty \ (v \neq S)$$

对已确定点 $u$ 的每条出边 $(u \to v, w)$，做松弛：

$$d[v] = \min\big(d[v],\ d[u] + w\big)$$

## 逐行代码解析

下面把整份模板按模块拆开讲，各块按顺序拼起来就是完整代码。

### 模块一：头文件与全局变量

```cpp
#include <bits/stdc++.h>
using namespace std;
const int INF = 1e9;
const int MaxN = 1e6 + 10;
int n,m;
vector<pair<int,int>> G1[MaxN];
vector<int> d, vis;
```

- `const int INF = 1e9`：用 `1e9` 表示"无穷大"，它比 `INT_MAX` 小，和边权相加不容易溢出。
- `G1` 是邻接表，`G1[a]` 存 `a` 的所有出边，每条边是个 `(终点, 权值)` 的 `pair`。
- `d`、`vis` 声明成 `vector` 而没直接开成数组，是为了后面能 `assign` 动态定大小。

### 模块二：堆结点结构体

```cpp
        struct Point{
            int id,x;
            bool operator<(const Point &aa)const{return x>aa.x;}
        };
```

- `Point` 里 `id` 是点编号、`x` 是当前距离。
- 关键在这句 `return x>aa.x;`：重载 `<` 却写成了 `>`，于是距离**小的**反而"更大"，`priority_queue` 默认大根堆在取堆顶时就取到了**距离最小**的点——这是把小根堆"骗"出来的经典写法。

### 模块三：solve 主过程

```cpp
        void solve(int S) {
            d.assign(1e6, INF);
            vis.assign(1e6, 0);
            d[S] = 0;
            priority_queue<Point> q;
            q.push({S, 0});
            while (!q.empty()) {
                auto it= q.top(); q.pop();
                if (vis[it.id]) continue;
                vis[it.id] = 1;
                for (auto t: G1[it.id]) {
                    if (d[it.id] + t.second < d[t.first]) {
                        d[t.first] = d[it.id] + t.second;
                        if (!vis[t.first]) q.push({t.first, d[t.first]});
                    }
                }
            }
        }
```

- `d.assign(1e6, INF)` 把距离数组开成 $10^6$ 并全部置 `INF`，源点再单独设 `0`。
- `if (vis[it.id]) continue;` 是**惰性删除**：同一个点可能被多次入堆，弹出旧条目时它已经被标记过，直接跳过。
- 内层 `if (d[it.id] + t.second < d[t.first])` 就是松弛条件；成功就更新 `d[t.first]`，并且在 `t.first` 还没确定时把新距离压堆。

### 模块四：main 函数

```cpp
int main() {
    cin >> n >> m;
        for(int i = 1; i <= m; i ++) {
            int a, b; cin >> a >> b;
            int c; cin >> c;
            G1[a].push_back({b, c});
        }
        solve(1);
        if(d[n] == INF) cout << -1 << endl;
        else cout << d[n] << endl;
    return 0;
}    
```

- 先读 $n$ 个点、$m$ 条边，每条边按 `a b c`（先两个端点，再权值）读入；这是有向边，所以只加 `G1[a].push_back({b, c})` 一条。
- 从 1 号点开跑 `solve(1)`，最后输出源点到 $n$ 号点的距离，不可达就输出 `-1`。

## 复杂度分析

用优先队列（堆）优化后：

- 时间复杂度：$O((n+m)\log n)$，其中 $n$ 是点数、$m$ 是边数。每条边最多贡献一次入堆，单次堆操作是 $\log n$ 的。
- 空间复杂度：$O(n+m)$，主要是邻接表，再加上 `d`、`vis` 两个数组。

## 适用场景

边权**全场非负**的图（有向、无向都行）求单源最短路。因为复杂度稳定、基本卡不动，OI 里写最短路首选就是它。

## 常见陷阱与注意事项

1. **负权边**：图里有负权边时贪心失效，最短路不保证正确，负环更是直接出错或死循环；这种情况只能上 Bellman-Ford 或 SPFA（判负环）。
2. **`INF` 相加溢出**：本例用 `1e9` 比较安全；若 `INF` 取 `INT_MAX`，`xA + w` 会溢出成负数。
3. **无向图少建边**：代码只建了 `G1[a]` 这一条有向边，无向图还要补 `G1[b].push_back({a, c})`，否则漏掉反向路。
4. **堆里 `Point` 的比较方向**：`operator<` 里写的是 `x>aa.x`，别手滑改成 `x<aa.x`，否则就变成"取最远点"，全错。
5. **写死的数组上限**：这份模板把长度硬编码成 $10^6$（`MaxN` 与 `assign(1e6, ...)`），点编号超过就不能用了，实战要按题目范围改。

## 对比与扩展

和朴素 Dijkstra（$O(n^2)$）比，堆优化在稀疏图（$m \ll n^2$）里快得多；和 SPFA 比，它不会被构造数据卡到 $O(nm)$，代价是没能力处理负权。想求全源最短路可以看 Floyd，想支持负权可以看 Johnson。$AKB216$, '图论', array['图论', '最短路', 'Dijkstra', '堆优化', '优先队列', '单源最短路', '贪心'], 'col-graph-shortest-overview', null, 'knowledge'),
('world-needs-sunday', 'col-graph-dijkstra-heap', 'Dijkstra 最短路（堆优化）', $AKB217$## 算法原理

Dijkstra 算法是求解**非负权图**中单源最短路径的经典算法，基于贪心思想：每一步从未确定最短路的节点中，选取距离源点最近的那个，将其标记为"已确定"，并用它去松弛（relax）相邻节点的距离估计值。

朴素 Dijkstra 的时间复杂度为 $O(V^2)$，在稠密图中表现尚可，但在边数 $E \ll V^2$ 的稀疏图中效率低下。堆优化的核心改进是：用最小堆（优先队列）替代线性扫描来寻找"当前距离最小的未确定节点"，将"取最小"操作从 $O(V)$ 降为 $O(\log V)$。

本代码使用 C++ STL 的 `priority_queue`（配 `greater<>` 比较器实现小根堆），堆中存储 `(distance, node)` 二元组。由于 STL 优先队列不支持 decrease-key 操作（修改堆中已有元素的优先级），代码采用**惰性删除**（lazy deletion）策略：当发现更短路径时直接将新的 `(dist, node)` 压入堆，不修改旧条目；弹出时通过 `vis[]` 数组检查该节点是否已被确定，若已确定则跳过。这样堆中可能存在同一节点的多个过期条目，但每个条目最多被弹出一次，不影响正确性。

松弛操作是 Dijkstra 的核心：对于当前确定的节点 $u$ 及其出边 $(u, v, w)$，若 $A[v] > A[u] + w$，则更新 $A[v] = A[u] + w$ 并将 $(A[v], v)$ 压入堆。这保证了每个节点被确定时，其距离值已经是全局最优（由 Dijkstra 的正确性证明保证：在非负权图中，已确定节点的距离值不会再被更新）。

## 状态定义与转移方程

距离数组定义：

$$A[v] = \text{从源点 } s \text{ 到节点 } v \text{ 的当前最短距离估计值}$$

初始化：

$$A[s] = 0, \quad A[v] = +\infty \quad (v \neq s)$$

松弛转移方程（对当前确定节点 $u$ 的每条出边 $(u, v, w)$）：

$$A[v] = \min\big(A[v],\; A[u] + w\big)$$

松弛条件（仅在距离能改善时执行更新）：

$$\text{if } A[v] > A[u] + w \;\Rightarrow\; A[v] \leftarrow A[u] + w, \;\; \text{push } (A[v], v) \text{ into heap}$$

贪心选择：每轮从堆顶取出 $A$ 值最小的未确定节点 $u$，标记 $vis[u] = \text{true}$，此时 $A[u]$ 即为 $s$ 到 $u$ 的最短路长度（最终答案）。在非负权图中此选择满足最优子结构：已确定节点的距离不会被后续松弛改变。

## 数据结构图示

```
输入示例：n=5, m=7, s=1（有向图）

  边: 1→2(4)  1→3(1)  3→2(2)  2→4(1)  3→4(5)  4→5(1)  2→5(3)

  邻接表：
  edges[1] = {(2,4), (3,1)}
  edges[2] = {(4,1), (5,3)}
  edges[3] = {(2,2), (4,5)}
  edges[4] = {(5,1)}
  edges[5] = {}

  执行过程（堆中 (dist, node)）：

  初始:  A=[INF, 0, INF, INF, INF, INF]
         堆: [(0,1)]

  弹出(0,1), 确定 u=1: 松弛 2→A[2]=4, 松弛 3→A[3]=1
         堆: [(1,3), (4,2)]

  弹出(1,3), 确定 u=3: 松弛 2→A[2]=min(4,1+2)=3, 松弛 4→A[4]=1+5=6
         堆: [(3,2), (4,2)*, (6,4)]      // (4,2) 是过期条目

  弹出(3,2), 确定 u=2: 松弛 4→A[4]=min(6,3+1)=4, 松弛 5→A[5]=3+3=6
         堆: [(4,4), (4,2)*, (6,4)*, (6,5)]

  弹出(4,4), 确定 u=4: 松弛 5→A[5]=min(6,4+1)=5
         堆: [(4,2)*, (5,5), (6,4)*, (6,5)*]

  弹出(4,2)*, vis[2]=true → 跳过（惰性删除）
  弹出(5,5), 确定 u=5: 无出边
  弹出剩余过期条目，全部跳过

  最终:  A=[INF, 0, 3, 1, 4, 5]
         输出: 0 3 1 4 5
```

## 核心操作详解

### 建图：邻接表

- **数据结构**：`vector<vector<pair<int,int>>> edges(n+1)`，`edges[u]` 存储 $u$ 的所有出边，每条边为 `(v, w)` 即 `(终点, 权重)`。
- **关键细节**：使用 `emplace_back(v, w)` 而非 `push_back({v, w})`，直接原地构造 `pair`，略快。图为有向图，仅添加 $u \to v$；若需无向图，应同时添加 `edges[v].emplace_back(u, w)`。

### 堆：小根优先队列

- **声明**：`priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> que`
- **作用**：存储 `(距离, 节点编号)` 对，按距离从小到大排序（`greater<>` 使最大堆行为反转为最小堆）。
- **关键细节**：`pair` 的比较先比较 `.first`（距离），再比较 `.second`（节点编号），因此堆顶始终是当前距离最小的条目。将距离放在 `.first` 是正确排序的关键。

### 惰性删除（Lazy Deletion）

- **策略**：不修改堆中旧条目，弹出时用 `vis[tmp.second]` 判断是否已确定。
- **代码**：`if(vis[tmp.second]) continue;`
- **关键细节**：STL `priority_queue` 不支持 decrease-key，惰性删除是替代方案。堆中同一节点可能有多个条目（旧大值 + 新小值），但每个过期条目弹出时 $O(1)$ 跳过，不影响总复杂度。

### 松弛（Relaxation）

- **条件**：`if(A[i.first] > tmp.first + i.second)`
- **执行**：`A[i.first] = tmp.first + i.second; que.emplace(A[i.first], i.first);`
- **关键细节**：`tmp.first` 是已确定节点 $u$ 的最短距离（非临时值），`i.second` 是边权 $w$。松弛成功后将新距离压入堆。注意松弛前额外检查 `if(vis[i.first]) continue` 跳过已确定节点，减少无效入堆。

## 逐行代码解析

下面把整段程序按逻辑拆成 5 个模块：头文件与全局变量、读入与建图、初始化、Dijkstra 主循环、输出结果。各模块代码按顺序拼接即得到完整的 `.cpp`（注释与空白不计）。

### 模块一：头文件与全局变量

```cpp
#include<bits/stdc++.h>
using namespace std;
const int INF = INT_MAX;
int main()
{
```

- `bits/stdc++.h`：GCC 的万能头文件，竞赛常用，一次包含 STL 全部头文件（含 `<queue>`、`<vector>`、`<climits>`）。
- `const int INF = INT_MAX`：用 `int` 能表示的最大值作为「无穷大」距离。注意它与边权相加可能溢出，见「常见陷阱」。
- 入口 `int main()`：本代码只处理单组数据，所有变量都声明在 `main` 内部，天然避免多组数据忘记清空的问题。

### 模块二：读入与建图

```cpp
    ios::sync_with_stdio(false);          // 关闭 C/C++ 流同步，加速 I/O
    cin.tie(nullptr);cout.tie(nullptr);   // 解绑 cin/cout，进一步加速

    // 小根堆：(距离, 节点)，greater<> 使距离小的在堆顶
    priority_queue<pair<int,int>,vector<pair<int,int>>,greater<pair<int,int>>> que;

    int n,m,s;
    cin >> n >> m >> s;                   // n 个节点，m 条边，源点 s

    vector<int> A(n + 1,INF);             // 距离数组，初始化为 INF
    vector<vector<pair<int,int>>> edges(n + 1);  // 邻接表

    for(int i = 1;i <= m;i++)
    {
        int u,v,w;
        cin >> u >> v >> w;
        edges[u].emplace_back(v,w);       // 有向边 u→v，权重 w
    }
```

- `priority_queue<..., greater<...>>`：STL 优先队列默认是大根堆，加 `greater<>` 反转为小根堆；元素是 `pair<int,int>`，先比 `.first`（距离）再比 `.second`（节点编号），保证距离最小的在堆顶。
- `A` 与 `edges` 都开 `n + 1` 大小、下标从 `1` 用起，与题面「节点编号从 1 开始」一致（下标 0 闲置）。
- `for(int i = 1;i <= m;i++)`：读 `m` 条边，循环上界是边数 `m` 而不是点数 `n`，这是容易写错的地方。
- `edges[u].emplace_back(v,w)`：只加 `u→v` 一条有向边；若为无向图需再加 `edges[v].emplace_back(u,w)`。

### 模块三：初始化

```cpp
    vector<bool> vis(n + 1,false);        // 标记节点是否已确定最短路
    A[s] = 0;                              // 源点距离为 0
    que.emplace(0,s);                     // 将源点入堆
```

- `vis` 记录节点是否「已确定最短路」，初始全 `false`，供堆弹出时的惰性删除使用。
- `A[s] = 0`：源点到自身距离为 0，其余点保持 `INF`（未定）。
- `que.emplace(0,s)`：源点 `(距离0, 节点s)` 入堆作为算法起点；`emplace` 原地构造，比 `push` 少一次拷贝/移动。

### 模块四：Dijkstra 主循环

```cpp
    while(!que.empty())
    {
        pair<int,int> tmp = que.top();    // 取堆顶（距离最小的未处理节点）
        que.pop();

        if(vis[tmp.second]) continue;     // 惰性删除：已确定则跳过
        vis[tmp.second] = true;           // 标记为已确定

        for(pair<int,int> i : edges[tmp.second])  // 遍历 u 的所有出边
        {
            if(vis[i.first]) continue;    // 跳过已确定的邻居

            if(A[i.first] > tmp.first + i.second)  // 松弛条件
            {
                A[i.first] = tmp.first + i.second;  // 更新距离
                que.emplace(A[i.first],i.first);    // 新距离入堆
            }
        }
    }
```

- `pair<int,int> tmp = que.top()`：`tmp.first` 是距离、`tmp.second` 是节点，取当前距离最小的未确定节点。
- `if(vis[tmp.second]) continue`：**惰性删除**的核心——同一节点可能有多个过期条目（如先入 $(4,2)$ 后入 $(3,2)$），弹出旧条目时 `vis` 已为 `true`，直接跳过。
- `if(vis[i.first]) continue`：松弛前跳过已确定的邻居，减少无效入堆。
- `if(A[i.first] > tmp.first + i.second)`：松弛条件，等价于 $A[v] > A[u] + w$；满足时更新 `A` 并把新距离入堆（旧条目不删除，交给惰性删除）。

### 模块五：输出结果

```cpp
    for(int i = 1;i <= n;i++) cout << A[i] << ' ';  // 输出各点最短距离
    return 0;
}
```

- 输出循环上界是点数 `n`、从 `1` 到 `n`，与建图、初始化的下标范围保持一致。
- 不可达节点保持 `A[i] = INF`，会直接输出 `INT_MAX`（即 2147483647）；若题目要求输出 `-1` 等特殊值需额外判断。
- `return 0;` 与 `}`：结束 `main`，对应模块一中 `int main(){` 的收尾。

## 复杂度分析

- **时间复杂度**：建图 $O(m)$。主循环中每个节点最多被确定一次（$V$ 次），每次确定后遍历其所有出边，总松弛次数为 $O(E)$。每次松弛/入堆为 $O(\log V)$，因此总时间为 $O\big((V + E) \log V\big)$。惰性删除使堆中最多有 $E$ 个条目（每条边最多贡献一次入堆），堆操作上限为 $O(E \log E) = O(E \log V)$（因为 $E \le V^2$）。整体为 $O\big((V + E) \log V\big)$。

- **空间复杂度**：邻接表 $O(V + E)$，距离数组 $O(V)$，`vis` 数组 $O(V)$，堆最多 $O(E)$ 个条目。总空间复杂度为 $O(V + E)$。

与朴素 Dijkstra（$O(V^2)$）相比，堆优化在稀疏图（$E \ll V^2$）中显著更优；在稠密图（$E \approx V^2$）中两者接近，朴素版常数更小。与 SPFA（最坏 $O(VE)$）相比，堆优化 Dijkstra 复杂度稳定，不受负权边/构造数据影响（但要求非负权）。

## 适用场景

非负权有向/无向图中求单源最短路。具体包括：无权图可视为所有边权为 $1$ 的特例（但 BFS 更优）；网络延迟问题（节点为服务器，边权为延迟）；最短路径计数（在松弛时额外记录方案数）；分层图最短路（将状态扩展为多维）。常见于竞赛中的最短路模板题（如洛谷 P4779），也是 A* 算法、K 短路等高级算法的基础组件。

## 常见陷阱与注意事项

1. **负权边**：Dijkstra 的正确性依赖于"已确定节点的距离不会被后续更新"。若存在负权边，这一假设被打破：一个已确定的节点可能通过负权边获得更短路径。存在负权时应使用 Bellman-Ford（$O(VE)$）或 SPFA（均摊 $O(kE)$，最坏 $O(VE)$）。
2. **INF 溢出**：`INF = INT_MAX` 时，松弛 `tmp.first + i.second` 可能溢出（`INT_MAX + w` 越界为负数）。若边权较大，应将 `INF` 设为 `1e9` 或 `0x3f3f3f3f`（约 $10^9$，加上边权不溢出），或使用 `long long`。**注**：OI 常规约束下最短路长度 ≤ $(n-1)\cdot w_{\max}$，不会超过 `int`（约 $2.1\times10^9$）——用 `int` 存距离是安全的；真正要防的是「`INF` 本身与边权相加」的溢出，而非路径长度的累加。
3. **无向图建边**：代码构建的是有向图（仅 `edges[u].emplace_back(v,w)`）。若为无向图，需同时添加 `edges[v].emplace_back(u,w)`，否则结果错误。
4. **堆的元素顺序**：`pair` 中距离必须在 `.first`（`emplace(dist, node)`），这样 `greater<>` 才能按距离排序。若误写为 `emplace(node, dist)`，堆会按节点编号排序，完全错误。
5. **重复入堆导致的空间**：惰性删除策略下堆可能膨胀到 $O(E)$ 大小。在极端图（如完全图）中堆占用内存较大，但不会超时。
6. **不可达节点**：未被松弛到的节点 `A[v]` 保持 `INF`。输出时若题目要求特殊处理（如输出 $-1$），需额外判断 `A[i] == INF`。
7. **多组数据**：若有多组测试数据，需在每组开始前清空 `edges`、`vis` 和堆，或将堆和 `vis` 声明在循环内部（如本代码，每组新建）。

## 对比与扩展

与朴素 Dijkstra（$O(V^2)$）相比，堆优化将"取最小"从线性扫描降为堆操作，在稀疏图中效率提升数个数量级；但在稠密图中朴素版常数更小，且可用 `bitset` 优化进一步降低常数。与 SPFA 相比，Dijkstra 复杂度稳定为 $O((V+E)\log V)$，而 SPFA 在构造数据下退化为 $O(VE)$，但 SPFA 支持负权边（Dijkstra 不支持）。与 Floyd（$O(V^3)$）相比，Dijkstra 求单源最短路，Floyd 求全源最短路，适用规模不同。

扩展方向包括：① **多源 Dijkstra**（多源点同时入堆，求各点到最近源点的最短路）；② **分层图最短路**（将节点状态扩展为 $(位置, 层级)$，处理带状态约束的最短路）；③ **K 短路**（在 Dijkstra 基础上用 A* 算法求第 $K$ 短路）；④ **最短路计数**（松弛时若 $A[u] + w = A[v]$ 则 $cnt[v] += cnt[u]$）；⑤ **反图 Dijkstra**（建反图后从终点跑 Dijkstra，用于求各点到终点的最短路，常与正图配合解决最短路相关问题）。若需支持负权边且不引入 SPFA 的不稳定性，可考虑 Johnson 全源最短路算法（用 Bellman-Ford 消除负权后对每个点跑 Dijkstra）。$AKB217$, '图论', array['图论', '最短路', 'Dijkstra', '堆优化', '优先队列', '单源最短路', '贪心'], 'col-graph-shortest-overview', null, 'knowledge'),
('world-needs-sunday', 'col-graph-e-dcc-condensation', '边双连通分量缩点（E-DCC）', $AKB218$## 算法原理

边双连通分量（Edge-Biconnected Component，E-DCC）缩点是**求桥算法的自然延伸**：在 Tarjan 找出所有桥的基础上，把每个极大的"无桥子图"缩成一个"超级点"，用桥连接这些超级点，得到一棵**缩点树**。缩点后，原图中复杂的环和冗余路径被压缩成单个节点，许多问题（如 2-边连通性增强、路径上的桥计数）可以在树上高效解决。

### 边双连通分量的定义

- **边双连通（2-边连通）**：一个无向图是边双连通的，当且仅当它**没有桥**。等价地，任意两点之间至少存在两条**边不相交**的路径。
- **边双连通分量（E-DCC）**：无向图中的极大边双连通子图。"极大"意味着不能再添加任何节点使它仍然边双连通。

直观理解：把图中所有的桥都"剪断"，剩下的每个连通块就是一个边双连通分量。

### 核心思想：Tarjan + 栈划分分量

Tarjan 求桥的过程中，我们可以**利用栈记录 DFS 路径上的节点**。每当发现一条桥（子节点追溯不到父节点），就把栈中从栈顶到子节点的所有节点弹出，它们构成一个边双连通分量。

这与 SCC 缩点的"Tarjan + 栈"思路非常相似，区别在于：
- SCC 缩点判定条件是 `low[v] == dfn[u]`（强连通分量的根）
- E-DCC 缩点判定条件是 `low[v] > dfn[u]`（发现桥，桥的两侧是不同的边双连通分量）

### 缩点的意义

缩点后的图有一个关键性质：**它是一棵树（或森林）**。

证明：假设缩点后的图中有环，那么环上的"超级点"之间可以通过环的两条路径连通，说明这些超级点之间的边都不是桥（因为有替代路径），与桥的定义矛盾。因此缩点后的图无环，是一棵树。

这棵树上的每条边都对应原图中的一座桥。树上任意两点之间的路径，对应原图中这两个边双连通分量之间必须经过的所有桥。

### 算法步骤总览

1. **Tarjan 求桥 + 栈划分**：DFS 遍历，用栈保存路径节点，发现桥时弹出子节点及其以上的所有节点作为一个 E-DCC
2. **逐连通分量收尾**：每个连通分量的 Tarjan 结束后，栈中剩余节点构成该连通分量最靠近根的 E-DCC，立即弹出
3. **构建缩点图**：遍历原图每条边，若两个端点属于不同的 E-DCC，则在缩点图中加一条超级边

## 核心状态定义与转移方程

### 状态定义

| 变量 | 类型 | 含义 |
|------|------|------|
| `dfn[u]` | `int` | 节点 $u$ 的 DFS 时间戳，0 表示未访问 |
| `low[u]` | `int` | 节点 $u$ 及其子树通过最多一条返祖边能到达的最早时间戳 |
| `sk[]` | 数组（栈） | 保存当前 DFS 路径上尚未确定所属分量的节点 |
| `top` | `int` | 栈顶指针 |
| `col[u]` | `int` | 节点 $u$ 所属的边双连通分量编号 |
| `col_cnt` | `int` | 边双连通分量的总数 |
| `ans[k]` | `vector<int>` | 第 $k$ 个边双连通分量包含的所有节点 |
| `e_DCC_edges[k]` | `vector<int>` | 缩点图中第 $k$ 个超级点的邻接表 |
| `tim` | `int` | 时间戳计数器 |
| `cnt` | 局部 | 重边处理计数器（只跳第一条父边） |

### Tarjan 转移规则

与 Tarjan 求桥完全一致：

$$
\text{low}[u] =
\begin{cases}
\text{跳过（第一条父边）} & v = \text{fa} \text{ 且 } \text{cnt} = 0 \\
\min(\text{low}[u], \text{low}[v]) & v \text{ 未访问，递归回溯后} \\
\min(\text{low}[u], \text{dfn}[v]) & v \text{ 已访问（返祖边/重边）}
\end{cases}
$$

### 分量划分规则

当回溯到父节点 $u$ 时，若发现桥 $u$-$v$（$v$ 是子节点）：

$$
\text{low}[v] > \text{dfn}[u] \quad \Longrightarrow \quad \text{弹出栈中 } v \text{ 及其以上节点，构成一个 E-DCC}
$$

弹栈条件为 `while (sk[top] != v)`：`top` 指向栈顶的下一格（即已弹出但未清除的旧数据位置），逐个 `--top` 弹出 $v$ 的所有后代，当 `sk[top] == v` 时说明已弹到 $v$ 自身的位置，循环停止。此时 $v$ 已被弹出并归入该分量，而 $u$ 仍在栈中（属于父侧分量）。

### 缩点图构建规则

对原图每条边 $i$-$j$：

$$
\text{若 } \text{col}[i] \neq \text{col}[j] \text{ 且尚未加边} \quad \Longrightarrow \quad \text{在缩点图中加边 } \text{col}[i] \leftrightarrow \text{col}[j]
$$

用 `vis[v] == u` 标记法避免重复加边（同一个超级点对之间只加一条边）。

## 逐行代码解析

### 全局变量定义

```cpp
vector<vector<int>> edges, ans, e_DCC_edges;  // 原图邻接表 / 各分量节点 / 缩点图邻接表
vector<int> dfn, low, sk, col;                 // 时间戳 / low值 / 栈 / 分量编号
int tim, top, col_cnt;                          // 时间戳 / 栈顶 / 分量数
```

三组邻接表各司其职：
- `edges`：原图的邻接表
- `ans`：`ans[k]` 存第 $k$ 个边双连通分量的所有节点
- `e_DCC_edges`：缩点后的树的邻接表

### 初始化函数

```cpp
void init(int n, int m)
{
	dfn.assign(n + 1, 0);
	low.assign(n + 1, 0);
	edges.assign(n + 1, vector<int>());
	sk.assign(n + 1, 0);
	col.assign(n + 1, 0);
	ans.assign(1, vector<int>());    // ans[0] 占位，分量从 1 开始
	tim = 0;
	top = 0;
	col_cnt = 0;
}
```

注意 `ans.assign(1, vector<int>())` —— `ans` 预留了一个空的第 0 位，因为分量编号从 1 开始，这样 `ans[col_cnt]` 直接对应第 `col_cnt` 个分量。

### 加边函数

```cpp
void add(int u, int v)
{
	edges[u].emplace_back(v);
	edges[v].emplace_back(u);
}
```

无向图双向加边。

### mark 函数（入栈 + 打时间戳）

```cpp
inline void mark(int rt)
{
	dfn[rt] = low[rt] = ++tim;
	sk[top++] = rt;
}
```

将初始化时间戳和入栈操作封装成一个内联函数。新节点被访问时，先打时间戳，再压入栈中——表示这个节点"待分配分量"。

### Tarjan 核心函数

```cpp
void tarjan(int rt, int fa)
{
	int cnt = 0;
	mark(rt);                           // 打时间戳 + 入栈
	for (int i : edges[rt])
	{
		if (fa == i && !cnt)            // 只跳过第一条父边（重边处理）
		{
			++cnt;
			continue;
		}
		if (!dfn[i])                    // 树边：递归 DFS
		{
			tarjan(i, rt);
			low[rt] = min(low[i], low[rt]);
			if (low[i] > dfn[rt])       // 发现桥，划分一个边双连通分量
			{
				++col_cnt;
				ans.emplace_back();
				while (sk[top] != i)    // 弹出到 i 的位置（弹出 i 及其所有后代）
				{
					col[sk[--top]] = col_cnt;
					ans[col_cnt].emplace_back(sk[top]);
				}
			}
		}
		else                             // 返祖边 / 重边
			low[rt] = min(dfn[i], low[rt]);
	}
}
```

逐段解析：

1. **`int cnt = 0;`**：局部重边计数器，只跳过第一条父边。

2. **`mark(rt);`**：打时间戳并入栈。

3. **树边分支 + 桥判定**：
   - `low[i] > dfn[rt]` 表示 $i$ 的子树追溯不到 `rt` 或更早，`rt`-$i$ 是桥
   - 发现桥后，弹出 $i$ 及其所有后代，构成一个边双连通分量
   - `while (sk[top] != i)` —— `top` 指向栈顶的下一格（已弹出但未清除的旧数据位置）。循环体先 `--top` 再处理 `sk[top]`，即从栈顶逐个弹出 $i$ 的后代。当 `sk[top] == i` 时，说明已弹到 $i$ 自身的存储位置（$i$ 本身已在前一轮 `--top` 中被弹出），循环停止。此时 `rt` 仍在栈中，属于父侧分量
   - 弹出时设置 `col[节点] = col_cnt`，并加入 `ans[col_cnt]`

4. **返祖边分支**：用 `dfn[i]` 更新 `low[rt]`，保持 low 的正确定义。

### e_DCC 主流程函数

```cpp
void e_DCC(int n, int m)
{
	for (int i = 1; i <= n; i++)
	{
		if (!dfn[i]) tarjan(i, -1);
		if (top)                       // 每个连通分量结束后立即收尾
		{
			++col_cnt;
			ans.emplace_back();
			while (top)
			{
				col[sk[--top]] = col_cnt;
				ans[col_cnt].emplace_back(sk[top]);
			}
		}
	}

	// 构建缩点图
	e_DCC_edges.assign(col_cnt + 1, vector<int>());
	vector<int> vis(col_cnt + 1, 0);   // 标记数组，防止重复加边
	for (int u = 1; u <= col_cnt; u++)
	{
		for (int i : ans[u])           // 遍历分量 u 中的每个原图节点
		{
			for (int j : edges[i])     // 遍历该节点的所有出边
			{
				int v = col[j];        // 对端节点所属分量
				if (vis[v] == u || u == v) continue;  // 已加过 或 同一分量
				vis[v] = u;
				e_DCC_edges[u].emplace_back(v);
			}
		}
	}
}
```

分为两个阶段：

**阶段一：划分分量**

- 外层循环遍历所有节点，对每个未访问的节点启动 Tarjan
- **关键**：`if (top)` 收尾处理位于 for 循环**内部**，在每个连通分量的 Tarjan 结束后立即执行。栈中剩余的节点构成该连通分量最靠近根的边双连通分量，被弹出作为一个 E-DCC
- 这样做的原因：如果图不连通，多个连通分量的节点会先后入栈。若收尾放在循环外部，所有连通分量的剩余节点会被合并到同一个 E-DCC 中，导致划分错误

**阶段二：构建缩点图**

- 遍历每个超级点 $u$
- 对 $u$ 中的每个原图节点 $i$，遍历 $i$ 的所有出边
- 若对端节点 $j$ 属于另一个分量 $v$，且 $u$ 和 $v$ 之间还没加过边，则在缩点图中加边
- `vis[v] == u` 的技巧：用 $u$ 本身作为时间戳标记，这样每轮只需要一个 `vis` 数组而不需要每次清空

### 主函数

```cpp
int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr); cout.tie(nullptr);
	int n, m;
	cin >> n >> m;
	init(n, m);
	for (int i = 1; i <= m; i++)
	{
		int u, v;
		cin >> u >> v;
		add(u, v);
	}
	e_DCC(n, m);
	cout << "e_DCC缩点后有 " << col_cnt << " 个边双连通分量" << '\n';
	for (int i = 1; i <= col_cnt; i++)
	{
		cout << "超级点" << i << "含有: ";
		for (int j : ans[i]) cout << j << ' ';
		cout << '\n';
		cout << "超级点" << i << "有" << e_DCC_edges[i].size() << "个点连接\n";
		for (int j : e_DCC_edges[i]) cout << j << ' ';
		cout << '\n';
	}
	return 0;
}
```

输出每个超级点包含的节点及其在缩点树中的邻接超级点。

## 复杂度分析

### 时间复杂度：$O(n+m)$

1. **Tarjan 求桥 + 栈划分**：每个节点入栈出栈各一次，每条边处理两次（双向），$O(n+m)$
2. **构建缩点图**：遍历每个分量的每个节点的每条边，总次数等于原图边数的两倍（无向图双向），$O(n+m)$
3. **栈操作**：每个节点恰好入栈一次、出栈一次，$O(n)$

总时间复杂度线性。

### 空间复杂度：$O(n+m)$

- 原图邻接表：$O(n+m)$
- `dfn`、`low`、`col`、`sk`：各 $O(n)$
- `ans`：存储所有节点的分量归属，总共 $O(n)$
- `e_DCC_edges`：缩点树的邻接表，有 `col_cnt - 1` 条边，$O(n)$（树的边数 = 点数 - 1）

## 适用场景

### 适用场景

1. **边双连通分量划分**：找出图中所有的边双连通分量
2. **2-边连通性增强**：给定无向图，求至少添加几条边使图变成 2-边连通（无桥）。答案 = $\lceil \frac{\text{缩点树叶子数}}{2} \rceil$
3. **路径必经边计数**：问两点之间路径上有多少座桥（必经边）。缩点后树上两点路径长度即为答案
4. **网络可靠性**：分析网络中哪些边故障会导致网络分裂，以及网络的"边连通度"结构
5. **图上问题转化为树**：将复杂图问题通过缩点转化为树上问题，利用树的性质（LCA、树形 DP、重链剖分等）高效求解

### 不适用场景

1. **点双连通分量**：需要点双连通分量（割点视角）时，应使用点双连通分量算法
2. **有向图强连通**：有向图的强连通分量用 Tarjan SCC 或 Kosaraju
3. **动态图**：边不断增删的图，缩点需要重建，不适合频繁修改

## 常见陷阱与注意事项

### 1. 弹栈条件用子节点做哨兵

发现桥时，弹栈的条件是 `while (sk[top] != i)`，其中 `i` 是子节点。`top` 指向栈顶的下一格（已弹出但未清除旧数据的位置），循环体先 `--top` 弹出元素，当 `sk[top] == i` 时说明已弹到 $i$ 自身的位置，循环停止。

此时 $i$ 及其所有后代已被弹出并归入该分量，而父节点 $rt$ 仍在栈中，属于父侧分量。

如果误用 `while (sk[top - 1] != rt)`（检查栈顶是否为父节点），在大部分情况下也能正确工作，但语义不够精确——应以子节点为哨兵，确保弹出的恰好是子节点及其后代。

### 2. 逐连通分量收尾（不能放在循环外）

每个连通分量的 Tarjan 结束后，栈中剩余的节点构成该连通分量最靠近根的边双连通分量。收尾代码 `if (top) { ... }` 必须放在外层 for 循环**内部**，在每个 `tarjan(i, -1)` 调用后立即执行。

**如果放在 for 循环外部**（所有 Tarjan 结束后才统一收尾），当图不连通时，多个连通分量的剩余节点会堆积在栈中，最终被合并为同一个 E-DCC，导致划分错误。

### 3. 重边处理与求桥一致

与求桥一样，缩点算法使用 `if (fa == i && !cnt)` 只跳过第一条父边，正确处理重边。如果重边被全部跳过，有重边的两个节点可能被错误地分到不同分量。

### 4. 缩点图的去重

构建缩点图时，同一对超级点之间可能有多条原图边对应（因为原图两个分量之间可能有多座桥）。代码中用 `vis[v] == u` 去重，确保每对超级点之间只加一条边。

如果不去重，缩点图就不是树了（会有重边），后续树上算法可能出错。

### 5. 分量编号从 1 开始

`col_cnt` 从 0 开始，每次发现新分量时 `++col_cnt`，所以分量编号是 $1, 2, \dots, \text{colCnt}$。`ans` 数组也预留了 `ans[0]` 作为占位。

如果下游代码假设分量从 0 开始编号，需要注意调整。

### 6. 图不连通时产生森林

如果原图不连通，缩点后得到的是**森林**（多棵树），每个连通分量对应一棵缩点树。做树上算法时需要遍历所有树的根。

### 7. 栈的大小

代码中 `sk.assign(n + 1, 0)` 预分配了 $n+1$ 的空间，这是足够的——每个节点最多入栈一次。但如果节点编号不是从 1 到 $n$，需要根据实际最大编号调整。

## 对比与扩展

### E-DCC 缩点 vs SCC 缩点

| 对比维度 | E-DCC 缩点（无向图） | SCC 缩点（有向图） |
|----------|---------------------|-------------------|
| 图类型 | 无向图 | 有向图 |
| 核心概念 | 边双连通（无桥） | 强连通（互相可达） |
| 判定条件 | `low[v] > dfn[u]`（桥） | `low[v] == dfn[u]`（分量根） |
| 弹栈方式 | 弹到子节点位置（不含父节点） | 弹到并包含根节点 |
| 缩点后结构 | 树 / 森林（无向） | DAG（有向无环图） |
| 典型应用 | 2-边连通增强、必经边 | 拓扑序 DP、可达性 |

### E-DCC 缩点 vs 点双连通分量（V-DCC）

| 对比维度 | E-DCC（边双） | V-DCC（点双） |
|----------|-------------|-------------|
| 删除对象 | 边（桥） | 顶点（割点） |
| 分量性质 | 任意两点有两条边不相交路径 | 任意两点有两条点不相交路径 |
| 节点归属 | 每个节点恰好属于一个 E-DCC | 割点可属于多个 V-DCC |
| 划分方式 | 删桥后各连通块 | 维护边栈，遇割点弹栈 |
| 缩点后结构 | 树 | 圆方树 |

### 扩展：2-边连通性增强问题

**问题**：给定无向图，至少添加几条边可以使图变成 2-边连通？

**解法**：
1. 求 E-DCC 并缩点，得到一棵树
2. 统计树中度为 1 的节点数（叶子数）$L$
3. 答案 = $\lceil \frac{L}{2} \rceil$

**直觉**：每添加一条边，可以连接两个叶子，使它们的度都变成 2，从而消除两个叶子。最优策略就是两两配对叶子。

### 扩展：圆方树（点双缩点）

边双缩点得到的是普通的树（节点是分量，边是桥）。点双缩点得到的结构更复杂——因为割点属于多个点双连通分量，需要用"圆方树"表示：每个点双连通分量变成一个"方点"，每个割点是"圆点"，圆点和方点之间通过割点的归属关系相连。圆方树也是一棵树，但节点类型有两种。

### 扩展：边三连通分量

比边双连通更强的概念：**边三连通**意味着删除任意两条边图仍然连通。求边三连通分量需要更复杂的算法（如基于链分解的算法），时间复杂度仍是线性但常数更大。$AKB218$, '图论', array['图论', 'Tarjan', '边双连通分量', 'E-DCC', '缩点', '桥'], 'col-graph-scc-overview', null, 'knowledge'),
('Xesir', 'col-graph-floyd--xesir', 'Floyd 全源最短路（三层循环） · Xesir', $AKB219$## 算法原理

Floyd 解决的是**多源最短路**（求任意两点之间的最短路），**边权可正可负**，但不能有负环。

核心思想是**动态规划**：设 $f[k][i][j]$ 表示"只把编号 $1..k$ 的点当作中间点，从 $i$ 到 $j$ 的最短路长度"，初始为 `INF`。转移就是一句话——要么不经过 $k$，要么经过 $k$ 作为中转：

$$f[k][i][j] = \min\big(f[k-1][i][j],\ f[k-1][i][k] + f[k-1][k][j]\big)$$

**特点**：实现极其简单（就三层循环），能处理负权；顺便还能求路径的传递闭包（比如判断两点是否连通）。虽然复杂度比较高，但它一轮就能求出任意两点最短路，适合稠密图、且需要反复查询最短路信息的问题。

## 核心公式 / 状态定义与转移方程

朴素状态（三维）：

$$f[k][i][j] = \min\big(f[k-1][i][j],\ f[k-1][i][k] + f[k-1][k][j]\big)$$

实际代码中把第一维滚动掉，变成 $f[i][j]$：

$$f[i][j] = \min\big(f[i][j],\ f[i][u] + f[u][j]\big)$$

初始化：$f[i][i] = 0$，其余为 `INF`；然后逐条边 `f[a][b] = min(f[a][b], c)`。最后三层循环 $u, x, y$（中转点 $u$ 必须在最外层）。

## 逐行代码解析

下面把整份模板按模块拆开讲，各块按顺序拼起来就是完整代码。

### 模块一：头文件与全局数组

```cpp
#include <bits/stdc++.h>
using namespace std;
int f[210][210];
const int INF=1e9;
```

- `f[210][210]` 就是邻接矩阵，直接在全局开好；`f[i][j]` 表示 $i$ 到 $j$ 的最短路。
- `INF = 1e9` 作无穷大：因为 Floyd 里会出现 `INF + INF`，用 `1e9` 相加约 $2\times10^9$，还在 `int` 范围内不会溢出。

### 模块二：初始化与读边

```cpp
int main(){
   
    int n,m,k;cin >> n >> m>>k;
    for(int i=1;i<=n;i++){
        for(int j=1;j<=n;j++){
            if(i!=j) f[i][j]=INF;
            else f[i][j]=0;
        }
    }
    for(int i = 1; i <= m; i ++) {
        int a, b; cin >> a >> b;
        int c; cin >> c;
        f[a][b]=min(f[a][b],c);
    }
```

- 读入 $n$ 个点、$m$ 条边，以及后面的 $k$ 次询问。
- 初始化：到自己的距离为 `0`，到别人的距离为 `INF`。
- 读边时用 `f[a][b]=min(f[a][b],c)`，这样**重边**会自动取最小那条。这里是有向边，无向图要再补 `f[b][a]`。

### 模块三：Floyd 三层循环

```cpp
    for (int u = 1; u <= n; u++) {
        for (int x = 1; x <= n; x++) {
            for (int y = 1; y <= n; y++) {
                f[x][y] = min(f[x][y], f[x][u] + f[u][y]);
            }
        }
    }
```

- 三层循环，中转点 `u` 在最外层（这点很关键）。
- `f[x][y] = min(f[x][y], f[x][u] + f[u][y])` 就是那句转移：要么不使用中转点 `u`，要么用 `x → u → y` 这条更短的路。

### 模块四：处理询问

```cpp
    for(int i=1;i<=k;i++){
        int x,y;cin>>x>>y;
        if(f[x][y] == INF) cout << "impossible" << endl;
        else cout << f[x][y] << endl;
    }
}
```

- 读 $k$ 次询问，每次读一对 $(x, y)$，查 `f[x][y]`。
- 若仍为 `INF` 说明两点不连通，输出 `"impossible"`，否则输出距离。

## 复杂度分析

- 时间复杂度：$O(n^3)$，三层循环各 $n$ 次，和边数 $m$ 无关。
- 空间复杂度：$O(n^2)$，就是那个邻接矩阵。

## 适用场景

多源（任意两点）最短路、稠密图、需要反复查询最短路信息、求传递闭包等。因为 $O(n^3)$，一般只在 $n$ 比较小（大约几百以内）时用。

## 常见陷阱与注意事项

1. **循环顺序**：中转点那一维必须在最外层，把 `i`、`j` 写在外层会导致用"本轮的中间结果"去更新，答案错误。
2. **`INF` 相加溢出**：转移里有 `f[x][u] + f[u][y]`，若 `INF` 取太大（如 `INT_MAX`）会溢出成负数；用 `1e9` 就比较稳。
3. **重边要取 min**：本代码用 `min(f[a][b], c)`，如果直接赋值就会丢掉更短的边。
4. **无向图少建边**：只写了 `f[a][b]`，无向图还要补 `f[b][a] = f[a][b]`。
5. **负环**：有负环时 Floyd 结果没有意义；可以通过检查 `f[i][i] < 0` 来发现负环。

## 对比与扩展

和跑 $n$ 次 Dijkstra（$O(nm\log n)$）或 Johnson 比，Floyd 代码最短、还能顺带求传递闭包，但只适合小图；和 SPFA/Dijkstra 比，那些是单源，Floyd 是"一次算全源"。要点是：$n$ 小 + 稠密 + 要反复查，就选 Floyd。$AKB219$, '图论', array['图论', '最短路', 'Floyd', '全源最短路', '动态规划', '邻接矩阵', '负权边', '传递闭包'], 'col-graph-shortest-overview', null, 'knowledge'),
('world-needs-sunday', 'col-graph-floyd', 'Floyd-Warshall 全源最短路（传递闭包法）', $AKB220$## 算法原理

Floyd-Warshall 算法（简称 Floyd）解决**全源最短路**（All-Pairs Shortest Path, APSP）问题：给定 $n$ 个节点、$m$ 条边的带权图，求所有节点对 $(i, j)$ 之间的最短距离。与 Johnson 算法不同，Floyd 的核心思想是**动态规划**——通过逐步允许更多节点作为中转点，迭代更新所有节点对的最短路径。

### 核心思想：逐步放宽中转节点

定义 $A^{(k)}[i][j]$ 为从 $i$ 到 $j$，**仅以 $\{1, 2, \ldots, k\}$ 中的节点作为中转点**时的最短距离。则：

- $A^{(0)}[i][j]$：不经过任何中转点，即直接边权 $w(i, j)$（若无边则为 $+\infty$）
- $A^{(k)}[i][j]$：在 $A^{(k-1)}$ 的基础上，考虑是否经过新中转点 $k$

关键洞察：从 $i$ 到 $j$ 的最短路径（只允许 $1..k$ 中转），要么**不经过** $k$（此时就是 $A^{(k-1)}[i][j]$），要么**经过** $k$（此时路径拆成 $i \to k$ 和 $k \to j$ 两段，各自只允许 $1..k-1$ 中转）。由此得到状态转移方程。

### 与其他全源最短路算法的关系

| 特性 | Floyd | Johnson | $n$ 次 Dijkstra |
|---|---|---|---|
| 核心方法 | 动态规划 | 重赋权 + Dijkstra | 逐源 Dijkstra |
| 时间复杂度 | $O(n^3)$ | $O(nm \log n)$ | $O(nm \log n)$ |
| 空间复杂度 | $O(n^2)$ | $O(n^2 + m)$ | $O(n^2 + m)$ |
| 负权边 | 支持 | 支持 | 不支持 |
| 负环检测 | 支持（对角线） | 支持（Bellman-Ford） | 不适用 |
| 适用图密度 | 稠密图 | 稀疏图 | 稀疏图且无负权 |
| 实现难度 | 极简 | 较复杂 | 简单 |

**选择原则**：当 $n$ 较小（$n \le 500$）或图为稠密图（$m$ 接近 $n^2$）时，Floyd 是最优选择；当 $n$ 较大且图为稀疏图时，Johnson 更优。

## 核心公式/状态定义与转移方程

### 状态定义

$$A^{(k)}[i][j] = \text{从 } i \text{ 到 } j \text{ 仅经过 } \{1, 2, \ldots, k\} \text{ 中转的最短距离}$$

### 初始化

$$A^{(0)}[i][j] = \begin{cases} 0 & \text{若 } i = j \\ w(i, j) & \text{若存在边 } (i, j) \\ +\infty & \text{否则} \end{cases}$$

### 状态转移方程

$$A^{(k)}[i][j] = \min\Big(A^{(k-1)}[i][j],\; A^{(k-1)}[i][k] + A^{(k-1)}[k][j]\Big)$$

含义：允许 $k$ 作为中转后，$i \to j$ 的最短距离 = $\min$（不经过 $k$，经过 $k$）。

### 空间优化

注意到 $A^{(k)}$ 只依赖 $A^{(k-1)}$，可以去掉第一维，用**滚动数组**直接在原矩阵上原地更新：

$$A[i][j] = \min\Big(A[i][j],\; A[i][k] + A[k][j]\Big)$$

原地更新之所以正确：更新时 $A[i][k]$ 和 $A[k][j]$ 的值要么是 $A^{(k-1)}$ 的值（本轮还没被更新过），要么是 $A^{(k)}$ 的值（本轮已经更新过）。但 $A^{(k)}[i][k] = A^{(k-1)}[i][k]$（经过 $k$ 再回到 $k$ 不会更短，否则存在负环），因此两者相等，原地更新不影响正确性。

### 最终结果

$$d(i, j) = A^{(n)}[i][j]$$

即允许所有 $n$ 个节点作为中转时的最短距离。

### 负环检测

若存在负环，则负环上的节点 $i$ 满足 $A^{(n)}[i][i] < 0$。因此算法结束后，检查对角线是否有负值即可判断是否存在负环。

## 逐行代码解析

### 第 1 段：输入与邻接矩阵初始化

```cpp
long long INF = 1e17;
int main()
{
    int n, m;
    cin >> n >> m;
    vector<vector<long long>> A(n + 1, vector<long long>(n + 1, INF));
    for (int i = 1; i <= n; i++) A[i][i] = 0;
```

- **`INF = 1e17`**：使用 `long long` 防止加法溢出。$10^{17}$ 远小于 `LLONG_MAX`（约 $9.2 \times 10^{18}$），保证 $A[i][k] + A[k][j]$ 两个 INF 相加不会溢出。
- **邻接矩阵 `A`**：$(n+1) \times (n+1)$，初始化全为 INF。
- **对角线置 0**：$A[i][i] = 0$，表示节点到自身距离为 0。

### 第 2 段：读入边（处理重边与无向图）

```cpp
    for (int i = 1; i <= m; i++)
    {
        int u, v;
        long long w;
        cin >> u >> v >> w;
        if (A[u][v] > w)
        {
            A[u][v] = w;
            A[v][u] = w;
        }
    }
```

- **重边处理**：`if (A[u][v] > w)` 取最小边权。同一对节点间可能有多条边，只保留最短的。
- **无向图**：`A[u][v] = w; A[v][u] = w;` 双向建边。若为有向图，只需 `A[u][v] = w;`。
- **注意**：判断条件 `A[u][v] > w` 而非 `A[u][v] >= w`，这意味着遇到相同权值的多条边时不会重复赋值，但效果一样。

### 第 3 段：Floyd 三重循环（核心）

```cpp
    for (int k = 1; k <= n; k++)
    {
        for (int i = 1; i <= n; i++)
        {
            for (int j = 1; j <= n; j++)
            {
                A[i][j] = min(A[i][j], A[i][k] + A[k][j]);
            }
        }
    }
```

- **外层 `k` 必须在最外**：这保证状态转移的正确性——每一轮 $k$ 都是在"允许 $\{1..k\}$ 中转"的基础上更新。若 $k$ 在内层，会导致路径使用尚未更新完毕的中间结果，得到错误答案。
- **`A[i][j] = min(A[i][j], A[i][k] + A[k][j])`**：状态转移方程的直接实现。
- **原地更新**：直接在 $A$ 上修改，不需要额外矩阵。正确性依赖于 $A^{(k)}[i][k] = A^{(k-1)}[i][k]$ 这一性质（若不存在负环，经过 $k$ 再回到 $k$ 不会更短）。

### 第 4 段：输出结果

```cpp
    for (int i = 1; i <= n; i++)
    {
        for (int j = 1; j <= n; j++)
        {
            cout << A[i][j] << ' ';
        }
        cout << '\n';
    }
    return 0;
}
```

- 输出 $n \times n$ 的最短距离矩阵，第 $i$ 行第 $j$ 列即 $d(i, j)$。
- 若 $A[i][j] = \text{INF}$，输出 $10^{17}$（可根据题目要求改为输出 `-1` 或 `NO`）。
- 若 $A[i][i] < 0$，说明存在经过 $i$ 的负环（本代码未显式检测，但可根据需要添加）。

## 复杂度分析

### 时间复杂度

三重循环，每层 $n$ 次，内部为 $O(1)$ 的 `min` 和加法运算：

$$T(n) = n \times n \times n \times O(1) = O(n^3)$$

与边数 $m$ 无关——无论图是稠密还是稀疏，Floyd 都执行固定 $n^3$ 次操作。

### 空间复杂度

邻接矩阵 $A$ 占用 $O(n^2)$ 空间。无额外数据结构，空间复杂度为 $O(n^2)$。

### 实际性能参考

| $n$ | 操作次数 | 耗时（约） |
|---|---|---|
| 100 | $10^6$ | $< 1$ ms |
| 200 | $8 \times 10^6$ | $\sim 10$ ms |
| 500 | $1.25 \times 10^8$ | $\sim 200$ ms |
| 1000 | $10^9$ | $\sim 2$ s（接近超时边界） |

一般竞赛中 Floyd 适合 $n \le 500$ 的场景。

## 适用场景

### 适合使用 Floyd

- **全源最短路**：需要所有节点对之间的最短距离（而非单源）
- **稠密图**：$m$ 接近 $n^2$，Floyd 的 $O(n^3)$ 不逊于 Johnson 的 $O(nm \log n) = O(n^3 \log n)$
- **$n$ 较小**：$n \le 500$ 时 $O(n^3)$ 可接受
- **存在负权边**：Floyd 天然支持负权边（无负环时）
- **需要检测负环**：结束后检查对角线即可
- **需要传递闭包**：将 `min`/`+` 替换为 `|`/`&`，Floyd 即可计算图的传递闭包（可达性矩阵）

### 不适合使用 Floyd

- **$n$ 很大**（$n > 1000$）：$O(n^3)$ 超时，应选 Johnson 或 $n$ 次 Dijkstra
- **只需单源最短路**：用 Dijkstra/Bellman-Ford 即可，$O(n^3)$ 浪费
- **存在负环且需报告路径**：Floyd 可检测负环但不便于还原具体环
- **稀疏图且 $n$ 中等**：Johnson 的 $O(nm \log n)$ 更优

## 常见陷阱与注意事项

1. **循环顺序：$k$ 必须在最外层**
   - 错误写法：$i \to j \to k$ 或 $j \to i \to k$，会导致某些路径在中间节点尚未充分松弛时就被使用
   - 正确写法：$k \to i \to j$，保证每一轮 $k$ 都是基于"允许 $\{1..k\}$ 中转"的完整更新

2. **INF 大小与溢出**
   - `INF` 不能取 `LLONG_MAX`，否则 `A[i][k] + A[k][j]` 两个 INF 相加溢出
   - 推荐 `INF = 1e17`，既足够大表示"不可达"，又保证两个 INF 相加不溢出 `long long`
   - 若用 `int`，推荐 `INF = 1e9`（$10^9$，两个相加 $2 \times 10^9$ 不超过 `INT_MAX` 约 $2.1 \times 10^9$，但很危险，建议用 `long long`）

3. **无向图 vs 有向图**
   - 本代码处理无向图：`A[u][v] = A[v][u] = w`
   - 若为有向图，删除 `A[v][u] = w;` 即可

4. **重边处理**
   - 输入可能有 $u$ 到 $v$ 的多条边，代码用 `if (A[u][v] > w)` 取最小值
   - 若不处理重边，后读入的边可能覆盖更短的边

5. **自环处理**
   - 初始化 `A[i][i] = 0` 已经处理了自环
   - 若输入包含负自环（$u = v, w < 0$），会被 `if (A[u][v] > w)` 覆盖，导致 $A[i][i] < 0$，这表示负环

6. **负环检测**
   - Floyd 结束后，若 $\exists i: A[i][i] < 0$，则存在负环
   - 本代码未显式检测，可根据题目要求在输出前添加检查

7. **路径还原**
   - Floyd 不直接支持路径还原。若需还原路径，需额外维护一个 `nxt[i][j]` 数组记录中转点
   - 更新时：`if (A[i][k] + A[k][j] < A[i][j]) { A[i][j] = A[i][k] + A[k][j]; nxt[i][j] = k; }`
   - 递归还原路径：$i \to \text{nxt}[i][j] \to j$，对 $i \to \text{nxt}$ 和 $\text{nxt} \to j$ 递归

## 对比与扩展

### Floyd vs Johnson vs Dijkstra×n

| 对比维度 | Floyd | Johnson | Dijkstra $\times n$ |
|---|---|---|---|
| 算法范式 | 动态规划 | 贪心 + 重赋权 | 贪心 |
| 时间复杂度 | $O(n^3)$ | $O(nm \log n)$ | $O(nm \log n)$ |
| 稠密图 ($m \approx n^2$) | $O(n^3)$ ✅ | $O(n^3 \log n)$ | $O(n^3 \log n)$ |
| 稀疏图 ($m \approx n$) | $O(n^3)$ | $O(n^2 \log n)$ ✅ | $O(n^2 \log n)$ ✅ |
| 负权边 | ✅ 支持 | ✅ 支持 | ❌ 不支持 |
| 负环检测 | ✅ 对角线 | ✅ Bellman-Ford | ❌ |
| 实现复杂度 | 极低（4 行核心） | 中等 | 低 |
| 路径还原 | 需额外数组 | Dijkstra 前驱数组 | Dijkstra 前驱数组 |
| 图的存储 | 邻接矩阵 | 邻接表 | 邻接表 |

### 扩展：传递闭包

将 Floyd 的 `min`/`+` 替换为 `|`/`&`，可计算图的**传递闭包**（Transitive Closure）——判断任意两点是否可达：

$$T^{(k)}[i][j] = T^{(k-1)}[i][j] \;\lor\; \big(T^{(k-1)}[i][k] \;\land\; T^{(k-1)}[k][j]\big)$$

代码只需将 `A[i][j] = min(A[i][j], A[i][k] + A[k][j])` 改为 `T[i][j] = T[i][j] | (T[i][k] & T[k][j])`。可用 `bitset` 优化到 $O(n^3 / w)$，其中 $w$ 为字长。

### 扩展：最小环

Floyd 可用于求图中**最小环**（边权和最小的环）。在处理中转点 $k$ 时，对于所有 $i < k$ 和 $j < k$，检查 $A[i][k] + A[k][j] + G[i][j]$（其中 $G$ 是原始边权）是否构成更小的环。时间复杂度仍为 $O(n^3)$。$AKB220$, '图论', array['图论', '最短路', 'Floyd', 'Floyd-Warshall', '全源最短路', '动态规划', '邻接矩阵', '负权边'], 'col-graph-shortest-overview', null, 'knowledge'),
('Fohen', 'col-graph-hld-segtree--fenfeng', '树链剖分（重链剖分+线段树） · Fohen', $AKB221$## 算法原理

树链剖分（Heavy-Light Decomposition，简称 HLD，也称重链剖分）是一种把**树上问题转化为序列问题**的技巧。它本身并不负责维护「和」「最大值」「最小值」等具体信息，它的职责是：**把树上的路径或子树表示成若干个连续的序列区间**，从而能够像维护普通序列一样维护树上的信息。至于这些区间上的信息如何维护，则交给线段树、树状数组或其他合适的数据结构。这里先讲它的思想与直接运用。

**引入**：在线性序列上，区间 $[l,r]$ 是天然连续的一段，可以方便地交给线段树或树状数组处理。但在树上，两个节点之间的路径可能弯来绕去——例如要查询节点 $u$ 到 $v$ 路径上的点权和时，路径上的节点并不对应某个简单的编号区间。一种直接做法是让 $u$、$v$ 不断向上跳到最近公共祖先（LCA），但最坏情况下路径长度可达 $O(n)$，若有 $q$ 次询问，复杂度就可能达到 $O(nq)$。

树链剖分的做法是：把树拆成若干条链，给每条链上的节点重新编号，使同一条链上的节点编号连续。这样就能把任意一条树上路径拆成若干段链，再把每段链转化为一个序列区间，从而用维护序列的方式维护。剖分的方式决定了操作的复杂度，这里介绍**理论复杂度最优、OI 中最常见**的剖分算法——重链剖分。

**策略**：首先任选一个节点作为根，之后树就具有了父子关系、深度、子树等概念。

- 对于每个节点 $u$，在它的所有儿子中选择一个**子树大小最大**的儿子作为 $u$ 的**重儿子**，其余为**轻儿子**；若多个儿子的子树大小相同，任选一个即可。
- 连接 $u$ 与重儿子的边称为**重边**，其他连接父子节点的边称为**轻边**。
- 若干条连续的重边构成一条**重链**；特别地，没有重儿子的节点自身可以看成一条只包含自己的重链。

例如下面的树，若节点 $2$ 的子树最大，则 $1\to2$ 是重边，$1\to3$、$1\to4$ 是轻边；节点 $2,5,6$ 中若 $5$ 是重儿子，则 $2\to5$ 是重边、$2\to6$ 是轻边。

```text
        1
      / | \
     2  3  4
    / \
   5   6
```

得到重链以后，按 DFS 序把节点映射到序列上，就得到了重链剖分的序列。

## 核心公式 / 状态定义与转移方程

树链剖分通常通过两次 DFS 完成，需要维护以下信息：

| 数组 | 含义 |
|------|------|
| `fah[u]` | 节点 $u$ 的父节点 |
| `dep[u]` | 节点 $u$ 的深度 |
| `siz[u]` | 节点 $u$ 的子树大小 |
| `son[u]` | 节点 $u$ 的重儿子 |
| `top[u]` | 节点 $u$ 所在重链的链顶 |
| `seg[u]` | 节点 $u$ 对应到序列的编号 |
| `rev[u]` | 序列上第 $u$ 个位置对应的树上节点，即 `rev[seg[v]] = v` |

前 4 个信息在第一轮 DFS 中计算，后 3 个在第二轮 DFS 中计算。

**第一轮 DFS 的递推**（自底向上）：

$$dep[x] = dep[fah[x]] + 1, \qquad siz[x] = 1 + \sum_{i \in \text{children}(x)} siz[i]$$

重儿子的选择：

$$son[x] = \arg\max_{i \in \text{children}(x)} siz[i]$$

**第二轮 DFS 的编号**（自顶向下）：`seg[0]` 作为计数器，初值为 0，`seg[x] = ++seg[0]`，同时记录反向映射 `rev[seg[0]] = x`。

**轻边至少减半（复杂度保证的核心）**：设 $v$ 是 $u$ 的轻儿子。因为 $v$ 不是重儿子，所以一定存在 $u$ 的某个儿子 $w$ 满足 $siz[w] \ge siz[v]$；同时 $u$ 的子树至少包含 $u$ 自身、子树 $v$ 与子树 $w$。于是：

$$siz[u] \ge 1 + siz[v] + siz[w] \ge 2\,siz[v] + 1$$

也就是说，沿一条轻边向下走时，子树大小至少缩小一半。因此从任意节点向根移动时，最多经过 $O(\log n)$ 条轻边。

**编号后的两条性质**：

1. **同一条重链上的节点连续**：若 $u$、$v$ 在同一条重链上，且 $u$ 是链顶到 $v$ 之间的祖先，则它们对应的编号区间为 $[seg[u], seg[v]]$，链上的一段路径就变成了普通序列上的一段区间。
2. **一棵子树对应连续区间**：由于 DFS 会完整访问完一个节点的子树后才离开，节点 $u$ 的子树对应区间 $[seg[u], seg[u] + siz[u] - 1]$，子树操作无需逐个遍历节点，直接处理一个连续区间即可。这条性质与重边无关，普通 DFS 序也具备；但树链剖分通常同时维护 DFS 序，所以可以统一处理路径和子树问题。

## 逐行代码解析

第一轮 DFS 计算父节点、深度、子树大小与重儿子：

```cpp
void dfs1(int x,int f){
	dep[x]=dep[f]+1;
	fah[x]=f;
	siz[x]=1;
	for(int i:G8[x]){
		if(i==f) continue;
		dfs1(i,x);
		siz[x]+=siz[i];
		if(siz[son[x]]<siz[i]) son[x]=i;
	}
}
```

- `dep[x] = dep[f] + 1`：深度 = 父节点深度 + 1。
- `fah[x] = f`：记录父节点。
- `siz[x] = 1`：子树大小先计入自身，再在循环里累加各子节点的 `siz`。
- `if (i == f) continue;`：跳过父节点，避免在无根树上往回走。
- `if (siz[son[x]] < siz[i]) son[x] = i;`：维护子树大小最大的重儿子；`son` 数组默认初始为 0，叶节点的重儿子保持 0。
- `G8[x]` 为原作者的邻接表（`vector<int> G8[N]`），即节点 $x$ 的所有邻接点。

第二轮 DFS 计算链顶、DFS 序编号与反向映射：

```cpp
//该代码中 seg[0] 表示当前节点数，需初始化为 0
void dfs2(int x,int f) {
	top[x]=f;
	seg[x]=++seg[0];
	rev[seg[0]]=x;
	if(son[x]) dfs2(son[x],f);
	for(int i:G8[x]){
	    if(i!=fah[x]&&i!=son[x]) dfs2(i, i);
	}
}
```

- `top[x] = f`：当前节点所在重链的链顶继承自参数 `f`。
- `seg[x] = ++seg[0]`：`seg[0]` 是全局计数器，先自增再赋值，得到当前节点的 DFS 序编号。
- `rev[seg[0]] = x`：记录反向映射，用于从序列下标找回原节点。
- `if (son[x]) dfs2(son[x], f);`：**先递归重儿子**，让重儿子继承同一链顶，保证重链上的节点 DFS 序连续。
- 轻儿子 `dfs2(i, i)`：轻儿子作为新重链的链顶，各自开一条新链。

## 复杂度分析

- **预处理（两次 DFS）**：每个节点各被访问一次，共 $O(n)$。树链剖分本身的复杂度是 $O(n)$ 的。
- **路径拆分**：由于沿一条轻边向下子树大小至少缩小一半，从任意节点向根移动最多经过 $O(\log n)$ 条轻边；一条路径从两端分别向上跳，因此任意两点之间的路径最多被拆成 $O(\log n)$ 条重链上的连续区间。
- **维护序列的额外开销**：把拆分出的区间交给线段树等数据结构维护时，通常要多一个 $\log$，即路径操作整体 $O(\log^2 n)$；子树操作对应单个连续区间，为 $O(\log n)$。
- **空间复杂度**：`fah`、`dep`、`siz`、`son`、`top`、`seg`、`rev` 各 $O(n)$，总空间 $O(n)$。

## 适用场景

- **树上路径修改/查询**：路径点权和、路径最值等，把路径拆成 $O(\log n)$ 段连续区间后交给线段树处理。
- **子树修改/查询**：利用「子树对应连续区间」的性质，一次区间操作即可完成，无需逐点遍历。
- **统一处理路径与子树问题**：树链剖分同时维护了链上的连续性与子树的连续性，是同时需要路径操作与子树操作时的方便统一方案。
- **维护 LCA**：跳链的过程天然可用于求最近公共祖先（本段未展开，可配合线段树或树状数组使用）。

## 常见陷阱与注意事项

1. **重儿子的选择标准**：用「子树大小最大」选重儿子，若多个儿子子树大小相同任选一个即可；选择标准不影响正确性，只影响重链的划分方式，任何划分方式都保证 $O(\log n)$ 的跳跃次数。
2. **`siz[x]` 要先初始化为 1**：子树大小包含节点自身，漏掉会把叶节点算成 0，导致重儿子选错。
3. **第二轮 DFS 必须先递归重儿子**：`if (son[x]) dfs2(son[x], f)` 要放在遍历轻儿子之前，否则重链上的节点在 DFS 序中不连续，后续区间操作会出错。
4. **叶节点无重儿子的判断**：`son` 数组默认初始为 0，叶节点的 `son[x]` 保持 0，`if (son[x])` 不能省，否则会递归到不存在的节点。
5. **`seg[0]` 计数器需初始化为 0**：`seg[x] = ++seg[0]` 依赖 `seg[0]` 从 0 开始，否则整棵树的编号会整体错位。
6. **根节点的父节点**：`fah[root]` 通常设为自身（或 0），防止第一轮 DFS 中误判；无根树建图时需用 `if (i == f) continue;` 跳过父节点，防止往回走。
7. **反向映射 `rev` 的作用**：当需要从 DFS 序下标找回原节点（如按序建树、单点定位、还原被查询区间的实际节点）时，`rev` 比再跑一遍逆映射更直接。

## 对比与扩展

| 剖分方式 | 选择标准 | 特点 |
|----------|----------|------|
| 重链剖分（HLD） | 子树大小最大的儿子 | 任意路径拆 $O(\log n)$ 段，OI 最常见、最通用 |
| 长链剖分 | 子树深度最大的儿子 | 适合维护与深度相关的信息，如求 $k$ 级祖先 |
| 实链剖分（LCT） | 动态维护 | 支持加边/删边等动态树操作，但常数更大、实现更复杂 |

维护序列的数据结构也可选择：

- **线段树**：支持区间修改/查询，是树链剖分最常用的搭配，路径操作 $O(\log^2 n)$。
- **树状数组**：常数更小，适合只需前缀和、或「单点修改 + 区间求和」等场景，同样可行。

此外，树链剖分相比树上差分更「在线」：树上差分适合离线、批量处理，而树链剖分支持在线查询与修改；当需要同时做路径与子树操作时，树链剖分是更统一的方案。$AKB221$, '图论', array['图论', '树链剖分', '重链剖分', 'HLD', 'DFS序'], null, null, 'knowledge'),
('Xesir', 'col-graph-hld-segtree--xesir', '树链剖分（重链剖分） · Xesir', $AKB222$## 算法原理

~~xkl~~

> 原先的树链剖分主题在线段树位置，然而树剖作为一种图论算法应用很多，不能简单的视为线段树的附庸，故移至此处。

树链剖分（或重链剖分，**HLD**）是一种将树上问题转化为序列问题的技巧。它本身并不负责维护"和""最大值"或"最小值"等具体信息，功能是**把树上的路径或子树表示成若干个连续的序列区间**，以便能够按维护序列的方式维护树上信息。至于这些区间上的信息如何维护，则交给线段树、树状数组或其他合适的数据结构。

### 引入：从序列到树

在线性序列上，区间 $[l,r]$ 是连续的一段，可以很容易地交给线段树或树状数组处理。但在树上，两个节点之间的路径可能弯来弯去。例如要查询节点 $u$ 到节点 $v$ 路径上的点权和，路径上的节点并不对应某个简单的编号区间。一种直接做法是从 $u$ 和 $v$ 不断向上跳到最近公共祖先，但最坏情况下路径长度可能达到 $O(n)$；如果有 $q$ 次询问，复杂度就可能达到 $O(nq)$。

树链剖分的做法是：把树拆成若干条链，给每条链上的节点重新编号，使同一条链上的节点编号连续。这样我们就能把任意一条树上路径拆成若干段链，把每段链转化为一个序列区间，从而用维护序列的方式维护它。显然这种操作的复杂度取决于剖分方式，这里介绍理论复杂度最优、OI 中最常见的剖分算法——重链剖分。

### 重儿子 / 重边 / 重链

首先任选一个节点作为根，之后树就具有了父子关系、深度和子树等概念。

对于每个节点 $u$，在它所有儿子中选择一个子树大小最大的儿子，称为 $u$ 的**重儿子**，剩下的称轻儿子（有多个儿子的子树大小相同，任选一个即可）。连接 $u$ 与重儿子的边称为**重边**，其他连接父子节点的边称为**轻边**；若干条连续的重边构成一条**重链**。特别地，没有重儿子的节点自身可以看成一条只包含自己的重链。

例如：

```text
        1
      / | \
     2  3  4
    / \
   5   6
```

如果节点 $2$ 的子树最大，那么 $1\to2$ 是重边，$1\to3$ 和 $1\to4$ 是轻边；节点 $2,5,6$ 中，若 $5$ 是重儿子，则 $2\to5$ 是重边，而 $2\to6$ 是轻边。得到重链以后，按 DFS 序把它映射到序列上，就得到了重链剖分的序列。

### 为什么轻边不会太多（复杂度证明）

可以证明重链剖分后维护序列信息的复杂度是 $O(n \log n)$，因为剖分后的轻边不会太多，这也是树链剖分能够高效工作的关键。证明如下：

设 $v$ 是 $u$ 的轻儿子。因为 $v$ 不是重儿子，所以一定存在 $u$ 的某个儿子 $w$，满足 $siz[w]\ge siz[v]$。同时，$u$ 的子树至少包含节点 $u$ 自身、子树 $v$ 和子树 $w$，因此可以得到：

$$
siz[u]\ge 1+siz[v]+siz[w]\ge 2siz[v]+1
$$

也就是说，沿着一条轻边向下走时，子树大小至少缩小一半。所以，从任意节点向根移动时，最多经过 $O(\log n)$ 条轻边。由于两点路径可以从两端分别向上跳，因此任意两点之间的路径最多可以被拆成 $O(\log n)$ 条重链上的连续区间——这就是树链剖分的复杂度保证。

> 注：树链剖分的本身复杂度是 $O(n)$ 的，只是维护序列时通常要多一个 $\log$。

## 核心公式 / 状态定义与转移方程

树链剖分通常通过两次 DFS 完成，需要维护以下信息：

| 数组 | 含义 |
|---|---|
| `fah[u]` | 节点 $u$ 的父节点 |
| `dep[u]` | 节点 $u$ 的深度 |
| `siz[u]` | 节点 $u$ 的子树大小 |
| `son[u]` | 节点 $u$ 的重儿子 |
| `top[u]` | 节点 $u$ 所在重链的链顶 |
| `seg[u]` | 节点 $u$ 对应到序列的编号 |
| `rev[u]` | 序列上第 $u$ 个位置对应的树上节点，即 $rev[seg[v]]=v$ |

其中前 $4$ 个信息在第一个 DFS 中计算，后 $3$ 个信息在第二轮 DFS 中计算。

### 两条关键性质

树链剖分编号后，有两个特别实用的性质：

1. **同一条重链上的节点连续**（显而易见）。如果 $u$ 和 $v$ 在同一条重链上，并且 $u$ 是链顶到 $v$ 之间的祖先，那么它们对应的编号区间为 $[seg[u],seg[v]]$。因此链上的一段路径就变成了普通序列上的一段区间。
2. **一棵子树对应连续区间**。由于 DFS 会完整访问完一个节点的子树后才离开，所以节点 $u$ 的子树对应 $[seg[u],\ seg[u]+siz[u]-1]$。这意味着子树操作不需要逐个遍历节点，直接处理一个连续区间即可。

> （第 2 条实际上与树链剖分中的"重边"无关，普通 DFS 序也有此性质。但树链剖分通常同时维护 DFS 序，所以可以统一处理路径和子树问题。）

## 逐行代码解析

下面把模板按模块拆开，各模块按顺序拼接起来就是 `codePath` 指向的 `.cpp`。

### dfs1：求深度、父节点、子树大小、重儿子

```cpp
void dfs1(int x,int f){
	dep[x]=dep[f]+1;
	fah[x]=f;
	siz[x]=1;
	for(int i:G8[x]){
		if(i==f) continue;
		dfs1(i,x);
		siz[x]+=siz[i];
		if(siz[son[x]]<siz[i]) son[x]=i;
	}
}
```

- 进入时 `dep[x]=dep[f]+1` 由父亲深度加一，同时记录父节点 `fah[x]`、把 `siz[x]` 初始化为 1（包含自身）。
- 遍历邻接表 `G8[x]`，`i==f` 是回去的父边，直接跳过。
- 先递归 `dfs1(i,x)` 把儿子处理完，再 `siz[x]+=siz[i]` 累加子树大小，并用 `if(siz[son[x]]<siz[i]) son[x]=i` 边累加边挑出子树最大的儿子（重儿子）。
- `son[x]` 初值为 0、`siz[0]=0`，靠这个哨兵让第一个儿子自然成为重儿子候选。

### dfs2：重链优先编号

```cpp
//该代码中 seg[0] 表示当前节点数，需初始化为 0
void dfs2(int x,int f) {
	top[x]=f;
	seg[x]=++seg[0];
	rev[seg[0]]=x;
	if(son[x]) dfs2(son[x],f);
	for(int i:G8[x]){
	    if(i!=fah[x]&&i!=son[x]) dfs2(i, i);
	}
}
```

- 参数 `f` 传入的是**链顶**：第一次调用 `dfs2(root, root)`，之后重儿子继承同一个链顶。
- `seg[0]` 被当作"当前节点计数"使用（所以必须初始化为 0），`++seg[0]` 给它分配新编号，并同步记录反向映射 `rev[seg[0]]=x`。
- **先递归重儿子**（`if(son[x]) dfs2(son[x],f)`），保证同一条重链上的节点编号连续——这是重链剖分能成立的关键顺序。
- 再遍历轻儿子，每个轻儿子自己开一条新链（`dfs2(i, i)`）；循环里要同时判 `i!=fah[x]`（不回父）和 `i!=son[x]`（重儿子已经走过）。

## 复杂度分析

- **预处理**（两次 DFS）：$O(n)$。
- **树链剖分本身**：$O(n)$；任意两点之间的路径最多被拆成 $O(\log n)$ 条重链上的连续区间，单棵子树对应 $1$ 个区间。
- **维护序列信息**：通常要多一个 $\log$（每段区间交给线段树 / 树状数组），原文给出的整体量级是 $O(n\log n)$。
- **空间**：$O(n)$，即七个长度为 $n$ 的数组加上邻接表。

## 适用场景

1. **把树上路径转成序列区间**：路径求和 / 求最值 / 路径加，接上线段树或树状数组即可维护。
2. **子树整体操作**：利用 $[seg[u],\ seg[u]+siz[u]-1]$ 这一个连续区间，子树加 / 子树求和不必逐个遍历节点。
3. **求 LCA**：两端不断向上跳链顶，最后回到同一条链时深度较小的那个点就是 LCA（重链剖分求 LCA 的副产品）。
4. 当树结构**静态**、且需要**在线**处理路径 / 子树问题时，树链剖分是最实用的选择。

## 常见陷阱与注意事项

1. **dfs2 必须先递归重儿子**：否则同一条重链上的节点在序列中不连续，后续区间操作全错。
2. **`seg[0]` 要清零**：模板把 `seg[0]` 当节点计数器用，多组数据 / 多次调用前必须重置为 0。
3. **dfs2 的两个跳过条件缺一不可**：只判 `i!=fah[x]` 会把重儿子再走一遍；只判 `i!=son[x]` 会沿父边爬回去。
4. **`son[x]` 初值为 0、`siz[0]=0`**：靠这个哨兵让第一个儿子自然成为候选；若 0 在题里是合法节点要额外小心。
5. **链顶与节点深度别混**：跳链时比较的是链顶深度 `dep[top[u]]`，不是 `dep[u]`。
6. **同链收尾别漏**：两端跳到同一条链后，用深度较小者作为区间左端 `[seg[u],seg[v]]`，最后这一段不能忘。
7. **递归爆栈**：链状树会让 dfs1 / dfs2 递归到 $O(n)$ 层，必要时开大栈或改写迭代版。

## 对比与扩展

| 方法 | 路径操作 | 子树操作 | 是否在线 | 备注 |
|---|---|---|---|---|
| 树上差分 | 修改 $O(1)$ / 查询 $O(n)$ 重建 | $O(1)$ | 离线 | 不适合在线查询 |
| 树链剖分 + 线段树 | $O(\log^2 n)$ | $O(\log n)$ | 在线 | 静态树首选 |
| Link-Cut Tree | $O(\log n)$ 均摊 | 不直接支持 | 在线动态 | 树结构会变时用 |

