## 逐行代码解析

本页只做导航，不重复贴代码；各子页给出松弛方式、正确性条件与逐行解析。

## 复杂度分析

- Dijkstra 堆优化：$O((n+m)\log n)$。
- Bellman-Ford：$O(nm)$；SPFA 为均摊更快但最坏可退化。
- DAG 最短路：$O(n+m)$。
- Floyd：$O(n^3)$。
- Johnson：一次 Bellman-Ford + $n$ 次 Dijkstra，$O(nm\log n)$。

## 适用场景

- 路径规划、差分约束转最短路。
- 负权/负环判定。
- 全源最短路（$n$ 较小用 Floyd，负权用 Johnson）。
- DAG 上的最长/最短路。

## 常见陷阱与注意事项

- Dijkstra 不能处理负权边。
- SPFA 最坏 $O(nm)$，不要默认它一定快。
- Floyd 的三重循环顺序必须是 `k, i, j`。
- 负环判定：Bellman-Ford 第 $n$ 轮仍能松弛即存在负环。
- 同余最短路的状态是「余数」，不是原图点。

## 对比与扩展

- Dijkstra vs SPFA：非负优先 Dijkstra。
- Floyd vs Johnson：小图 Floyd 更短，稀疏负权图 Johnson 更快。
- 可扩展到 k 短路、分层图最短路。$AKB245$, '图论', array['最短路', 'Dijkstra', 'SPFA', 'Floyd', '总览'], null, null, 'knowledge'),
('Fohen', 'col-graph-spfa--fenfeng', 'Bellman-Ford 批量松弛优化（类SPFA变体） · Fohen', $AKB246$## 算法原理

当图中存在负权边时，Dijkstra 的贪心策略不再成立，需要改用能够处理负权边的算法。一种朴素的暴力做法是 Bellman-Ford：共进行 $n-1$ 轮松弛，每轮尝试所有 $m$ 条边，复杂度为 $O(nm)$。SPFA（Shortest Path Faster Algorithm）是对 Bellman-Ford 的优化，其核心观察是：**只有本轮被更新过的点，才有可能去更新别人**。因此不必每轮盲目遍历全部边，而是用队列维护这些「待处理」的点。

SPFA 的流程是：每次取出队首节点，松弛它的所有出边；如果某个节点被更新成功且当前不在队列中，就把它入队。如此反复，直到队列为空。

负环检测：如果某个点被反复松弛，说明可以无限绕圈使总权值不断减小，此时最短路不存在。常用的判定思路是「某个点的入队次数超过 $n$」，或更精确的「某点最短路径上的边数达到 $n$」。本代码采用后者——维护边数计数 `cnt[v] = cnt[u] + 1`，一旦 `cnt[v] >= n` 即判定存在负环。

## 核心公式 / 状态定义与转移方程

设 $dis[v]$ 为源点到节点 $v$ 的当前最短距离估计值。对于普通单源最短路，初始化为 $dis[s]=0$，其余为 $+\infty$。本代码面向**全图负环检测**，改用「超级源点」初始化：令所有 $dis[i]=0$ 并将所有节点入队，等价于新增一个到所有点连边权为 $0$ 的超级源点。

松弛转移方程（对队首 $u$ 的每条出边 $(u,v,w)$）：

$$dis[v] = \min\big(dis[v],\; dis[u] + w\big)$$

负环判定（边数计数判据）：

$$cnt[v] = cnt[u] + 1 \qquad \Rightarrow \qquad \text{若 } cnt[v] \ge n \text{，则存在负环}$$

## 逐行代码解析

以下按逻辑阶段把整份程序拆成 3 个模块，各模块代码块按顺序拼接即为完整 `.cpp` 源码（与 `codePath` 指向的文件一致）。

### 头文件、常量与全局数组

```cpp
#include <bits/stdc++.h>
using namespace std;
#define int long long
const int N = 2010;
vector<pair<int,int>> e[N];
int dis[N], cnt[N], vis[N];
queue<int> q;
```

- `#define int long long` 把代码中的 `int` 整体替换为 `long long`，避免距离累加溢出；因此入口函数必须写作 `signed main()`。
- `e[N]` 为邻接表，`e[u]` 存节点 $u$ 的所有出边 `(v, w)`；`dis` 存距离、`cnt` 存最短路径边数（判负环用）、`vis` 标记是否在队列中。

### spfa 函数

```cpp
bool spfa(int n) {
    for(int i=1;i<=n;i++){
        dis[i] = 0, vis[i] = 1;
          q.push(i);
    }
    while (!q.empty()) {
        int u = q.front();
        q.pop(), vis[u] = 0;
        for (auto ed : e[u]) {
              int v = ed.first, w = ed.second;
              if (dis[v] > dis[u] + w) {
                dis[v] = dis[u] + w;
                cnt[v] = cnt[u] + 1;  
                if (cnt[v]>=n) return false;
                if (!vis[v]) q.push(v), vis[v] = 1;
            }
        }
    }
    return true;
}
```

- 初始化把所有点的距离置 $0$ 并全部入队，即「超级源点」写法，用于检测全图（不限定从某个源点可达）的负环。
- 松弛成功后执行 `cnt[v] = cnt[u] + 1` 记录当前最短路径的边数；一旦 `cnt[v] >= n` 说明最短路径经过了至少 $n$ 条边，必然存在负环，立即返回 `false`。
- `vis` 表示「是否在队列中」，用于防止同一节点重复入队；出队时置回 `false`。

### main 函数

```cpp
signed main(){
    int n,m;cin >> n >> m;
    memset(dis,0x3f,sizeof dis);
    for(int i = 1; i <= m; i ++) {
        int a, b; cin >> a >> b;
        int c; cin >> c;
        e[a].push_back({b, c});
    }

    if(spfa(n)) cout<<"No";
    else cout<<"Yes";    
    return 0;
}
```

- 读入 $n$ 个节点、$m$ 条边并建图（有向边 $a \to b$，边权 $c$）。
- `spfa(n)` 返回 `true` 表示图中无负环，输出 `No`；返回 `false` 表示存在负环，输出 `Yes`。
- `main` 中的 `memset(dis,0x3f,...)` 会被 `spfa` 内 `dis[i]=0` 的超级源点初始化覆盖，属于冗余语句，不影响结果。

## 复杂度分析

- **时间复杂度**：理论上最坏为 $O(nm)$，但实际运行通常很快（均摊约 $O(km)$，$k$ 为小常数）。在构造数据下可被卡回 $O(nm)$。
- **空间复杂度**：邻接表 $O(n+m)$，辅助数组 `dis`、`cnt`、`vis` 各 $O(n)$，总空间复杂度为 $O(n+m)$。

## 适用场景

- 含负权边的单源最短路（正权图同样适用）。
- 负环检测（判定图中是否存在负环），这是 SPFA 相对 Dijkstra / Bellman-Ford 的关键优势场景。
- 后续的部分图论算法（如费用流）也以 SPFA 为基础。

## 常见陷阱与注意事项

1. **构造数据下易退化**：SPFA 可被卡到 $O(nm)$，容易超时。非负权图上首选 Dijkstra；SPFA 主要用在负权边与负环检测场景。
2. **判负环的标准**：常见有两种等价判据——「入队次数超过 $n$」与「最短路径边数达到 $n$」。本代码用后者（`cnt[v] = cnt[u] + 1`），比入队次数判据更精确、误判更少。
3. **`#define int long long` 与 `signed main`**：宏会把 `int` 整体替换为 `long long`，因此 `main` 必须写成 `signed main()`，否则 `int main()` 会被展开成 `long long main()` 而编译报错。
4. **全图负环检测需要超级源点**：普通 SPFA 只能发现「从源点可达」的负环；若要检测任意位置的负环，需把所有点的距离置 $0$ 并全部入队（即本代码的写法）。
5. **`vis` 语义**：表示「是否在队列中」，用于防止重复入队，与「本轮是否被更新」含义不同，混用会导致逻辑错误。

## 对比与扩展

- **与 Bellman-Ford**：SPFA 是 Bellman-Ford 的队列优化，只处理被更新节点的出边，均摊更快，但最坏复杂度同为 $O(nm)$。
- **与 Dijkstra**：堆优化 Dijkstra 复杂度 $O((n+m)\log n)$ 且稳定，但不支持负权边；SPFA 支持负权但复杂度不稳定。非负权图应首选 Dijkstra。
- **与 Floyd**：Floyd 求全源最短路，复杂度 $O(n^3)$，可处理负权（但不能有负环），与 SPFA 的规模互补。
- **扩展方向**：SLF（Small Label First，用双端队列，距离更小者从队首入队）与 LLL（Large Label Last，队首距离大于平均时移到队尾）加速收敛；差分约束系统（把不等式约束转成最短路并判负环）；费用流（SPFA 找费用最短路 + 增广路）。$AKB246$, '图论', array['图论', '最短路', 'SPFA', 'Bellman-Ford', '负环检测', '队列优化', '负权边'], 'col-graph-shortest-overview', null, 'knowledge'),
('Xesir', 'col-graph-spfa--xesir', 'SPFA 最短路与判负环（队列优化 Bellman-Ford） · Xesir', $AKB247$## 算法原理

最朴素的带负权最短路是 Bellman-Ford：暴力松弛 $n-1$ 轮，每轮把所有边都试一遍，复杂度 $O(nm)$。

SPFA 优化的点很直白：**只有本轮被更新过的点，才有可能去更新别人**。所以拿个队列把这些点维护起来，每次取队首，松弛它的出边；如果某个点被更新且它不在队列里，就把它入队。这样大量不必要的松弛就被省掉了。

**判断负环**：如果某个点入队/被更新的次数超过 $n$，说明存在负环——也就是可以无限绕圈让总权值无限变小，此时最短路根本不存在。

本代码就是一个**带判负环**的版本：它把所有点初始入队（相当于加了一个"超级源点"，这样能检测到任意位置可达的负环），并用 `cnt[v] = cnt[u] + 1` 记录松弛链长度，一旦 `cnt[v] >= n` 就返回"有负环"。

## 核心公式 / 状态定义与转移方程

松弛依然是那套：

$$dis[v] = \min\big(dis[v],\ dis[u] + w\big)$$

负环判定（`cnt[v]` 表示到 `v` 的最短路边数上界）：

$$\text{cnt}[v] \geq n \;\Rightarrow\; \text{存在负环}$$

## 逐行代码解析

下面把整份模板按模块拆开讲，各块按顺序拼起来就是完整代码。

### 模块一：头文件与全局变量

```cpp
#include <bits/stdc++.h>
using namespace std;
#define int long long
const int N = 2010;
vector<pair<int,int>> e[N];
int dis[N], cnt[N], vis[N];
queue<int> q;
```

- `#define int long long` 把全局的 `int` 偷换成 `long long`，代价是常数变大；开了它，`main` 必须写成 `signed main()`。
- `e` 是邻接表，存 `(终点, 权值)`；`cnt` 记录当前松弛链长度（判负环用），`vis` 记录点是否**在队列里**。
- `N = 2010` 是点数上限，直接开死。

### 模块二：spfa 函数

```cpp
bool spfa(int n) {
    for(int i=1;i<=n;i++){
        dis[i] = 0, vis[i] = 1;
          q.push(i);
    }
    while (!q.empty()) {
        int u = q.front();
        q.pop(), vis[u] = 0;
        for (auto ed : e[u]) {
              int v = ed.first, w = ed.second;
              if (dis[v] > dis[u] + w) {
                dis[v] = dis[u] + w;
                cnt[v] = cnt[u] + 1;  
                if (cnt[v]>=n) return false;
                if (!vis[v]) q.push(v), vis[v] = 1;
            }
        }
    }
    return true;
}
```

- 开头把所有点的 `dis` 清成 `0` 并入队——这是"超级源点"式写法，配合判负环能扫描到任意位置的可达负环。
- 出队时 `vis[u] = 0`，表示它已经不在队列里了，之后可以再次入队。
- `if (dis[v] > dis[u] + w)` 是松弛条件；成功后 `cnt[v] = cnt[u] + 1`，`cnt[v] >= n` 直接 `return false`（有负环）。
- 返回 `true` 表示跑完没有负环。

### 模块三：main 函数

```cpp
signed main(){
    int n,m;cin >> n >> m;
    memset(dis,0x3f,sizeof dis);
    for(int i = 1; i <= m; i ++) {
        int a, b; cin >> a >> b;
        int c; cin >> c;
        e[a].push_back({b, c});
    }

    if(spfa(n)) cout<<"No";
    else cout<<"Yes";    
    return 0;
}
```

- `memset(dis,0x3f,sizeof dis)` 把 `dis` 置成 `0x3f3f3f3f`；不过在这份"只判负环"的版本里其实用不上，因为 `spfa` 开头又会把所有 `dis[i]` 清成 0。
- 读 $m$ 条有向边，只加 `e[a].push_back({b, c})` 一条。
- 调用 `spfa(n)`，返回真就输出 `"No"`、否则 `"Yes"`（注意这里的输出是这套题的约定，和"有没有负环"的语义相反，用的时候按题目要求改）。

## 复杂度分析

- 时间复杂度：理论上 $O(nm)$，但实际通常很快。注意在构造数据下会被卡到 $O(nm)$，容易 TLE。
- 空间复杂度：$O(n+m)$，邻接表加上 `dis`、`cnt`、`vis` 几个数组。

## 适用场景

- **有负权边**的最短路（正权也能跑，但没优势）。
- **判断负环**：这是 SPFA 至今仍然"必须存在"的核心场景，很多图论算法的前置步骤都靠它。
- 后续一些图论算法会直接拿 SPFA 当基础组件。

> 警告：因为出题人喜欢卡 SPFA，OI 里它已经逐渐失宠，很多老司机说"SPFA 已死"。所以写最短路首选**一定是 Dijkstra**，~~不然莫名其妙 T 了也不能怪别人辣~~。当然这不代表它啥时候都不能用，判负环这种特殊场景还是得靠它。

## 常见陷阱与注意事项

1. **被构造数据卡爆**：复杂度最坏 $O(nm)$，别在正权最短路题里无脑用它。
2. **判负环的 `cnt` 写法**：`cnt[v] = cnt[u] + 1` 表示路径边数，`cnt[v] >= n` 才说明有负环；写成"入队次数"也行，但两者别混着写。
3. **`#define int long long` 的连带影响**：开了它入口必须是 `signed main()`，否则编译报错。
4. **数组上限 `N = 2010`**：写死的，点数超了要改。
5. **多组数据要清空**：`dis`、`cnt`、`vis`、队列和邻接表每组都要重置。

## 对比与扩展

和 Dijkstra 比，SPFA 能处理负权、能判负环，但复杂度不稳定；和 Floyd 比，SPFA 求单源最短路、能跑大规模稀疏图，Floyd 求全源、只能跑小图。想彻底避开 SPFA 的不稳定性又需要负权，可以考虑 Johnson 重赋权后跑 Dijkstra。$AKB247$, '图论', array['图论', '最短路', 'SPFA', 'Bellman-Ford', '负权边', '判负环', '队列优化'], 'col-graph-shortest-overview', null, 'knowledge'),
('world-needs-sunday', 'col-graph-spfa', 'Bellman-Ford 批量松弛优化（类SPFA变体）', $AKB248$## 算法原理

Bellman-Ford 每轮盲目遍历所有 $m$ 条边做松弛，但只有"上一轮被更新的节点"的出边才可能产生新的松弛。本代码借鉴了 SPFA 的核心思想——**只松弛上轮被更新节点的出边**，但实现方式与标准 SPFA 有本质区别，是一种**批量松弛优化的 Bellman-Ford 变体**。

标准 SPFA 的策略是"即时入队"：松弛成功后立刻将目标节点入队（若不在队列中），处理是流式的，节点一个接一个出队-松弛-入队，没有固定的轮次概念。而本代码采用**批量处理**（batch processing）策略：

- **阶段 1（处理）**：将当前队列中的所有节点处理完毕，松弛它们的出边，用 `vis[]` 标记被更新的节点。同轮内的松弛更新不会立即传播给其他节点。
- **阶段 2（收集）**：处理完后扫描所有节点，将 `vis[]` 为 `true` 的节点统一收集入队，进入下一轮。

这意味着本代码仍保留了 Bellman-Ford 的**轮次结构**（外层 $n-1$ 轮），每轮只处理"上轮被更新的节点"而非全量遍历。与标准 SPFA 相比：

| 特性 | 标准 SPFA | 本代码（批量变体） |
|---|---|---|
| 外层结构 | 无固定轮数，队列空即结束 | 固定 $n-1$ 轮外层循环 |
| 入队时机 | 松弛成功后即时入队 | 批量收集后下一轮入队 |
| 数据结构 | FIFO 队列 (`std::queue`) | 栈式访问 (`que[idx-1]` + `--idx`) |
| `vis` 语义 | "是否在队列中"（防重复入队） | "本轮是否被更新"（收集用） |
| 同轮内更新 | 即时传播给后续节点 | 不传播，下一轮才处理 |

批量策略的特点是：同一轮中一个节点可能被多次松弛更新，但只会在下一轮入队处理一次，避免了同轮内反复入队的冗余。代价是可能比标准 SPFA 多收敛几轮（因为同轮内的更新不会即时传播），但减少了重复入队次数。

算法的外层循环 $n-1$ 次保证正确性：与 Bellman-Ford 相同，最短路最多经过 $n-1$ 条边，每轮使最短路的边数上限 $+1$。提前终止优化：若某轮后队列为空（`!idx`），说明所有距离已收敛，提前退出。

## 状态定义与转移方程

距离数组定义：

$$A[v] = \text{从源点 } s \text{ 到节点 } v \text{ 的当前最短距离估计值}$$

初始化：

$$A[s] = 0, \quad A[v] = +\infty \quad (v \neq s)$$

松弛转移方程（对队列中节点 $u$ 的每条出边 $(u, v, w)$）：

$$A[v] = \min\big(A[v],\; A[u] + w\big)$$

批量收集条件：

$$\text{若 } A[v] \text{ 被更新} \;\Rightarrow\; vis[v] = \text{true}$$

下一轮入队：

$$\text{批量扫描 } vis[] \;\Rightarrow\; \text{将所有 } vis[v] = \text{true} \text{ 的 } v \text{ 入队，并重置 } vis[v] = \text{false}$$

收敛条件：

$$\text{若某轮后队列为空} \;\Rightarrow\; \forall v,\; A[v] \text{ 已收敛} \;\Rightarrow\; \text{break}$$

## 数据结构图示

```
输入示例：n=4, m=5, s=1（有向图）

  边: 1→2(2)  1→3(5)  2→3(1)  3→4(1)  2→4(4)

  邻接表：
  edges[1] = {(2,2), (3,5)}
  edges[2] = {(3,1), (4,4)}
  edges[3] = {(4,1)}
  edges[4] = {}

  执行过程（que 用 idx 指针模拟栈式处理）：

  初始:  A = [INF, 0, INF, INF, INF]
         que = [1], idx = 1

  === 第 1 轮 (t=1) ===
  while(idx): 处理 que[idx-1]=1
    1→2: A[2] = min(INF, 0+2) = 2    vis[2] = true
    1→3: A[3] = min(INF, 0+5) = 5    vis[3] = true
    --idx → idx=0, while 结束

  批量收集: vis[2]=true → que[0]=2, vis[2]=false
            vis[3]=true → que[1]=3, vis[3]=false
            idx = 2

  === 第 2 轮 (t=2) ===
  while(idx): 先处理 que[1]=3
    3→4: A[4] = min(INF, 5+1) = 6    vis[4] = true
    --idx → idx=1
  处理 que[0]=2
    2→3: A[3] = min(5, 2+1) = 3      vis[3] = true  ← 更新！
    2→4: A[4] = min(6, 2+4) = 6      无变化
    --idx → idx=0

  批量收集: vis[3]=true → que[0]=3, vis[3]=false
            vis[4]=true → que[1]=4, vis[4]=false
            idx = 2

  === 第 3 轮 (t=3) ===
  while(idx): 先处理 que[1]=4
    4 无出边
    --idx → idx=1
  处理 que[0]=3
    3→4: A[4] = min(6, 3+1) = 4      vis[4] = true  ← 更新！
    --idx → idx=0

  批量收集: vis[4]=true → que[0]=4, vis[4]=false
            idx = 1

  === 第 4 轮 (t=4, 但 t < n=4 不执行) ===
  实际: t 循环条件 t < n 即 t=1,2,3 共 3 轮
  第 3 轮后 idx=1，但循环已结束

  最终:  A = [INF, 0, 2, 3, 4]
         输出: 0 2 3 4
```

## 核心操作详解

### 建图：邻接表

- **数据结构**：`vector<vector<pair<int,int>>> edges(n+1)`，`edges[u]` 存储 $u$ 的所有出边 `(v, w)`。
- **关键细节**：与 Bellman-Ford 和 Dijkstra 相同的邻接表结构，支持有向图。若为无向图需双向建边。

### 队列：手写数组 + idx 指针

- **数据结构**：`vector<int> que(n+1)` 作为节点队列，`int idx` 作为尾指针。
- **入队**：`que[idx++] = v`；**出队/读取**：`que[idx-1]`（栈式 LIFO 访问）。
- **关键细节**：本代码用 `idx-1` 访问队尾并 `--idx` 弹出，实际是**栈式处理**（LIFO）而非 FIFO 队列。同一批节点按入队逆序处理。标准 SPFA 用 `std::queue` 的 FIFO 顺序。两种顺序不影响正确性，但影响收敛速度。

### 批量处理策略（即时收集优化版）

- **处理阶段**：`while(idx)` 循环弹出并处理当前队列中的所有节点，松弛它们的出边。松弛成功时，若目标节点本轮尚未被标记（`!vis[v]`），则标记 `vis[v] = true` 并立即写入临时数组 `tmp[id++]`。
- **收集阶段**：处理完后检查 `if(!id) break`，若 `id > 0` 则用 `while(id)` 将 `tmp` 中的节点转移到 `que`，同时重置 `vis` 为 `false`。
- **关键细节**：与旧版（扫描 $1 \sim n$ 所有节点收集 `vis[]` 为 `true` 的）相比，优化版在松弛时即时收集到 `tmp` 数组，避免了每轮 $O(n)$ 的全量扫描。`vis` 起去重作用：同一节点同轮内被多次松弛只入 `tmp` 一次，后续松弛跳过（`!vis[i.first]` 为 `false`）。收集阶段复杂度从 $O(n)$ 降为 $O(k)$（$k$ 为本轮更新节点数）。

### 提前终止优化

- **条件**：`if(!id) break`，即处理完当前队列后检查 `tmp` 是否为空。
- **效果**：若本轮松弛中没有任何节点被更新（`id == 0`），说明距离已收敛，提前退出外层循环。检查时机在收集阶段之前，避免无意义的 `while(id)` 转移。

### vis 数组与 tmp 数组的配合

- **处理阶段**：松弛成功时 `if(!vis[v])` 检查，若未被标记则 `vis[v] = true; tmp[id++] = v`，即时收集。
- **收集阶段**：`while(id)` 逐个从 `tmp` 取出节点，重置 `vis[tmp[id-1]] = false` 并放入 `que`。
- **关键细节**：`vis` 的语义是"本轮是否已加入 `tmp`"（去重用），而非旧版的"本轮是否被更新"。区别在于：旧版每次松弛都设 `vis = true`（即使已为 `true`），收集阶段扫描全部 $n$ 个节点；新版用 `!vis[v]` 守卫，只在首次松弛时加入 `tmp`，收集阶段只遍历 `tmp` 中的 $k$ 个节点。与标准 SPFA 中 `vis`/`inQueue` 表示"是否在队列中"也不同。

## 逐行代码解析

以下按逻辑阶段把整份程序拆成 6 个模块，各模块代码块按顺序拼接即还原为 `.cpp` 完整源码（仅多出 `//` 注释）。

### 头文件与常量定义

```cpp
#include<bits/stdc++.h>
using namespace std;
const long long INF = INT_MAX;
```

- 万能头 `bits/stdc++.h` 一次包含全部标准库，竞赛代码常用，代价是编译略慢。
- `INF = INT_MAX` 取 `int` 上限当作「无穷大」；距离数组用 `long long` 存，但 `INF` 偏小，负权边下不可达节点可能被误松弛（详见「常见陷阱」）。

### main 与读入建图

```cpp
int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);cout.tie(nullptr);
    int n,m,s;
    cin >> n >> m >> s;                   // n 个节点，m 条边，源点 s

    vector<vector<pair<int,int>>> edges(n + 1);
    for(int i = 1;i <= m;i++)
    {
        int u,v,w;
        cin >> u >> v >> w;
        edges[u].emplace_back(v,w);       // 有向边 u→v
    }
```

- `ios::sync_with_stdio(false)` + `cin.tie(nullptr)` 关掉与 C 标准 IO 的同步，加速输入输出。
- `edges[u]` 是邻接表，存节点 `u` 的全部出边 `(v, w)`。
- 只 `emplace_back` 一次，建的是**有向边**；节点编号从 `1` 开始，所以数组大小取 `n + 1`。

### 初始化：距离数组与双队列

```cpp
    vector<long long> A(n + 1,INF);        // 距离数组
    vector<int> que(n + 1,0),tmp(n + 1,0); // que: 主队列, tmp: 本轮收集
    vector<bool> vis(n + 1,false);        // 去重标记（本轮是否已入 tmp）
    int idx = 0,id = 0;                   // idx: que 尾指针, id: tmp 尾指针

    A[s] = 0;
    que[idx++] = s;                        // 源点入队
```

- `A` 全部初始化为 `INF`，仅源点 `A[s] = 0`，随后源点入队 `que`。
- `que`/`tmp` 双数组：`que` 存当前轮待处理节点，`tmp` 存本轮被更新的节点；`idx`/`id` 分别是两者的尾指针。
- `vis` 语义是「本轮是否已加入 `tmp`」的去重标记，与标准 SPFA 的「是否在队列中」含义不同。

### 外层循环 + 阶段1：批量处理

```cpp
    for(int t = 1;t < n;++t)              // 最多 n-1 轮
    {
        // === 阶段1：处理当前队列中的所有节点 ===
        while(idx)
        {
            for(pair<int,int> i : edges[que[idx - 1]])  // 遍历栈顶节点的出边
            {
                if(A[i.first] > A[que[idx - 1]] + i.second)  // 松弛条件
                {
                    A[i.first] = A[que[idx - 1]] + i.second;  // 更新距离
                    if(!vis[i.first])        // 本轮尚未收集该节点
                    {
                        vis[i.first] = true;
                        tmp[id++] = i.first;  // 即时收集到 tmp
                    }
                }
            }
            --idx;                        // 弹出（栈式）
        }
```

- 外层 `t < n` 最多跑 `n - 1` 轮，与 Bellman-Ford 一致：最短路最多经过 `n - 1` 条边。
- `que[idx-1]` + `--idx` 是**栈式（LIFO）**弹出，同一批节点按入队逆序处理（标准 SPFA 用 FIFO 队列）。
- 松弛条件 `A[i.first] > A[que[idx-1]] + i.second`：`i.first` 是目标点 `v`，`i.second` 是边权 `w`。
- `if(!vis[i.first])` 去重：同一节点同轮内只入 `tmp` 一次，避免冗余，也让收集阶段无需扫描全部 $n$ 个节点。

### 提前终止 + 阶段2：收集转移

```cpp
        // === 提前终止 ===
        if(!id) break;                     // 本轮无任何更新 → 已收敛

        // === 阶段2：将 tmp 中的节点转移到 que ===
        while(id)
        {
            vis[tmp[id - 1]] = false;      // 重置标记
            que[idx++] = tmp[id - 1];     // 转入主队列
            --id;
        }
    }
```

- `if(!id) break` 放在收集之前：`id == 0` 说明本轮无任何节点被更新，距离已收敛，直接退出，省掉无意义的 `while(id)` 转移。
- `while(id)` 从 `tmp[id-1]` 栈顶取出节点转入 `que`，同时把 `vis` 重置为 `false`，供下一轮重新去重。
- 只遍历本轮更新的 $k$ 个节点（而非旧版全扫 $n$ 个），收集阶段复杂度 $O(k)$。

### 输出

```cpp
    for(int i = 1;i <= n;i++) cout << A[i] << ' ';
    return 0;
}
```

- 按 `1 ~ n` 顺序输出各节点最短距离，空格分隔。
- 不可达节点会输出 `INF`（即 `INT_MAX`），数值很大，读取结果时需留意。

## 复杂度分析

- **时间复杂度**：外层最多 $n-1$ 轮，每轮处理队列中的节点并松弛其出边。处理阶段每轮总松弛次数 $\leq m$（所有边最多被遍历一次），收集阶段遍历 `tmp` 中 $k$ 个节点为 $O(k)$（优化后不再全量扫描 $n$ 个节点）。最坏复杂度为 $O(VE)$（与 Bellman-Ford 相同）。均摊情况下，每个节点入队 $k$ 次（$k$ 通常为 $2\sim3$），总时间为 $O(kE)$。但构造数据可使 $k$ 接近 $V$，退化到 $O(VE)$。
- **空间复杂度**：邻接表 $O(V+E)$，距离数组 $O(V)$，`que` 和 `tmp` 各 $O(V)$，`vis` 数组 $O(V)$。总空间复杂度为 $O(V+E)$。

与 Bellman-Ford（$O(VE)$ 确定性，每轮全量遍历所有边）相比，本代码通过选择性松弛（只处理上轮更新节点的出边）在均摊下更快，但最坏复杂度相同。与标准 SPFA（均摊 $O(kE)$，即时入队 + FIFO）相比，批量策略的均摊常数可能略大（多收敛几轮），但减少了重复入队次数。与堆优化 Dijkstra（$O((V+E)\log V)$）相比，本代码支持负权边但复杂度不稳定。

## 适用场景

含负权边的单源最短路问题、图规模适中且不易被构造数据针对的场景、需要求解差分约束系统。在竞赛中，当题目明确存在负权边时，标准 SPFA 或 Bellman-Ford 是常见选择；若图无非负权边，应优先使用堆优化 Dijkstra 以保证稳定的复杂度。常见于洛谷 P3385 等负权最短路/负环检测题。

注意：本代码为**类 SPFA 的批量松弛变体**，不是标准 SPFA 实现。若需在竞赛中使用标准 SPFA，建议参考下方"对比与扩展"中的标准实现。

## 常见陷阱与注意事项

1. **最坏退化**：本代码和标准 SPFA 一样可被构造数据卡到 $O(VE)$，性能远不如堆优化 Dijkstra 稳定。常见卡法包括：网格图 + 特定边权分布、链式图 + 负权边等。在不确定数据性质时，若无非负权边需求，优先用 Dijkstra。
2. **INF 溢出**：`INF = INT_MAX` 时，当 `A[u] = INF` 且边权 $w$ 为负数，`A[u] + w` 溢出为正大值，可能导致错误的松弛（把不可达节点松弛为 `INT_MAX - 1` 等）。解决方案：① `INF = 1e18`（`long long` 安全范围）；② 松弛前加 `if(A[u] == INF) continue` 跳过未到达节点。**注**：本代码是"队列式 + 只松弛上轮更新节点的出边"，不可达节点永远不会进入 `que`，因此实际上不会拿 `A[i] == INF` 去松弛它的出边——`INF = INT_MAX` 在本实现下是安全的；上述风险只在"遍历全部边"（如 Bellman-Ford 全量扫描）时才真正发生。
3. **负环检测**：本代码外层循环 $n-1$ 次，不检测负环。若存在从源点可达的负环，输出无意义。扩展方法：记录每个节点的入队次数，若某节点入队 $\geq n$ 次，则存在负环。
4. **栈式 vs 队列式处理**：本代码用 `que[idx-1]` + `--idx` 是栈式（LIFO）弹出，标准 SPFA 用 `std::queue` 的 FIFO。两者都正确，但 LIFO 可能改变收敛轮数。若追求标准 SPFA 行为，应改用 FIFO 队列。
5. **批量 vs 即时入队**：本代码的批量策略使同一轮内更新不即时传播，可能多收敛 $1\sim2$ 轮。标准 SPFA 即时入队，收敛通常更快但同轮内可能反复入队。两种策略的最坏复杂度相同。优化版用 `tmp` 数组即时收集避免了旧版每轮 $O(n)$ 的全量扫描，使收集阶段降至 $O(k)$。
6. **vis 语义**：本代码 `vis` 表示"本轮是否已加入 `tmp`"（去重用，防止同轮多次入 `tmp`），而标准 SPFA 的 `vis`/`inQueue` 表示"是否在队列中"（防止重复入队）。混用语义会导致逻辑错误。注意优化版的 `vis` 在 `tmp` 转移到 `que` 时立即重置为 `false`。
7. **节点编号从 1 开始**：代码中节点 $1 \sim n$，数组大小 $n+1$。若题目编号从 $0$ 开始需调整。

## 对比与扩展

与 Bellman-Ford 相比，本代码用选择性松弛（只处理上轮更新节点的出边）避免了全量边遍历，均摊更快但最坏复杂度相同。与标准 SPFA 相比，本代码的批量策略和栈式处理使均摊常数略大，但减少了重复入队。与堆优化 Dijkstra 相比，本代码支持负权边但复杂度不稳定（Dijkstra 稳定 $O((V+E)\log V)$ 但不支持负权）。与 Floyd（$O(V^3)$ 全源最短路）相比，规模互补。

本代码与标准 SPFA 的关键区别已在前文详述（批量处理 + 栈式弹出 + `vis` 语义不同 + 固定 $n-1$ 轮外层循环）。标准 SPFA 的典型实现如下供参考：

```cpp
// 标准 SPFA（FIFO 队列 + 即时入队）
void spfa(int s, int n, vector<vector<pair<int,int>>>& edges, vector<long long>& A) {
    const long long INF = 1e18;
    A.assign(n + 1, INF);
    vector<bool> inQueue(n + 1, false);
    queue<int> q;
    A[s] = 0;
    q.push(s);
    inQueue[s] = true;
    while (!q.empty()) {
        int u = q.front(); q.pop();      // FIFO 出队
        inQueue[u] = false;
        for (auto& [v, w] : edges[u]) {
            if (A[v] > A[u] + w) {       // 松弛
                A[v] = A[u] + w;
                if (!inQueue[v]) {        // 不在队列中才入队
                    q.push(v);
                    inQueue[v] = true;
                }
            }
        }
    }
}
```

标准 SPFA 没有 $n-1$ 轮的外层循环，仅靠队列驱动；松弛成功后即时入队（若不在队列中）；`inQueue` 表示"是否在队列中"而非"本轮是否被更新"。标准 SPFA 在多数场景下收敛更快。

扩展方向包括：① **SLF 优化**（Small Label First）：用双端队列，入队时若新距离 $\leq$ 队首距离则从队首入队，否则从队尾入队，加速收敛；② **LLL 优化**（Large Label Last）：出队时若队首距离 $>$ 队列平均距离，将队首移到队尾，减少大距离节点的无效松弛；③ **负环检测**：记录每个节点的入队次数，超过 $n$ 次则存在负环；④ **差分约束系统**：将不等式约束转化为图的最短路问题，用 SPFA 求解并检测无解（负环）。⑤ **多源最短路**：多源点同时入队，求各点到最近源点的最短距离。

### 负环检测的两种判据与全图负环检测

标准 SPFA 判负环有两种等价思路，本质都是利用「最短路最多经过 $n-1$ 条边」这一事实：

1. **入队次数判据**：维护 `cnt[v]` 表示节点 $v$ 的入队次数，每次成功入队时 `cnt[v]++`；若某次 `cnt[v] >= n`，说明 $v$ 被反复松弛，必然经过负环。
2. **边数计数判据**：维护 `cnt[v]` 表示源点到 $v$ 当前最短路径的**边数**，松弛时执行 `cnt[v] = cnt[u] + 1`；一旦 `cnt[v] >= n` 即判负环。此判据比入队次数更精确、误判更少，是竞赛中更常用的写法。

```
// 边数计数判据（插在标准 SPFA 的松弛处）
if (A[v] > A[u] + w) {
    A[v] = A[u] + w;
    cnt[v] = cnt[u] + 1;
    if (cnt[v] >= n) { /* 存在负环 */ }
    if (!inQueue[v]) { inQueue[v] = true; q.push(v); }
}
```

**全图负环检测**：上述判据只能发现「从源点 $s$ 可达」的负环。若图不连通、需检测**任意位置**的负环，可用「超级源点」初始化：把所有节点 $v$ 的 `dis[v] = 0` 并全部入队，等价于新增一个到所有点连边权为 $0$ 的超级源点 $s_0$，再做一次 SPFA。这样任意负环都从 $s_0$ 可达，即可被检测到。$AKB248$, '图论', array['图论', '最短路', 'Bellman-Ford', '批量松弛', '队列优化', '负权边', '类SPFA'], 'col-graph-shortest-overview', null, 'knowledge'),
('Fohen', 'col-graph-storage--fenfeng', '图的存储 · Fohen', $AKB249$## 算法原理

在程序里表示一张图，需要把「顶点集合」和「边集合」落到具体的数据结构上。OI 中常用的存图方式有四种，核心取舍在于**查一条边是否存在的速度**与**空间消耗**之间的权衡，以及是否方便遍历某个点的所有出边。

设图有 $n$ 个顶点、$m$ 条边，$d(u)$ 表示顶点 $u$ 的度数（出边数）。四种方式分别是：

- **直接存边**：把所有边平铺进一个数组，每条边记录两个端点与权值（如果有）。
- **邻接矩阵**：用二维数组 $\text{adj}[i][j]$ 表示从 $i$ 到 $j$ 是否有边（或边权）。
- **邻接表**：用「数组 + 链表 / vector」存每个点出发的所有边。
- **链式前向星**：本质是用数组模拟单向链表实现的邻接表，比 vector 版邻接表更省内存、常数更小。

## 核心公式 / 状态定义与转移方程

图的存储属于「数据结构选择」问题，没有状态转移方程；它的核心刻画是各方式的空间与查询复杂度。设 $n$ 为顶点数、$m$ 为边数、$d(u)$ 为顶点 $u$ 的度数：

- 直接存边：空间 $O(m)$；查询两点是否有边需遍历全部边，为 $O(m)$。
- 邻接矩阵：空间 $O(n^2)$；查询边 $(i,j)$ 是否存在为 $O(1)$；遍历点 $i$ 的所有出边需扫一整行，为 $O(n)$。
- 邻接表 / 链式前向星：空间 $O(n+m)$；查询边需遍历出边链表，为 $O(d(u))$；遍历出边也是 $O(d(u))$。

## 逐行代码解析

本节给出四种存图方式的**伪代码 / 思想步骤**，用于说明数据结构形态，不要求与任何完整程序一一对应。

### 直接存边

```cpp
struct Edge { int u, v, w; };  // 一条边：起点 u、终点 v、权值 w
vector<Edge> edges;            // 所有边平铺存储
```

思想步骤：

1. 读入每条边，把它追加进 `edges`。
2. 需要遍历所有边时，直接 `for (auto e : edges)`。
3. 若要判断两点是否相连，只能遍历整个数组逐一比对。

### 邻接矩阵

```cpp
int adj[N][N];  // adj[i][j]：从 i 到 j 的边权；0 表示无边
```

思想步骤：

1. 建图时令 `adj[u][v] = w`。
2. 查询 $(u,v)$ 是否有边：直接读 `adj[u][v]`，$O(1)$。
3. 遍历点 $u$ 的所有出边：枚举 $j = 0 \dots n-1$，若 `adj[u][j]` 非零则是一条出边。

### 邻接表

```cpp
vector<pair<int, int>> adj[N];  // adj[i] 存从 i 出发的边，first 是终点，second 是边权
// 不存边权时可简化为 vector<int> adj[N];
```

思想步骤：

1. 加边时执行 `adj[u].push_back({v, w})`（无向图再反向加一次）。
2. 遍历点 $u$ 的所有出边：`for (auto [v, w] : adj[u])`。
3. 只存实际存在的边，适合稀疏图。

### 链式前向星

```cpp
struct Edge { int to, w, next; } edge[M];  // next 指向同一起点的下一条边
int head[N], tot;                           // head[i] 存 i 的第一条出边在 edge 中的下标

void add(int u, int v, int w) {
    edge[++tot] = {v, w, head[u]};          // 新边插到链表头部
    head[u] = tot;
}
```

思想步骤：

1. 每加一条边就「头插」到 `head[u]` 指向的链表上。
2. 遍历点 $u$ 的所有出边：

```cpp
for (int i = head[u]; i; i = edge[i].next) {
    int v = edge[i].to, w = edge[i].w;
    // 处理边 u -> v
}
```

3. 用数组下标模拟指针，避免 vector 扩容与动态分配的开销。

## 复杂度分析

设 $n$ 为顶点数、$m$ 为边数、$d(u)$ 为顶点 $u$ 的度数。四种方式的复杂度对比如下：

| 存储方式 | 空间 | 查询两点是否有边 | 遍历点 $u$ 的出边 |
|---|---|---|---|
| 直接存边 | $O(m)$ | $O(m)$ | $O(m)$ |
| 邻接矩阵 | $O(n^2)$ | $O(1)$ | $O(n)$ |
| 邻接表 | $O(n+m)$ | $O(d(u))$ | $O(d(u))$ |
| 链式前向星 | $O(n+m)$ | $O(d(u))$ | $O(d(u))$ |

由于四种方式各有取舍，不存在统一的「一个算法」复杂度，因此 frontmatter 中复杂度记作「视具体实现」：实际使用时按上表选择对应的空间与查询复杂度。

## 适用场景

- **直接存边**：需要直接基于「边」来操作、或要按边权排序的算法，典型如 Kruskal 求最小生成树。
- **邻接矩阵**：$n$ 很小（如 $n \le 200$）且需要频繁查询两点间边，或需要全源最短路（如 Floyd）。
- **邻接表**：绝大多数情况的首选，适合稀疏图，Dijkstra、SPFA、DFS、BFS 等通用场景都适用。
- **链式前向星**：对性能要求高、或 vector 被卡常的题目。

考场建议：无脑用**邻接表（vector 版）**基本不会错；当 $n$ 很大（如 $10^6$）或 vector 被卡常时，再换成**链式前向星**。邻接矩阵只在 $n \le 200$ 且需要全源最短路时用，直接存边只在 Kruskal 一类按边操作时用。

## 常见陷阱与注意事项

- **邻接矩阵空间爆炸**：空间为 $O(n^2)$，$n$ 稍大（如 $n > 5000$）内存就会溢出，务必只在 $n$ 很小时使用。
- **无向图要加两次边**：邻接表与链式前向星存无向图时，$(u,v)$ 与 $(v,u)$ 都要各加一次，边数组要开到 $2m$ 大小。
- **链式前向星遍历顺序与插入顺序相反**：因为采用「头插」，遍历出的出边顺序与加边顺序相反；若题目对边顺序敏感需注意。
- **不要把查询复杂度当成 $O(1)$**：邻接表查询两点是否有边是 $O(d(u))$，只有邻接矩阵才是 $O(1)$。
- **重边与自环的语义差异**：邻接矩阵会天然「覆盖」重边（只保留最后写入的一条），邻接表 / 直接存边会保留全部；处理带重边的问题时要注意二者语义不同。

## 对比与扩展

- **邻接表 vs 链式前向星**：二者都是「每个点挂出边链表」，复杂度一致；链式前向星用数组模拟链表、常数更小，但写法更繁琐；vector 版邻接表可读性更好、调试更友好。
- **邻接矩阵 vs 邻接表**：矩阵以空间换「$O(1)$ 查边」，适合稠密图与小规模全源最短路；邻接表以「$O(n+m)$ 空间」换稀疏图的高效遍历。
- **扩展方向**：图的存储是后续所有图论算法（最短路、最小生成树、连通分量、网络流等）的公共基础，选择正确的存图方式能显著影响常数与代码复杂度。进阶题目里还可能出现「按边存 + 排序」「邻接表 + 反向图（用于强连通分量、DAG 最短路）」「vector 前向星混合」等变体。$AKB249$, '图论', array['图论', '图的存储', '邻接表', '邻接矩阵', '链式前向星'], null, null, 'knowledge'),
('Xesir', 'col-graph-storage--xesir', '图的存储 · Xesir', $AKB250$## 算法原理

学会了概念，接下来就是怎么把图存进代码里。OI 中常用的存图方式有四种，各有各的适用场景：

- **直接存边**：开一个数组，每个元素存一条边的两个端点和权值（如果有的话）。
- **邻接矩阵**：用二维数组 $\text{adj}[i][j]$ 表示从 $i$ 到 $j$ 是否有边（或者边权是多少）。
- **邻接表**：用一个 `vector` 数组，`adj[i]` 存所有从 $i$ 出发的边。
- **链式前向星**：本质上是**用单向链表实现的邻接表**，用数组模拟链表，比 `vector` 更省内存，速度也更快。

四种方式的核心取舍在于**查一条边是否存在的速度**与**空间消耗**之间的权衡，以及是否方便遍历某个点的所有出边。

## 逐行代码解析

下面把四种存图方式在笔记里的写法贴出来，重点看数据结构长什么样。

### 直接存边

开一个数组，每个元素存一条边的两个端点和权值：

```cpp
struct Edge { int u, v, w; };
vector<Edge> edges;
```

**优点**：实现简单，方便按边权排序。
**缺点**：想知道两点之间是否有边，需要遍历整个数组，$O(m)$ 效率低。
**适用场景**：Kruskal 求最小生成树。

### 邻接矩阵

用一个二维数组 `adj[n][n]`，`adj[i][j]` 表示从 $i$ 到 $j$ 是否有边（或者边权是多少）：

```cpp
int adj[N][N];  // adj[i][j] = 0 表示无边，否则存边权
```

**优点**：判断两点之间是否有边 $O(1)$，实现极其简单。
**缺点**：空间 $O(n^2)$，$n$ 稍微大一点（比如 $n > 5000$）就炸了。
**适用场景**：$n$ 较小（如 $n \le 200$）且需要频繁查询两点间边的情况，比如 Floyd 算法。

### 邻接表

用一个 `vector` 数组，`adj[i]` 存所有从 $i$ 出发的边：

```cpp
vector<pair<int, int>> adj[N];  // first 是终点，second 是边权
// 或者 vector<int> adj[N];  // 不存边权时
```

**优点**：只存储实际存在的边，空间 $O(n + m)$，适合稀疏图；可以方便地遍历一个点的所有出边。
**缺点**：判断两点之间是否有边需要遍历整个邻接表，$O(degree)$。
**适用场景**：最常用！Dijkstra、SPFA、DFS、BFS 等绝大多数场景都适用。

### 链式前向星

本质是**用数组模拟单向链表**实现的邻接表：

```cpp
struct Edge { int to, w, next; } edge[M];  // next 指向下一条边
int head[N], tot;  // head[i] 存 i 的第一条出边在 edge 中的下标

void add(int u, int v, int w) {
    edge[++tot] = {v, w, head[u]};
    head[u] = tot;
}
```

遍历从 $u$ 出发的所有边：

```cpp
for (int i = head[u]; i; i = edge[i].next) {
    int v = edge[i].to, w = edge[i].w;
    // 处理边 u -> v
}
```

**优点**：空间 $O(n + m)$，常数小，速度快，在算法竞赛中广泛使用。
**缺点**：写起来比 `vector` 麻烦。
**适用场景**：对性能要求高的题目，或者 `vector` 被卡常的时候。

## 复杂度分析

设图有 $n$ 个顶点、$m$ 条边，$d(u)$ 表示顶点 $u$ 的度数。四种方式的对比如下：

| 存储方式 | 空间 | 查边 | 遍历出边 | 适用场景 |
|---|---|---|---|---|
| 直接存边 | $O(m)$ | $O(m)$ | $O(m)$ | Kruskal 等需要直接基于边的算法 |
| 邻接矩阵 | $O(n^2)$ | $O(1)$ | $O(n)$ | $n$ 很小的全源最短路 |
| 邻接表 | $O(n+m)$ | $O(d(u))$ | $O(d(u))$ | 绝大多数情况 |
| 链式前向星 | $O(n+m)$ | $O(d(u))$ | $O(d(u))$ | 卡常、追求极致性能 |

**考场建议**：无脑上**邻接表**（`vector` 版）基本不会错。如果 $n$ 很大（比如 $10^6$）或者 `vector` 被卡常了，再换**链式前向星**。邻接矩阵只在 $n \le 200$ 且需要全源最短路时用。直接存边只在 Kruskal 时用。

## 适用场景

- **直接存边**：只需要把边拿出来排序、遍历的算法，典型是 Kruskal。
- **邻接矩阵**：$n$ 很小（大概 $n \le 200$）且要频繁查两点有没有边，例如 Floyd。
- **邻接表（`vector` 版）**：默认首选，Dijkstra、SPFA、DFS、BFS、拓扑排序都适用。
- **链式前向星**：被卡常、内存吃紧，或者边数极大时，用来替代 `vector` 版邻接表。

## 常见陷阱与注意事项

1. **邻接矩阵开不下**：$O(n^2)$ 的空间，$n > 5000$ 基本就炸了，别拿它硬刚大图。
2. **无向图要存两条边**：无向图上一条边得在两个端点各存一次，遍历时注意别把反向的那条又当成新边。
3. **自环与重边**：题目允许时要保证存图结构不会把它们吃掉；邻接矩阵天然存不了重边（会被覆盖），邻接表 / 链式前向星则可以。
4. **链式前向星的初始化**：`head` 初始化为 0、`tot` 从 0 开始，遍历写成 `for (int i = head[u]; i; i = edge[i].next)`，靠 `i` 为 0 终止，别把 0 号边也当成有效边。
5. **`vector` 被卡常**：数据量极大时 `vector` 版邻接表可能 TLE，这时候该换链式前向星。$AKB250$, '图论', array['图论', '图的存储', '邻接表', '邻接矩阵', '链式前向星'], null, null, 'knowledge'),
('world-needs-sunday', 'col-graph-tarjan-cut-vertex', 'Tarjan 割点与桥', $AKB251$## Tarjan 求割点

## 一、问题定义

**割点（关节点）**：在无向图中，如果删掉某个点（以及它连的所有边）之后，图的连通分量数增加了，这个点就称为割点。

暴力做法是枚举每个点，删掉它后用 BFS/DFS 检查连通性，时间复杂度 $O(n(n+m))$，在大规模数据下会超时。

Tarjan 算法的精髓在于：**只做一次 DFS，就能同时判断所有点是不是割点**，复杂度 $O(n+m)$。

## 二、算法原理：核心思想

删掉点 $u$ 之后图会不会断，关键看 $u$ 的"下方"（DFS 树中 $u$ 的子树）能不能不经过 $u$，绕回到 $u$ 的"上方"（$u$ 的祖先）。

- 如果能绕回去 → $u$ 的子树和其余部分除了 $u$ 还有别的通道，删 $u$ 不断
- 如果绕不回去 → $u$ 是子树通向外界的唯一通道，删 $u$ 后子树被孤立，$u$ 是割点

## 三、基础概念

### 1. DFS 生成树

对图做 DFS，第一次走到某个点所经过的边称为**树边**，所有树边构成一棵生成树。其余边称为**非树边**。

**重要性质**：无向图的 DFS 中，非树边一定是"连向祖先"的**返祖边**，不存在横叉边（连向完全另一棵子树的边）。这个性质是 Tarjan 正确性的基石。

### 2. dfn[u] —— 时间戳

`dfn[u]` 表示 $u$ 是第几个被访问到的点。它有两个作用：
- 作为"访问顺序"的编号，数值越小代表越靠近 DFS 的源头（越像"祖先"）
- 同时充当访问标记（0 = 未访问）

### 3. low[u] —— 能追溯到的最早时间戳

**定义**：$u$ 及其子树中的所有点，通过最多一条返祖边，能够到达的时间戳最小的点的时间戳。

直观理解：`low[u]` 回答的问题是——"$u$ 这一片区域，最远能'回头'摸到多早的祖先？"

- `low[u]` 越小 → 子树有强大的返祖通道，能绕过很多层祖先
- `low[u] >= dfn[u]` → 整个子树被 $u$ 封死了，任何回头路最多回到 $u$ 自己

**low 的维护规则**：

| 情况 | 更新方式 | 代码 |
|------|---------|------|
| 初始化 | `low[u] = dfn[u]`（至少能摸到自己） | `dfn[nd] = low[nd] = ++tim` |
| 走树边进入孩子 to | 孩子的回头能力可以继承给我 | `low[nd] = min(low[nd], low[to])` |
| 遇到返祖边连向已访问的 to | 直接一步跳到 to，能摸到 dfn[to] | `low[nd] = min(low[nd], dfn[to])` |

## 四、两个判定定理

### 定理 1：非根节点 u 是割点

**条件**：存在一个孩子 $v$，满足 $\text{low}[v] \geq \text{dfn}[u]$

**证明思路**：
- 如果 $v$ 的子树中所有返祖边最远只能回到 $u$ 或 $u$ 的后代（$\text{low}[v] \geq \text{dfn}[u]$），那么 $v$ 的子树与"$u$ 的祖先部分"之间，$u$ 是唯一通道。删掉 $u$，$v$ 的子树必然和上面断开。
- 反过来，如果每个孩子的子树都能绕到 $u$ 的严格祖先（$\text{low}[v] < \text{dfn}[u]$），删掉 $u$ 后各子树借返祖边跳到上方再互通，图仍然连通。

### 定理 2：根节点是割点

**条件**：它在 DFS 树中有 $\geq 2$ 个孩子

**为什么根不能用定理 1？** 因为根的时间戳最小（`dfn = 1`），`low[v] >= dfn[root]` 对任何孩子都恒成立，直接套用会得出"根永远是割点"的错误结论。根本身就是最高点，"绕不到根上面"对根没有意义。

**正确角度**：由"无向图 DFS 无横叉边"的性质，根的不同 DFS 子树之间一定没有边相连。所以：
- 孩子数 $\geq 2$ → 子树之间完全隔离 → 删根必断 → 根是割点
- 孩子数 $= 1$ → 整张图都在一棵子树里 → 根不是割点

> 注意：这里的"孩子"指 DFS 树中的孩子，不是图中的度数。比如星形图从叶子开始 DFS，中心节点有多个孩子（判为割点 ✓），叶子只有一个孩子（非割点 ✓）。用度数会误判。

## 五、逐行代码解析

### 变量定义

```cpp
int n, m, tim, cnt;
vector<vector<int>> edges;
vector<int> dfn, low;
vector<bool> is_cut;
```

| 变量 | 含义 |
|------|------|
| `n, m` | 点数、边数 |
| `tim` | 时间戳计数器 |
| `cnt` | 割点总数 |
| `edges` | 邻接表 |
| `dfn` | 每个点的时间戳，0 表示未访问 |
| `low` | 每个点子树能追溯到的最早时间戳 |
| `is_cut` | 标记每个点是否为割点 |

### 初始化函数

```cpp
void init()
{
    tim = 0;
    cnt = 0;
    dfn.assign(n + 1, 0);
    low.assign(n + 1, 0);
    is_cut.assign(n + 1, false);
}
```

重置所有数组和计数器，时间戳从 1 开始（0 表示未访问）。

### Tarjan 主函数

```cpp
void tarjan(int nd, int fa)
{
    int child_cnt = 0;
    dfn[nd] = low[nd] = ++tim;
```

- `nd`：当前节点；`fa`：父节点，根传 -1
- `child_cnt`：记录 DFS 树中的孩子数量
- 打时间戳，low 初始化为自己（"最差也能摸到自己"）

```cpp
    for (int to : edges[nd])
    {
        if (to == fa) continue;
```

枚举所有邻居，**跳过父亲边**。无向边在邻接表里存了两份，从孩子往回枚举时一定会碰到父亲，如果不跳过，就会把"来时的树边"误认成"返祖边"，导致所有点都判不出割点。

```cpp
        if (!dfn[to])                // 情况 1: to 未访问 → 树边
        {
            ++child_cnt;
            tarjan(to, nd);
            low[nd] = min(low[nd], low[to]);
            if (fa != -1 && low[to] >= dfn[nd] && !is_cut[nd])
                is_cut[nd] = true, cnt++;
        }
```

**情况 1：树边**
1. 孩子数 +1
2. 递归处理孩子（先递归，出来时 `low[to]` 才是最终值）
3. 继承孩子的回头能力：`low[nd] = min(low[nd], low[to])`
4. 定理 1 判定非根割点：`low[to] >= dfn[nd]` 且非根
   - `!is_cut[nd]` 去重：多个孩子都满足条件时只计数一次

```cpp
        else                         // 情况 2: to 已访问 → 返祖边
            low[nd] = min(low[nd], dfn[to]);
    }
```

**情况 2：返祖边**
- 用 `dfn[to]` 更新，不是 `low[to]`！
- 语义：返祖边是"我直接一步就能到达 to"，一步可达能摸到的最早值就是 `dfn[to]`
- 割点场景下误用 low[to] 恰好不出错，但割边（桥）会出 bug，养成用 `dfn[to]` 的正确习惯

```cpp
    if (fa == -1 && child_cnt >= 2)
        is_cut[nd] = true, cnt++;
}
```

**定理 2：根的特判**
- 必须等所有邻居枚举完（所有孩子都统计完）才能下结论
- 放在循环外、函数末尾

### 驱动函数

```cpp
void fn()
{
    init();
    for (int i = 1; i <= n; i++)
    {
        if (!dfn[i]) tarjan(i, -1);
    }
}
```

图可能不连通，对每个未访问的点都启动一次 DFS。每个连通块的第一个被访问点自动成为该块的 DFS 根，享受"孩子数 ≥ 2"的正确判定；孤立点孩子数为 0，不会被误判。

### 主函数

```cpp
int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr); cout.tie(nullptr);
    cin >> n >> m;
    edges.assign(n + 1, {});
    for (int i = 1; i <= m; i++)
    {
        int u, v;
        cin >> u >> v;
        edges[u].emplace_back(v);
        edges[v].emplace_back(u);   // 无向图，双向加边
    }
    fn();
    cout << cnt << '\n';
    for (int i = 1; i <= n; i++)
    {
        if (is_cut[i]) cout << i << ' ';
    }
    return 0;
}
```

## 六、手动模拟示例

**图结构**：

```
1 — 2 — 3
    |
    4 — 5
```

边：1-2, 2-3, 2-4, 4-5

从 1 开始 DFS，路径 1→2→3→(回)→2→4→5：

| 步骤 | 动作 | 结果 |
|------|------|------|
| 1 | 进入 1 | `dfn[1]=low[1]=1` |
| 2 | 进入 2 | `dfn[2]=low[2]=2`，1 的 child_cnt=1 |
| 3 | 进入 3 | `dfn[3]=low[3]=3`，2 的 child_cnt=1 |
| 4 | 3 无未访问邻居，回溯 | `low[3]=3` 保持 |
| 5 | 回到 2，用孩子 3 更新 | `low[2]=min(2,3)=2`；`low[3]=3 >= dfn[2]=2` 且 fa=1 非根 → **2 是割点**，cnt=1 |
| 6 | 2 枚举邻居 4（未访问） | 进入 4，child_cnt[2]=2 |
| 7 | 进入 5 | `dfn[5]=low[5]=5` |
| 8 | 回到 4 | `low[4]=min(4,5)=4`；`low[5]=5 >= dfn[4]=4`，fa=2 非根 → **4 是割点**，cnt=2 |
| 9 | 回到 2 | `low[2]=min(2,4)=2`；low[4]>=dfn[2]，但 2 已标记，不重复计数 |
| 10 | 回到 1，枚举完毕 | 1 是根，child_cnt=1 < 2 → 不是割点 |

**结论**：割点为 2 和 4 ✓

## 七、复杂度分析

| 维度 | 复杂度 | 说明 |
|------|--------|------|
| 时间 | $O(n + m)$ | 每个点恰好访问一次，每条无向边在邻接表中各遍历一次 |
| 空间 | $O(n + m)$ | 邻接表 + dfn/low/is_cut 三个数组 |
| 递归深度 | 最坏 $O(n)$ | 链状图会达到最深。本题规模下安全；$n$ 达 $10^5$ 以上需改迭代版或加大栈空间 |

## 八、常见陷阱

1. **返祖边误用 `low[to]`**：应使用 `dfn[to]`。割点场景下恰好不出错，但割边会出 bug，养成正确习惯。
2. **忘记跳过父亲边**：树边被当返祖边，low 全部失效，所有点都判不出割点。
3. **根没有特判**：或误用 `low >= dfn` 判根，导致根永远 / 永不判中。
4. **用图的度数代替 DFS 树的孩子数**：重边、多入口都会使度数失真（见星形图反例）。
5. **忘记处理非连通图**：必须对每个未访问点都启动一次 DFS。
6. **割点判定写在递归之前**：用到未定型的 `low[to]`，判断错误。
7. **忘记去重**：一个点被多个孩子的条件反复触发时多计 cnt。
8. **重边与割点/割边的区别**：割点中"跳过所有 fa 边"没问题；但这个模板不能直接改成割边（桥）——桥必须只跳过"来时的那一条树边"（通常用边编号判断），否则有重边时桥会被漏判。

## 九、适用场景

- **求割点**：找出无向图中所有关节点
- **点双连通分量**：割点是点双连通分量的交界点，求割点是求点双的基础
- **网络可靠性分析**：判断哪些节点故障会导致网络分裂
- **2-SAT 问题**：某些变体需要借助割点分析
- **图的缩点**：点双连通分量缩成"圆方树"，割点是公共点

## 十、与强连通分量 Tarjan 的对比

| 维度 | 强连通分量 Tarjan | 割点 Tarjan |
|------|------------------|------------|
| 图类型 | 有向图 | 无向图 |
| 核心结构 | 栈维护当前 SCC | 无栈，靠 dfn/low 直接判定 |
| 判定条件 | `low[u] == dfn[u]` 弹出栈 | 非根：`low[child] >= dfn[u]`；根：child_cnt >= 2 |
| 父节点处理 | 不需要跳过父边 | 必须跳过父边（`to == fa` continue） |
| 输出 | 每个 SCC 的点集 + 颜色数组 | 割点标记数组 |
| 延伸算法 | 缩点 → DAG → 拓扑 DP | 点双连通分量、圆方树 |

## 附：Tarjan 求桥（割边）

Tarjan 算法由 Robert Tarjan 于 1974 年提出，通过**一次深度优先搜索（DFS）**即可找出无向图中所有的**桥**（割边），时间复杂度为 $O(n+m)$。

#### 什么是桥

**桥（Bridge，又称割边）**：在无向图中，如果删除某条边后，图的连通分量数增加，则称这条边为桥。换句话说，桥是图中的"生命线"——去掉它图就会被拆成两部分。

暴力做法是枚举每条边，删除后用 BFS/DFS 检查连通性，时间复杂度 $O(m(n+m))$，在大规模数据下会超时。Tarjan 算法的精髓在于：只做一次 DFS，就能同时判断所有边是不是桥。

#### 核心思想

判断一条树边 $u \to v$（$u$ 是父节点，$v$ 是子节点）是不是桥，关键看 $v$ 的子树能不能不经过这条边，绕回到 $u$ 或 $u$ 的祖先：

- **能绕回去** → 子树和外界除了这条边还有其他通道，这条边不是桥
- **绕不回去** → 这条边是子树通向外界的唯一通道，删去后子树被孤立，是桥

#### DFS 生成树与返祖边

对无向图做 DFS，第一次走到某个点所经过的边称为**树边**，所有树边构成一棵生成树。其余的边称为**非树边**。

**关键性质**：无向图的 DFS 中，非树边一定是"连向祖先"的**返祖边**，不存在横叉边（连向完全另一棵子树的边）。这个性质是 Tarjan 正确性的基石——因为如果有横叉边，"low 值追溯"的逻辑就不成立了。

#### dfn 与 low 数组

| 数组 | 含义 |
|------|------|
| `dfn[u]` | 节点 $u$ 被首次访问的时间戳（DFS 序），同时充当访问标记（0 = 未访问） |
| `low[u]` | 从 $u$ 及其子树中的所有点出发，通过最多一条返祖边，能到达的时间戳最小的节点的时间戳 |

`low[u]` 回答的问题是："$u$ 这一片区域，最远能'回头'摸到多早的祖先？"

#### 桥的判定条件

对于树边 $u \to v$（$u$ 是父节点，$v$ 是子节点）：

$$
\text{low}[v] > \text{dfn}[u] \quad \Longrightarrow \quad u\text{-}v \text{ 是桥}
$$

含义：$v$ 的子树最多只能追溯到 $v$ 自己或更晚的节点，无法回到 $u$ 或更早的祖先，因此 $u$-$v$ 这条边是子树与外界的唯一连接——桥。

对比割点的判定 `low[v] >= dfn[u]`：割点允许子树追溯到 $u$ 自身（等于号成立），而桥要求**严格大于**——因为如果子树能回到 $u$，说明存在不经过这条树边的路径（通过返祖边），所以这条边不是桥。

### 核心状态定义与转移方程

#### 状态定义

| 变量 | 含义 |
|------|------|
| `dfn[rt]` | 当前节点的时间戳（DFS 序编号） |
| `low[rt]` | 当前节点及其子树能追溯到的最早时间戳 |
| `fa` | DFS 树中的父节点，用于防止走回父边 |
| `tim` | 全局时间戳计数器 |
| `cnt` | tarjan 函数内的局部计数器，用于重边处理（只跳过第一条父边） |
| `is_bridge` | 存储所有桥的边列表 |

#### 转移规则

进入 DFS 时初始化：

$$
\text{dfn}[u] = \text{low}[u] = \text{++tim}
$$

对每条出边 $u \to v$，分三种情况处理：

$$
\text{low}[u] \text{ 的更新} =
\begin{cases}
\text{跳过（仅第一条父边）} & v = \text{fa} \text{ 且本轮未跳过过父边} \\
\min(\text{low}[u], \text{low}[v]) & v \text{ 未访问，递归后回溯更新} \\
\min(\text{low}[u], \text{dfn}[v]) & v \text{ 已访问且未被跳过（返祖边或重边）}
\end{cases}
$$

注意返祖边的情况用的是 `dfn[v]` 而不是 `low[v]`。这是因为 `low` 的定义是"通过最多一条返祖边"能到达的最早节点，如果用 `low[v]` 就相当于走了多条返祖边，会导致误判。

#### 桥的判定

递归回溯后，若满足：

$$
\text{low}[v] > \text{dfn}[u]
$$

则 $u$-$v$ 是桥。

#### 重边处理机制

无向图加边时每条边存两份（$u \to v$ 和 $v \to u$）。如果 $u$ 和 $v$ 之间有**重边**（两条以上的平行边），那么删掉其中一条不影响连通性，因此重边不可能是桥。

代码通过局部计数器 `cnt` 实现正确的重边处理：对当前节点 `rt`，只跳过邻接表中**第一次出现的父边**，后续出现的同方向重边会走到 `else` 分支作为返祖边处理，从而更新 `low` 值，使重边不会被误判为桥。

### 逐行代码解析

#### 全局变量定义

```cpp
vector<vector<int>> edges;             // 邻接表
vector<int> dfn, low;                  // 时间戳 / 能追溯的最早时间戳
vector<pair<int, int>> is_bridge;     // 存储所有桥
int tim;                                // 全局时间戳计数器
```

- `edges`：无向图的邻接表
- `dfn`、`low`：Tarjan 的核心双数组
- `is_bridge`：存放所有桥的端点对
- `tim`：DFS 时间戳计数器

#### 初始化函数

```cpp
void init(int n, int m)
{
	dfn.assign(n + 1, 0);
	low.assign(n + 1, 0);
	edges.assign(n + 1, vector<int>());
	is_bridge.clear();
	tim = 0;
}
```

所有数组初始化为 0，`dfn = 0` 表示未访问。

#### 加边函数

```cpp
void add(int u, int v)
{
	edges[u].emplace_back(v);
	edges[v].emplace_back(u);
}
```

无向图双向加边。重边会在邻接表中存为多个独立条目。

#### Tarjan 核心函数

```cpp
void tarjan(int rt, int fa)
{
	int cnt = 0;                              // 局部计数器：记录是否已跳过父边
	dfn[rt] = low[rt] = ++tim;               // 初始化时间戳和 low 值
	for (int i : edges[rt])                   // 遍历所有邻接点
	{
		if (fa == i && !cnt)                 // 只跳过第一条父边
		{
			++cnt;
			continue;
		}
		if (!dfn[i])                         // 情况1：未访问——树边
		{
			tarjan(i, rt);                   // 递归 DFS
			low[rt] = min(low[i], low[rt]);  // 回溯：用子节点 low 更新父节点
			if (low[i] > dfn[rt])            // 桥的判定条件
				is_bridge.emplace_back(rt, i);
		}
		else                                  // 情况2：已访问——返祖边或重边
			low[rt] = min(dfn[i], low[rt]);  // 用 dfn[i] 更新 low[rt]
	}
}
```

逐行解析关键点：

1. **`int cnt = 0;`**：局部计数器，每次进入 `tarjan` 函数时重置为 0。用于记录当前节点是否已经跳过了一条父边。

2. **`dfn[rt] = low[rt] = ++tim;`**：新节点初始时，low 值等于自己的时间戳——目前只知道能到达自己。注意全局计数器已更名为 `tim`，避免与局部 `cnt` 混淆。

3. **`if (fa == i && !cnt)`**：这是**重边处理的核心**。无向图中每条边在邻接表中出现两次（$u \to v$ 和 $v \to u$），从父节点来的边不能往回走，否则会死循环。但如果有重边（$u$ 和 $v$ 之间多条平行边），只跳过第一条父边，后续重边会走到 `else` 分支作为返祖边处理，从而正确地不判定为桥。

4. **`++cnt;`**：标记已跳过一条父边，后续即使再遇到 `fa` 也不会跳过，而是作为返祖边处理。

5. **`if (!dfn[i])` 树边分支**：
   - 递归进入子节点 `tarjan(i, rt)`
   - 回溯时更新：`low[rt] = min(low[i], low[rt])`——子树能追溯到的最早节点，父节点当然也能追溯到
   - **桥判定**：`if (low[i] > dfn[rt])` —— 子节点的追溯能力到不了父节点或更早，说明父→子这条边是唯一通道，是桥

6. **`else` 返祖边分支**：
   - `low[rt] = min(dfn[i], low[rt])` —— 注意这里用的是 `dfn[i]`（邻居的时间戳）而不是 `low[i]`！因为返祖边只能算"一条"，不能把邻居 $i$ 通过其自身子树追溯到的能力也算上。用 `dfn[i]` 精确表达"通过这条返祖边直接到达节点 $i$"。

#### 主函数

```cpp
int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr); cout.tie(nullptr);
	int n, m;
	cin >> n >> m;
	init(n, m);
	for (int i = 1; i <= m; i++)
	{
		int u, v;
		cin >> u >> v;
		add(u, v);
	}
	for (int i = 1; i <= n; i++)     // 遍历所有连通分量
	{
		if (!dfn[i]) tarjan(i, -1);
	}
	cout << is_bridge.size() << '\n';
	for (pair<int, int> i : is_bridge)
		cout << i.first << ' ' << i.second << '\n';
	return 0;
}
```

注意：代码处理了图不连通的情况——外层循环遍历所有节点，对每个未访问的连通分量启动一次 Tarjan。根节点的父节点设为 `-1`（不存在的节点编号）。

### 复杂度分析

#### 时间复杂度：$O(n+m)$

- 每个节点恰好被访问一次（`dfn` 从 0 变非 0 只发生一次）
- 每条无向边被访问两次（双向各一次），其中一条因父边判定被跳过，实际有效处理一次
- 总操作量与顶点数 $n$ 和边数 $m$ 成线性关系

#### 空间复杂度：$O(n+m)$

- 邻接表：$O(n+m)$
- `dfn`、`low` 数组：各 $O(n)$
- `is_bridge` 结果数组：最坏 $O(m)$（全是桥，即树）
- DFS 递归栈深度：最坏 $O(n)$（链状图）

### 适用场景

#### 适用场景

1. **桥的检测**：找出无向图中所有的桥（割边）
2. **边双连通分量**：将所有桥删除后，每个极大连通子图就是一个边双连通分量。桥是边双连通分量之间的"关节边"
3. **网络可靠性分析**：找出网络中的关键链路，故障后会导致网络分裂
4. **2-边连通性问题**：判断图是否 2-边连通（无桥），或至少需要添加多少条边使图变成 2-边连通

#### 不适用场景

1. **有向图**：桥是无向图的概念，有向图的对应概念需另行定义（如强连通分量）
2. **需要点双连通分量**：点双连通分量基于割点，不是桥
3. **动态图**：边不断增删的图，Tarjan 是静态算法，每次增删边都需要重新运行

### 常见陷阱与注意事项

#### 1. 桥的判定是严格大于

桥的判定条件是 `low[i] > dfn[rt]`（**严格大于**），而割点是 `low[i] >= dfn[u]`（大于等于）。

- **割点**：子树追溯不到 $u$ 之外 → $u$ 是割点。等于号成立说明子树能回到 $u$ 自己，但 $u$ 被删后子树仍然孤立
- **桥**：子树必须连 $u$ 都回不到 → 这条边才是桥。等于号时子树能通过返祖边回到 $u$，说明存在替代路径，这条边不是桥

#### 2. 返祖边更新必须用 dfn[i] 而不是 low[i]

返祖边更新 low 值时，代码写的是 `low[rt] = min(dfn[i], low[rt])`，用的是邻居的 `dfn[i]`，不是邻居的 `low[i]`。

原因：`low` 的定义是"通过**最多一条**返祖边"能到达的最早节点。如果用 `low[i]` 更新，就相当于把 $i$ 通过其子树进一步追溯的结果也算进来了，等于走了多条返祖边，会导致 `low` 值过小，从而把本应是桥的边漏判。

#### 3. 重边处理：只跳第一条父边

无向图中，如果 $u$ 和 $v$ 之间有**重边**（两条以上的平行边），删掉其中一条不影响连通性，因此重边不可能是桥。

**错误做法**：`if (fa == i) continue;` —— 这会跳过所有指向父节点的边，导致重边中的第二条也被跳过，无法作为返祖边更新 `low` 值，从而可能把重边误判为桥。

**正确做法**：用局部计数器 `cnt` 只跳过邻接表中第一条出现的父边（`if (fa == i && !cnt)`），后续重边走到 `else` 分支作为返祖边处理，正确更新 `low` 值，使重边不会被误判为桥。

#### 4. 图不连通的处理

代码外层有 `for (int i = 1; i <= n; i++) if (!dfn[i]) tarjan(i, -1);`，确保每个连通分量都被处理。这一点很重要，否则非连通图的某些分量会被漏掉。

#### 5. 桥的输出顺序

桥以 `(rt, i)` 的顺序存入，即父节点在前、子节点在后。输出的方向与 DFS 树的父子关系一致，与输入的边的方向不一定相同。同一座桥只会被记录一次（从父到子的方向）。

#### 6. 自环边

自环（节点到自己的边）不是桥——删掉自环不影响连通性。在代码中，自环会被 `else` 分支（返祖边）处理，`low[rt] = min(dfn[rt], low[rt])` 没有变化，且不会触发桥的判定（桥的判定只在树边分支）。所以自环被正确忽略。

### 对比与扩展

#### 与割点算法对比

| 对比维度 | Tarjan 求桥 | Tarjan 求割点 |
|----------|-----------|-------------|
| 判定对象 | 边 | 顶点 |
| 判定条件 | `low[v] > dfn[u]`（严格大于） | `low[v] >= dfn[u]`（大于等于），根节点单独判定 |
| 根节点处理 | 无需特殊处理 | 需统计子树个数，子树数 $\geq 2$ 才是割点 |
| 结果存储 | 边对 `(u, v)` | 顶点编号 |
| 时间复杂度 | $O(n+m)$ | $O(n+m)$ |
| 空间复杂度 | $O(n+m)$ | $O(n+m)$ |

#### 边双连通分量

将图中所有的桥都删除后，每个极大的连通子图称为一个**边双连通分量**（Edge-Biconnected Component, E-BCC）。边双连通分量内部没有桥——任意两点之间至少有两条边不相交的路径。

求边双连通分量的方法：
1. 用 Tarjan 找出所有桥
2. 删除所有桥，对剩余图做 DFS/BFS 染色，每个连通块就是一个边双连通分量

#### 点双连通分量

点双连通分量（Vertex-Biconnected Component, V-BCC）是指不存在割点的极大子图。点双连通分量的关系比边双更复杂：一个割点可以属于多个点双连通分量。求点双连通分量需要在 DFS 中维护一个栈，保存经过的边，发现割点时弹栈得到一个点双。

#### 2-边连通性增强

给定一个无向图，问至少添加几条边可以使图变成 2-边连通（没有桥）。解法：
1. 求所有边双连通分量，将每个分量缩成一个点
2. 缩点后的图是一棵树，所有的"边"都是原来的桥
3. 答案 = $\lceil \frac{\text{叶子数}}{2} \rceil$，其中叶子是缩点后度数为 1 的节点

这个结论与"无向图添加最少边使图强连通"（缩点后入度0和出度0的最大值）是类似的对偶问题。$AKB251$, '图论', array['图论', 'Tarjan', '割点', 'DFS', '连通性'], null, null, 'knowledge'),
('Fohen', 'col-graph-tarjan-scc--fenfeng', 'Tarjan 强连通分量 · Fohen', $AKB252$## 算法原理

Tarjan 算法用于求有向图中所有的**强连通分量（Strongly Connected Components, SCC）**，它的核心是**一次深度优先搜索（DFS）**，复杂度为线性，实际运行效率很高，是竞赛中最常用的 SCC 算法。

### 什么是强连通分量

对于一个有向图 $G$，一个点集 $S$ 称为强连通分量，当且仅当 $S$ 中任意两个节点互相可以到达（默认节点可以到达自身）。当一个强连通分量无法在保持强连通性质的同时再扩张时，称其为**极大强连通分量**，通常简称为 SCC。

极大 SCC 有两个关键性质：

- 每一个点只属于一个 SCC，即不同的极大 SCC **没有交集**。
- 将所有极大 SCC 缩成一个点后，所得的图是 **DAG**（有向无环图）。

这两条性质是「缩点」类题目成立的基础。

### DFS 搜索树与四种边

任意一个有向图都可以从任意一点开始 DFS，得到一棵搜索树。Tarjan 在 DFS 过程中把每条边归为四类：

1. **树边**：搜索树上的边（指向未访问节点的边）。
2. **返祖边**：指向祖先节点的边。
3. **横叉边**：从一棵子树指向另一棵子树的边。
4. **前向边**：指向子树中（后代）节点的边。

其中前向边不携带任何有用信息；返祖边与树边一定构成环，横叉边与树边可能构成环。DFS 的性质保证有向图中只会有这四种边。

### 核心思想：`dfn` 与 `low`

Tarjan 只需在原图上进行一次 DFS 就能求出所有 SCC，它维护两个数组：

- `dfn[u]`：节点 $u$ 第一次被 DFS 访问时的时间戳。
- `low[u]`：从 $u$ 出发，经过若干条 DFS 树边以及**至多一条返祖边**，能够到达的最小 `dfn`。

当 DFS 处理节点 $u$ 时，先把它标记入栈；对每个邻点 $v$ 分三种情况处理（详见「核心公式」一节）。处理完所有邻点后，若 $dfn[u] = low[u]$，说明 $u$ 是当前 SCC 的根，栈中从栈顶到 $u$ 的所有节点恰好构成一个 SCC，直接统计并全部出栈即可。

由于 DFS 前序遍历的特点，在处理完一个 SCC 之前不会退出，Tarjan 正是利用这一性质构造出线性解法。

## 核心公式 / 状态定义与转移方程

Tarjan 没有数值型的递推式，它的「状态」是两个时间戳数组，转移规则体现在 `low` 的更新上。

### 状态定义

对每个节点 $u$ 维护：

- $dfn[u]$：DFS 首次访问 $u$ 的时间戳，按访问顺序递增编号。
- $low[u]$：$u$ 能回溯到的最小时间戳，定义为「从 $u$ 出发，经过若干条树边以及至多一条返祖边能到达的最小 $dfn$」。

### 转移：三种情况

DFS 到 $u$ 时，先令 $dfn[u] = low[u] = \text{++}idx$ 并压栈。随后对每条出边 $u \to v$：

1. **$v$ 未访问**（树边）：搜索树中 $u$ 是 $v$ 的父节点，$v$ 能到达的节点 $u$ 一定能到达，故先递归处理 $v$，再用 $low[v]$ 更新 $low[u]$：

$$low[u] = \min(low[u],\, low[v])$$

2. **$v$ 已访问且在栈中**（返祖边或横叉边）：用 $v$ 的时间戳更新 $low[u]$：

$$low[u] = \min(low[u],\, dfn[v])$$

3. **$v$ 已访问但不在栈中**：说明 $v$ 已在另一个 SCC 中且处理完毕，直接跳过。

### 判定 SCC 根

处理完 $u$ 的所有邻点后，若满足：

$$dfn[u] = low[u]$$

则 $u$ 是当前 SCC 的根，此时栈中从栈顶到 $u$ 的所有节点（含 $u$）恰好构成一个 SCC，把它们全部弹出并标记为同一个分量编号。

## 逐行代码解析

下面把 Tarjan 模板按职责拆成四个模块，各模块代码按顺序拼接即为 `codePath` 指向的 `.cpp`。

### 模块一：头文件与全局数据结构

```cpp
#include<bits/stdc++.h>
#define endl '\n'
#define fi first
#define se second
#define lowbit(x) x&(-x)
#define int long long
using namespace std;
typedef pair<int,int> PII;
typedef long long ll;
//const int N=1e5+10;
//int cnt=0;
//int a[N];
inline int read();
inline void write(int x);
const int MAXN = 10005;
vector<int> G1[MAXN];  // 邻接表存储有向图
int dfn[MAXN], low[MAXN], scc[MAXN];  // scc[u]表示u所属的SCC编号
stack<int> st;
int idx = 0, tot = 0;  // 时间戳、SCC数量
bool vis[MAXN];  // 标记是否在栈中
```

- `G1` 是邻接表，存储有向图；`dfn`、`low` 是时间戳数组，`scc[u]` 记录 $u$ 所属的 SCC 编号。
- `st` 是辅助栈，`idx` 是全局时间戳，`tot` 是已求出的 SCC 数量，`vis[u]` 标记 $u$ 是否在栈中。
- `#define int long long` 把 `int` 全部替换成 `long long` 防溢出，因此入口函数写作 `signed main`。
- `read` / `write` 是快读快写函数，声明在前、实现放在文件末尾。

### 模块二：Tarjan 主体

```cpp
void tarjan(int u) {
    dfn[u] = low[u] = ++idx;
    st.push(u);
    vis[u] = true;
    for (int v : G1[u]) {
        if (!dfn[v]) {  // v未访问
            tarjan(v);
            low[u] = min(low[u], low[v]);
        } else if (vis[v]) {  // v已访问且在栈中（回边）
            low[u] = min(low[u], dfn[v]);
        }
    }
    // 找到SCC的根
    if (dfn[u] == low[u]) {
        tot++;
        int v;
        do {
            v = st.top();
            st.pop();
            vis[v] = false;
            scc[v] = tot;
        } while (v != u);
    }
}
```

- 进入时给 $u$ 打上时间戳并压栈，`dfn[u]` 与 `low[u]` 初始都为当前时间戳。
- 遍历每条出边：`!dfn[v]` 表示 $v$ 未访问，递归后用 `low[v]` 更新 `low[u]`；`vis[v]` 表示 $v$ 在栈中（返祖边或横叉边），用 `dfn[v]` 更新 `low[u]`；两者都不满足说明 $v$ 已出栈（属于别的 SCC），跳过。
- 所有邻点处理完，若 `dfn[u] == low[u]`，则 $u$ 是 SCC 的根：`tot` 自增，用 `do...while` 把栈顶到 $u$ 的节点依次弹出并染成 `tot`。

