### 模块四：快读快写

```cpp
inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch< '0'||ch>'9'){
        if(ch=='-') f=-1;
        ch=getchar();
    }
    while(ch>='0'&&ch<='9'){
        x=(x<<1)+(x<<3)+(ch^48);
        ch=getchar();
    }
    return x*f;
}
inline void write(int x){
    if(x<0){
        putchar('-');
        x=-x;
    }
    if(x>9) write(x/10);
    putchar(x%10+'0');
}
```

- `read`：快读，逐字符读入并处理负号，`ch^48` 把数字字符转成数值，`x = (x<<1) + (x<<3) + ...` 等价于 `x = x*10 + ...`。
- `write`：快写，负数先输出负号，然后按位递归输出，`putchar(x%10+'0')` 把个位数字转成字符。

## 复杂度分析

- **时间复杂度**：$O(n+m)$。每个节点恰好入栈一次、出栈一次，每条边恰好被访问一次，一次 DFS 的总代价与图的规模线性相关。Tarjan 只做一次 DFS，常数很小，实际运行效率很高。
- **空间复杂度**：$O(n+m)$。邻接表 `G1` 占 $O(n+m)$；`dfn`、`low`、`scc`、`vis` 与栈各占 $O(n)$。整体为线性。

## 适用场景

1. **强连通分量检测**：求出有向图中所有 SCC，分析图的结构。
2. **缩点**：把每个 SCC 缩成一个点，将一般有向图转化为 DAG，之后可做拓扑排序、最长路、DP 等。
3. **2-SAT 问题**：用 Tarjan 求 SCC 后，根据每个变量的两个状态是否落在同一 SCC 中判断可行性。
4. **有向图连通性判断**：判断两个节点是否互相可达。

## 常见陷阱与注意事项

1. **「已访问但不在栈中」要跳过**：第三种情况（$v$ 已访问且已出栈）表示 $v$ 属于另一个已处理完的 SCC，不能再更新 `low[u]`，否则会把不同 SCC 错误地合并。
2. **`low` 的更新要分情况**：树边（$v$ 未访问）用 `low[v]` 更新，返祖边（$v$ 在栈中）用 `dfn[v]` 更新。两者不能混用：返祖边只能「跳一步」到祖先，不能用后代的 `low`。
3. **前向边无需处理**：前向边指向已访问的后代，不携带「回到更早节点」的信息，DFS 中会被「已访问」的判定自然跳过，不影响结果。
4. **横叉边与返祖边都落在「在栈中」分支**：有向图中只要终点仍在栈中，无论是返祖边还是横叉边，统一用 `dfn[v]` 更新 `low[u]`，实现上用 `vis[v]` 判断即可。
5. **不连通图要遍历所有节点**：图可能不连通，需要对每个未访问的节点都启动一次 `tarjan`，不能只从一个起点出发。
6. **链状图可能爆栈**：Tarjan 用递归实现，当图是一条很长的链时，DFS 深度可达 $O(n)$；$n$ 很大（如 $10^5$、$10^6$ 量级）时系统栈可能溢出，应改用显式栈的迭代写法或增大栈空间。

## 对比与扩展

### 与 Kosaraju 的对比

求 SCC 最常用的两个算法是 Tarjan 与 Kosaraju：

| 算法 | 思路 | DFS 次数 | 常数 | 直观程度 |
|------|------|---------|------|---------|
| Tarjan | 一次 DFS + 栈 + `dfn`/`low` | 1 次 | 小 | 较难理解 |
| Kosaraju | 正向 DFS 求出栈序 + 反图 DFS | 2 次 | 稍大 | 直观易理解 |

两者时间复杂度相同，都是 $O(n+m)$。Tarjan 只需一次 DFS、常数更小、代码更短，竞赛中最常用；Kosaraju 需要额外存反图、多跑一遍 DFS，但思路更清晰，适合入门理解 SCC。相关内容见「Kosaraju（强连通分量）」。

### 缩点：SCC 的典型应用

求出每个点所属的 SCC（`scc[u]`）后，可以构建**缩点图**：每个 SCC 是一个新节点，原图中跨 SCC 的边变成缩点图中的边。由极大 SCC 的性质，缩点图一定是 DAG。

```cpp
// 伪代码：构建缩点图
vector<vector<int>> new_edges(tot + 1);
for (int u = 1; u <= n; u++)
    for (int v : G1[u])
        if (scc[u] != scc[v])
            new_edges[scc[u]].push_back(scc[v]);
```

缩点后可以做：拓扑排序上的 DP（如求经过节点权值最大的路径）、求 DAG 上的最长路/最短路、统计入度为 0 的缩点个数（至少需要多少个起点才能走遍全图）等。$AKB252$, '图论', array['图论', '强连通分量', 'Tarjan', 'DFS', '缩点'], 'col-graph-scc-overview', null, 'knowledge'),
('Xesir', 'col-graph-tarjan-scc--xesir', 'Tarjan 强连通分量 · Xesir', $AKB253$## 算法原理

先明确概念。对于有向图 $G$，一个点集 $S$ 是**强连通分量**（SCC），当且仅当 $S$ 中任意两个节点互相可达（默认节点可以到达自身）。当它在保持强连通的前提下**没法再扩大**时，就叫**极大强连通分量**，平时说的 SCC 指的就是它。

极大 SCC 有两把刷子：

- 每个点**只属于一个** SCC，不同极大 SCC **互不相交**。
- 把所有极大 SCC 各缩成一个点之后，得到的图一定是个 **DAG**。

第二条是「缩点」这类题的命根子。举个栗子：点集 $\{1,2,3,4,9\}$ 两两可达，是一个极大 SCC；而 $\{5,6,8\}$、$\{7\}$ 各自也是。

求 SCC 常见两种写法：Kosaraju 和 Tarjan。

- **Kosaraju**：两次 DFS。第一次在原图上跑，记下每个点的**完成时间**；第二次在**反图**上，按完成时间**逆序**再跑，每次能访问到的一坨点恰好就是一个 SCC。思路好懂，但要建反图、跑两遍。
- **Tarjan**：~~Tarjan 还是太强了~~ 只跑**一次 DFS** 就能求出全部 SCC，复杂度线性，实战最快。
  > 你说得对，但是**罗伯特·塔扬（Robert Endre Tarjan）**是 **1986 年图灵奖得主**，Tarjan、并查集、Splay、LCT 等算法的发明者，势能分析法开创者。~~吓哭了~~

Tarjan 的关键在于把 DFS 过程中遇到的有向边分成四类：

1. **树边**：搜索树上的边。
2. **返祖边**：指向祖先节点的边。
3. **横叉边**：从一棵子树指向已访问过的另一棵子树的边。
4. **前向边**：指向子树中节点的边。

前向边基本没用；返祖边和树边必然成环；横叉边和树边**可能**成环。DFS 的性质保证只会有这四种边。

## 核心公式 / 状态定义与转移方程

Tarjan 只维护两个数组：

- `dfn[u]`：点 $u$ **第一次**被 DFS 访问到的时间戳。
- `low[u]`：从 $u$ 出发，经过若干条 DFS 树边、以及**至多一条**返祖边，能够到达的最小 `dfn`。

设 $u$ 的邻点为 $v$，转移分三种情况：

- $v$ **未访问**：$u$ 是 $v$ 在搜索树上的父亲，$v$ 能到的 $u$ 一定能到，所以先递归 $v$，再用 `low[v]` 更新：

$$
low[u] = \min(low[u],\ low[v])
$$

- $v$ **已访问且在栈中**（返祖边 / 横叉边）：用 `dfn[v]` 更新：

$$
low[u] = \min(low[u],\ dfn[v])
$$

- $v$ **已访问且不在栈中**：说明 $v$ 已经属于另一个处理完的 SCC，直接跳过。

回溯时若 `dfn[u] == low[u]`，$u$ 就是当前 SCC 的根，此刻栈中从栈顶到 $u$ 的所有点正好构成这个 SCC，一起弹出来即可。

## 逐行代码解析

下面把整份模板按模块拆开讲，各块按顺序拼起来就是完整代码。

### 头文件与宏定义

```cpp
#include<bits/stdc++.h>
#define endl '\n'
#define fi first
#define se second
#define lowbit(x) x&(-x)
#define int long long
using namespace std;
typedef pair<int,int> PII;
typedef long long ll;
//const int N=1e5+10;
//int cnt=0;
//int a[N];
inline int read();
inline void write(int x);
```

- `#define int long long` 是把全局的 `int` 偷换成 `long long` 的常用套路，代价是常数变大；开了它，`main` 要写成 `signed main()`。
- 提前声明 `read` / `write`，方便在 `main` 里直接用（编译器要在使用前看到声明）。

### 全局变量

```cpp
const int MAXN = 10005;
vector<int> G1[MAXN];  // 邻接表存储有向图
int dfn[MAXN], low[MAXN], scc[MAXN];  // scc[u]表示u所属的SCC编号
stack<int> st;
int idx = 0, tot = 0;  // 时间戳、SCC数量
bool vis[MAXN];  // 标记是否在栈中
```

- `scc[u]` 记录点 $u$ 属于第几个 SCC，是后面缩点的基础。
- `vis[u]` 记录 $u$ **是否还在栈里**，这是判断「已访问且在栈中」的依据。

### tarjan 函数

```cpp
void tarjan(int u) {
    dfn[u] = low[u] = ++idx;
    st.push(u);
    vis[u] = true;
    for (int v : G1[u]) {
        if (!dfn[v]) {  // v未访问
            tarjan(v);
            low[u] = min(low[u], low[v]);
        } else if (vis[v]) {  // v已访问且在栈中（回边）
            low[u] = min(low[u], dfn[v]);
        }
    }
    // 找到SCC的根
    if (dfn[u] == low[u]) {
        tot++;
        int v;
        do {
            v = st.top();
            st.pop();
            vis[v] = false;
            scc[v] = tot;
        } while (v != u);
    }
}
```

- 进入时先打时间戳、入栈、置 `vis = true`。
- 注意第二支用的是 `dfn[v]` 而不是 `low[v]`：已访问且在栈中的点，只能通过它**本身的**时间戳来更新，写错了会连成一片。
- 弹出时用 `do…while`，保证根 $u$ 自己也被弹出。

