### 快读快写

```cpp
inline int read(){
    int x=0,f=1;
    char ch=getchar();
    while(ch< '0'||ch>'9'){
        if(ch=='-') f=-1;
        ch=getchar();
    }
    while(ch>='0'&&ch<='9'){
        x=(x<<1)+(x<<3)+(ch^48);
        ch=getchar();
    }
    return x*f;
}
inline void write(int x){
    if(x<0){
        putchar('-');
        x=-x;
    }
    if(x>9) write(x/10);
    putchar(x%10+'0');
}
```

- `read` 用 `x = (x<<1) + (x<<3) + (ch^48)`，等价于 `x = x*10 + (ch-'0')`，位运算更快。
- `write` 是递归版，先把高位输出完再输出末位，天然就是正序。

## 复杂度分析

每个点、每条边都只被处理常数次：入栈出栈各一次，遍历邻接表总计 $O(m)$，所以

- 时间复杂度：$O(n + m)$，严格线性，没有 $\log$。
- 空间复杂度：$O(n + m)$，即邻接表加上三个数组。

## 适用场景

- **缩点**：把 SCC 缩成点后原图变 DAG，接着就能在上面跑拓扑 / DP（如最长路、方案计数）。
- **判环 / 找环**：一个 SCC 大小大于 1 就说明有环。
- **2-SAT、传递闭包**等有向图结构问题的前置步骤。
- 需要「有向图强连通结构」时优先用 Tarjan；如果只是无向图割点 / 桥，那是另一套 Tarjan 变体。

## 常见陷阱与注意事项

1. **`low` 更新用错数组**：已访问且在栈中的点要用 `dfn[v]`，未访问的点递归后用 `low[v]`，这两个别搞混。
2. **忘记判 `vis[v]`**：如果只用 `dfn[v]` 判「访问过」，会把已经出栈、属于别的 SCC 的点也算进来，结果全错。
3. **链状图爆栈**：递归 Tarjan 在一条长链上可能爆栈，必要时开大栈或改写迭代版。
4. **多组数据要清空**：`dfn` / `low` / `scc` / 邻接表在每组数据前都要重置。
5. **图的编号从 0 开始**：`dfn[u]` 未访问判断依赖初值为 0，若点编号含 0 要特殊处理。

## 对比与扩展

| 维度 | Tarjan | Kosaraju |
|---|---|---|
| DFS 次数 | 1 次（原图） | 2 次（原图 + 反图） |
| 是否需要反图 | 不需要 | 需要 |
| 时间复杂度 | $O(n+m)$ | $O(n+m)$ |
| 代码量 / 常数 | 小 / 小 | 稍大 / 稍大 |

扩展方向：

- **缩点建新图**：把 `scc[u]` 当作新点编号，遍历原边去重后得到 DAG（对应 `graph-scc-condensation`、`graph-scc-dag-dp`）。
- **无向图 Tarjan**：同一套 `dfn` / `low` 思想还能求割点、桥、边双 / 点双连通分量，注意无向图要处理「走过的反向边」。$AKB253$, '图论', array['图论', '强连通分量', 'Tarjan', 'DFS', '缩点'], 'col-graph-scc-overview', null, 'knowledge'),
('world-needs-sunday', 'col-graph-tarjan-scc', 'Tarjan 强连通分量', $AKB254$## 算法原理

Tarjan 算法由 Robert Tarjan 于 1972 年提出，基于**一次深度优先搜索（DFS）**找出有向图中所有的强连通分量（Strongly Connected Components, SCC），时间复杂度为 $O(n+m)$。

### 什么是强连通分量

在有向图中，若两个节点 $u$ 和 $v$ 互相可达（即存在 $u \to v$ 的路径，也存在 $v \to u$ 的路径），则称它们强连通。图中**极大的强连通子图**称为强连通分量。

强连通分量的意义在于：**将每个 SCC 缩成一个点后，原图变成 DAG**，从而可以用拓扑排序等 DAG 专属算法高效解决问题。

### 核心思想

在 DFS 过程中，用两个关键数组标记每个节点：

| 数组 | 含义 |
|------|------|
| `dns[u]`（dfn） | 节点 $u$ 被首次访问的时间戳（DFS 序） |
| `low[u]` | 从 $u$ 出发，通过**一条返祖边**或通过**后代的返祖边**能回到的最早节点的时间戳 |

核心结论：**当 `dfs[u] == low[u]` 时，以 $u$ 为根的子树中所有仍在栈里的节点恰好构成一个强连通分量。**

### 为什么正确

- 如果 `low[u] < dns[u]`，说明 $u$ 能通过某条路径回到更早的祖先，因此 $u$ 一定和那个祖先在同一个 SCC 中
- 如果 `low[u] == dns[u]`，说明 $u$ 无法回到任何更早的节点，它就是当前 SCC 的"最高点"（根），此时栈中从 $u$ 到栈顶的所有节点都属于这个 SCC

## 算法步骤

1. **初始化**：`dns`、`low` 全为 0（未访问），栈为空，时间戳 `tim = 1`，分量计数 `cnt = 0`
2. **遍历所有节点**：对每个未访问的节点启动 DFS
3. **DFS 过程**：
   - 标记当前节点的 `dns` 和 `low`，将节点压入栈并标记在栈中
   - 遍历每条出边：
     - 若后继未访问：递归 DFS，回溯时更新 `low[u] = min(low[u], low[v])`
     - 若后继已访问且仍在栈中（返祖边）：更新 `low[u] = min(low[u], dns[v])`
   - 遍历结束后，若 `dns[u] == low[u]`：弹出栈中元素直到包含 $u$，这些节点构成一个 SCC

## 逐行代码解析

### 变量与数组

```cpp
vector<vector<int>> edges, ans;  // 邻接表 / 各分量的节点列表
vector<int> sk, dns, low, col;   // 栈 / 时间戳 / 能回退的最早时间 / 所属分量
vector<bool> in_sk;              // 节点是否在栈中
int idx, tim, cnt;               // 栈顶指针 / 时间戳 / 分量计数
```

### 初始化

```cpp
inline void init(int n)
{
    idx = 0, tim = 1, cnt = 0;
    sk.assign(n + 1, 0);
    in_sk.assign(n + 1, false);
    dns.assign(n + 1, 0);
    low.assign(n + 1, 0);
    col.assign(n + 1, 0);
    ans.assign(1, {});  // ans[0] 占位，分量从 1 开始
}
```

### 标记节点首次访问

```cpp
inline void mark(int rt)
{
    dns[rt] = tim;
    low[rt] = tim;   // 初始假设只能回到自己
    sk[idx++] = rt;  // 入栈
    in_sk[rt] = true;
    tim++;
}
```

### Tarjan DFS 主体

```cpp
void tarjan(int rt)
{
    mark(rt);
    for (int i : edges[rt])
    {
        if (!dns[i])          // 树边：后继未访问
        {
            tarjan(i);
            low[rt] = min(low[rt], low[i]);  // 用儿子的low更新自己
        }
        else if (in_sk[i])    // 返祖边：后继已访问且在栈中
            low[rt] = min(low[rt], dns[i]);  // 用后继的dfn更新自己
    }
    if (dns[rt] == low[rt])   // rt是SCC的根
    {
        ++cnt;
        ans.emplace_back();
        while (in_sk[rt])     // 弹出到rt为止的所有节点
        {
            col[sk[idx - 1]] = cnt;       // 标记所属分量
            ans[cnt].emplace_back(sk[idx - 1]);
            in_sk[sk[idx - 1]] = false;
            --idx;
        }
    }
}
```

### 主函数：处理不连通图

```cpp
for (int i = 1; i <= n; i++)
{
    if (!dns[i]) tarjan(i);  // 每个未访问的节点都要启动一次DFS
}
```

图可能不连通，需要对每个连通分量分别运行 Tarjan。

## 复杂度分析

- **时间复杂度**：$O(n+m)$
  - 每个节点恰好入栈一次、出栈一次
  - 每条边恰好被访问一次
  - DFS 总代价线性
- **空间复杂度**：$O(n+m)$
  - 邻接表：$O(m)$
  - dns、low、col、in_sk、栈：$O(n)$

## 适用场景

1. **强连通分量检测**：找出图中所有 SCC，常用于图的结构分析
2. **缩点**：将每个 SCC 缩成一个点，把一般有向图转化为 DAG，然后做拓扑 DP、最长路等
3. **2-SAT 问题**：利用 Tarjan 求 SCC 后，根据每个变量的两个状态是否在同一 SCC 中判断可行性
4. **有向图的连通性问题**：判断两个节点是否互相可达

## 常见陷阱与注意事项

1. **in_sk 的判断**：返祖边的条件是 `dns[i] != 0 && in_sk[i] == true`，不能只判断 `dns[i] != 0`。因为如果 `i` 已经被弹出栈（属于其他 SCC），就不是返祖边而是横叉边
2. **low 的更新方式**：树边用 `low[v]` 更新，返祖边用 `dns[v]` 更新（不是 `low[v]`）。返祖边只能跳一步，不能用后代的 low 值
3. **栈的弹出条件**：当 `dns[rt] == low[rt]` 时，弹出**从栈顶到 rt** 的所有节点，不是只弹 rt
4. **多连通分量**：图可能不连通，必须遍历所有节点，对未访问的都跑一次 Tarjan
5. **ans 的索引**：代码中 `ans.assign(1, {})` 让 ans 从下标 1 开始，分量编号从 1 到 cnt
6. **变量名 dns**：部分教材写作 dfn（depth-first number），含义相同
7. **DFS 边的四类分类**：有向图的 DFS 会把每条边归为四类——**树边**（tree edge，指向未访问节点的边）、**返祖边**（back edge，指向仍在栈中祖先的边）、**横叉边**（cross edge，指向已访问且已出栈节点的边）、**前向边**（forward edge，指向已访问后代节点的边）。判断口诀：

```
访问边 u->v 时：
  若 v 未访问             -> 树边
  否则若 v 在栈中         -> 返祖边
  否则若 dns[v] > dns[u]  -> 前向边
  否则                    -> 横叉边
```

   其中只有**树边**与**返祖边**参与 `low` 的更新，前向边和横叉边被直接忽略：横叉边终点已属于其他 SCC，前向边不携带"回到更早节点"的信息。缩点后图中不再存在返祖边，这正是"缩点图是 DAG"的直观原因。

8. **链状图递归爆栈**：Tarjan 采用递归实现，当图是一条很长的链时，DFS 深度可达 $O(n)$。若 $n$ 达到 $10^5$、$10^6$ 量级，系统栈极易溢出（stack overflow）。这类数据下应改用**显式栈的迭代版 DFS**，或增大栈空间。

## 缩点：SCC 的典型应用

求出 SCC 后，可以构建**缩点图**：每个 SCC 是一个新节点，原图中跨 SCC 的边变成缩点图中的边。缩点图一定是 DAG。

```cpp
// 伪代码：构建缩点图
vector<vector<int>> new_edges(cnt + 1);
for (int u = 1; u <= n; u++)
    for (int v : edges[u])
        if (col[u] != col[v])
            new_edges[col[u]].push_back(col[v]);
```

缩点后可以做：
- 拓扑排序上的 DP（比如求经过节点权值最大的路径）
- 求 DAG 上的最长路/最短路
- 统计入度为 0 的缩点个数（至少需要多少个起点才能走遍全图）

## 与 Kosaraju 算法对比

| 算法 | 思路 | DFS 次数 | 常数 | 直观程度 |
|------|------|---------|------|---------|
| Tarjan | 一次DFS + 栈 + dfn/low | 1 次 | 小 | 较难理解 |
| Kosaraju | 正向DFS出栈序 + 反向图DFS | 2 次 | 稍大 | 直观易理解 |

两者时间复杂度相同（都是 $O(n+m)$），Tarjan 只需要一次 DFS 所以常数更小；Kosaraju 思路更清晰但代码稍长。竞赛中 Tarjan 更常用。$AKB254$, '图论', array['图论', '强连通分量', 'Tarjan', 'DFS', '缩点'], 'col-graph-scc-overview', null, 'knowledge'),
('Xesir', 'col-graph-topo-sort--xesir', '拓扑排序（Kahn 算法·BFS） · Xesir', $AKB255$## 算法原理

有一堆任务，有些任务必须在另一些任务之前完成。问：能不能把所有任务排成一个线性顺序，使得每个任务的所有前置任务都排在它前面？

这就是**拓扑排序**。

**定义**：对一个**有向无环图**（DAG）的所有顶点进行线性排序，使得对于每条有向边 $u \to v$，$u$ 都排在 $v$ 的前面。

**关键前提**：只有 DAG 才有拓扑排序。如果图里有环，就永远排不出来（环上的任务互相依赖，不存在先后关系）。

**Kahn 算法（BFS 版）** 的步骤：

1. 统计每个点的入度（即有多少条边指向它）。
2. 把所有入度为 0 的点入队（这些点没有任何前置依赖，可以最先做）。
3. 每次从队列里取出一个点 $u$，把它加入拓扑序列；然后遍历 $u$ 的所有出边 $u \to v$，把 $v$ 的入度减 1。如果 $v$ 的入度变成 0，就把 $v$ 入队。
4. 重复直到队列为空。如果最后拓扑序列的长度小于总点数，说明图里有环，无法拓扑排序。

## 核心公式 / 状态定义与转移方程

入度约束（对每条边 $u \to v$）：

$$d^-(v) \leftarrow d^-(v) - 1$$

当某个点入度降为 $0$ 时即可入队：

$$v \in Q \iff d^-(v) = 0$$

最终判定：

$$\text{拓扑序列长度} = n \;\Rightarrow\; \text{是 DAG};\quad < n \;\Rightarrow\; \text{有环}$$

## 逐行代码解析

下面把整份模板按模块拆开讲，各块按顺序拼起来就是完整代码。

### 模块一：头文件与全局变量

```cpp
#include <bits/stdc++.h>
using namespace std;
const int N=1e9;
bool v[N];
vector<vector<int>> s(N);
int h[N];
vector<int> pai;
queue<int> q;
int n,m;
```

- `s` 是邻接表，`s[x]` 存 `x` 的所有后继；`h` 记录每个点的入度。
- `pai` 用来存拓扑序列，`q` 是 Kahn 算法的 BFS 队列。
- `bool v[N]` 这份代码里其实没用上；另外 `N` 开成了 `1e9`，见下面"常见陷阱"。

### 模块二：读边并统计入度

```cpp
int main() {
    cin>>n>>m;
    for (int i=1;i<=m;i++) {
        int x,y;
        cin>>x>>y;
        s[x].push_back(y); 
        h[y]++;
    }
```

- 读 $n$ 个点、$m$ 条有向边。
- 对每条边 $x \to y$：把它加进 `s[x]`，同时给 `y` 的入度 `h[y]` 加 1。

### 模块三：入队初始点 + Kahn 主循环

```cpp
    for(int i=1;i<=n;i++){
        if(h[i]==0){
            q.push(i);
            pai.push_back(i);             
        }
    }
    while (q.size()) {
        int t=q.front();
        q.pop();                 
        for(int j:s[t]){            
            h[j]--;
            if(h[j]==0){q.push(j);pai.push_back(j);}            
        } 
    }
```

- 先扫一遍所有点，把入度为 0 的点入队、并同时放进 `pai`。
- 主循环里取出队首 `t`，遍历它的所有后继 `j`，把 `h[j]` 减 1；一旦某个 `j` 的入度减到 0，就入队并追加到 `pai`。

### 模块四：输出拓扑序 / 判环

```cpp
    if(pai.size()==n){
        for(auto i:pai){
            cout<<i<<" ";
        }
    }else{
        cout<<-1;
    }
    return 0;
}
```

- 如果 `pai` 里恰好有 $n$ 个点，说明所有点都被排进去了，输出这个拓扑序。
- 否则说明有环排不出来，输出 `-1`。

## 复杂度分析

- 时间复杂度：$O(n+m)$，每个点、每条边都只被处理常数次。
- 空间复杂度：$O(n+m)$，邻接表加上入度、序列、队列几个数组。

## 适用场景

- **判断图是否有环**：能拓扑排序就是 DAG，否则有环。
- **DP 顺序**：树上或 DAG 上的 DP（最长路、方案数等）需要按拓扑序计算。
- **任务调度**：确定任务的先后执行顺序。
- **依赖解析**：比如包管理工具处理软件包依赖。

拓扑排序本身不算"难题"，但它经常作为其他算法的前置步骤出现。比如树形 DP 里的"先算子树再合并"，本质上就是一种树上的拓扑序——很能体现图论的万金油性质。

## 常见陷阱与注意事项

1. **数组上限写成了 `1e9`**：`const int N=1e9; bool v[N]; int h[N];` 这么写数组根本开不出来（`h` 要 4 GB），`vector<vector<int>> s(N)` 也会构造 $10^9$ 个空 vector。实战要按数据范围把 `N` 改小（比如 $10^5$）。
2. **`bool v[N]` 没用上**：这份模板里它是个"僵尸数组"，真正参与判环的是 `pai.size()` 和总数 $n$ 的比较。
3. **只对 DAG 有效**：有环时输出 `-1` 或者序列长度不足，别把它当成"万能排序"。
4. **入度数组与邻接表要同步清空**：多组数据时 `h`、`s`、`q`、`pai` 每组都要重置。
5. **入队时机**：初始入度为 0 的点要一次性入队；后续只有在入度**刚减到 0** 时才入队，重复入队会出错。

## 对比与扩展

Kahn（BFS 版）思路直观、天然能判环，是最常用的写法；另一种是 **DFS 版**——对每个点做 DFS，在递归返回时把当前点压栈，最后栈的逆序就是拓扑序，同时也能检测环（DFS 中遇到还在递归栈里的点即有环）。两者复杂度相同，Kahn 更好写、也更容易做"字典序最小拓扑序"之类的变形。$AKB255$, '图论', array['图论', '拓扑排序', 'Kahn', 'BFS', 'DAG', '判环', '入度'], null, null, 'knowledge'),
('world-needs-sunday', 'col-graph-topo-sort', '拓扑排序（Kahn算法/BFS）', $AKB256$## 算法原理

拓扑排序用于将有向无环图（DAG）的所有顶点排成一个线性序列，使得对每条有向边 $(u, v)$，$u$ 在序列中排在 $v$ 之前。Kahn 算法采用 BFS 风格的实现：反复取出当前入度为 $0$ 的顶点加入拓扑序列，并删除该顶点的所有出边（即将其后继节点的入度减一），当某个后继的入度降为 $0$ 时将其加入队列。

算法初始化时扫描所有顶点，将入度为 $0$ 的顶点一次性入队。随后进入主循环：每次从队列中取出一个顶点，遍历其所有出边，将目标顶点的入度减一。若入度降为 $0$，说明该顶点不再有未处理的前驱，将其入队并加入拓扑序列。这一过程持续直到队列为空。

拓扑排序的一个重要性质是判环能力：若图是 DAG，则所有 $n$ 个顶点都会被输出；若图中存在环，则环上顶点的入度永远无法降为 $0$（因为环中每个顶点至少有一条来自环内其他顶点的入边未被删除），最终输出的顶点数小于 $n$。代码中用 `cnt` 计数已输出顶点，初始为 $n$，每输出一个减一，结束时若 `cnt != 0` 则说明存在环。

## 核心公式

拓扑序约束（对每条边 $(u, v) \in E$）：
$$\text{pos}(u) < \text{pos}(v)$$

Kahn 算法的迭代规则（$d^-(v)$ 为入度）：
$$v \in Q \iff d^-(v) = 0 \text{ 且尚未输出}$$

取顶点 $u$ 出队后对其后继 $v$ 更新入度：
$$d^-(v) \leftarrow d^-(v) - 1, \quad \text{if } d^-(v) = 0 \text{ then } v \text{ 入队}$$

判环条件（输出顶点数 $C$）：
$$\text{有环} \iff C < n$$

## 逐行代码解析

按逻辑阶段把程序拆成 5 个模块，各模块代码顺序拼接即为完整 `.cpp`。

### 模块一：头文件与全局变量

```cpp
#include<bits/stdc++.h>
using namespace std;
vector<vector<int>> edges;   // 邻接表
int n,m;                     // 顶点数、边数
```

- `edges` 用 `vector<vector<int>>` 存邻接表，只存实际出边，比邻接矩阵省空间，适合稀疏图。
- `n`、`m` 声明为全局变量，供建图、初始化、BFS 各阶段共用。

### 模块二：读入与建图（main 开头）

```cpp
int main()
{
	cin >> n >> m;
	edges.resize(n + 1);
	vector<int> q(n + 1 , 0);   // q[i] = 顶点 i 的入度
	vector<int> ans;           // 拓扑序列
	int cnt = n;               // 剩余未输出顶点计数
	for(int i = 0;i < m;i++)
	{
		int a,b;
		cin >> a >> b;
		edges[a].emplace_back(b);   // 建边 a -> b
		q[b]++;                     // b 的入度 +1
	}
```

- `edges.resize(n + 1)` 与 `q(n + 1, 0)` 都按顶点编号 `1..n` 预留空间，编号超出该范围会越界。
- `edges[a].emplace_back(b)` 与 `q[b]++` 成对出现：建邻接表的同时统计入度，一遍读入完成图结构构建。
- `cnt` 初始为 `n`，之后每输出一个顶点减一，结束时用 `cnt` 是否归零来判环。

### 模块三：初始化入队（入度为 0 的点）

```cpp
	queue<int> que;
	for(int i = 1;i <= n;i++)   // 初始化：入度为 0 的点入队
	{
		if(q[i] == 0)
		{
			que.emplace(i);
			ans.emplace_back(i);
			cnt--;
		}
	}
```

- 扫描所有顶点，把入度为 $0$ 的点一次性入队，保证多源并行推进——图中可有多个无前驱的起点同时开始拓扑。
- 入队的同时就写入 `ans` 并 `cnt--`，所以最终 `ans` 存的就是顶点被输出的顺序。

### 模块四：BFS 主循环（删边 + 后继入队）

```cpp
	while(!que.empty())
	{
		int i = que.front();
		que.pop();
		for(int idx : edges[i])   // 遍历 i 的所有出边
		{
			q[idx]--;             // 后继入度 -1（删除边 i->idx）
			if(q[idx] == 0)       // 入度降为 0，入队
			{
				que.emplace(idx);
				ans.emplace_back(idx);
				cnt--;
			}
		}
	}
```

- `q[idx]--` 是"删除边"的隐式实现：取出顶点 $i$ 后删除其所有出边，等价于后继入度减一，无需真正改动邻接表。
- `if(q[idx] == 0)`：入度降为 $0$ 意味着该顶点所有前驱已被输出，可安全加入拓扑序列。
- 每个顶点最多入队一次：入度一旦归零就不会再被减，不会重复入队，所以 `cnt` 不会减成负数。

### 模块五：判环与输出

```cpp
	if(cnt) cout << "有环" << endl;  // 未输出全部顶点 -> 存在环
	else
	{
		for(int i = 0;i < n;i++) cout << ans[i] << " ";
	}
	
	return 0;
}
```

- `cnt != 0` 说明有顶点始终未被输出，这些顶点处于环中（入度永远无法归零），因此存在环。
- 无环时 `ans.size() == n`，`for(i=0;i<n;i++)` 逐个打印即得一种合法拓扑序，不会越界。
- 有环分支只输出"有环"，不打印 `ans`，避免输出残缺序列。

## 复杂度分析

每个顶点最多入队、出队各一次，每次出队时遍历其所有出边。所有顶点的出边总数等于边数 $m$，因此总遍历次数为 $O(n + m)$。入度的维护（初始化扫描和每次减一）均为 $O(1)$ 操作。空间上邻接表存储 $m$ 条边、入度数组和队列各 $O(n)$，总空间复杂度为 $O(n + m)$。这是图遍历类算法的最优复杂度。

## 适用场景

任务调度与依赖关系排序（如编译顺序、课程先修关系）、判断有向图是否有环（判环）、DAG 上动态规划的预处理（按拓扑序处理保证状态依赖已就绪）、关键路径分析的前置步骤等。

## 常见陷阱与注意事项

1. **入度为 0 的初始化遗漏**：必须在建图后扫描所有顶点找出初始入度为 $0$ 的点。若遗漏则队列始终为空，所有顶点都不被输出，错误判定为有环。
2. **`cnt` 初值与判环逻辑**：`cnt` 初始为 $n$，每输出一个减一。判环时检查 `cnt != 0`（即 `cnt` 为真）。若误将 `cnt` 初始为 $0$ 且递增，则逻辑反转容易出错。
3. **拓扑序不唯一**：当多个顶点同时入度为 $0$ 时，入队顺序不同会导致不同的拓扑序。若题目要求字典序最小的拓扑序，应用优先队列（小根堆）代替普通队列。
4. **自环与重边**：自环 $(u, u)$ 使 $u$ 的入度永远无法归零，会被正确判定为环。重边会增加入度计数但不会影响正确性（多条边删除后入度才归零）。
5. **顶点编号不从 1 开始**：代码假设顶点编号为 $1 \sim n$。若编号从 $0$ 开始或离散，需调整循环范围或使用映射。
6. **队列 vs 栈**：用队列（FIFO）得到的是 BFS 风格拓扑序，用栈（LIFO）得到的是 DFS 风格拓扑序。两者都是合法拓扑序，但具体顺序不同。

## 对比与扩展

与基于 DFS 的拓扑排序（逆后序）相比，Kahn 算法（BFS 风格）更直观且天然支持判环，无需处理递归栈深度问题。DFS 拓扑排序利用"完成时间"的逆序，在需要同时求强连通分量时更方便（如 Tarjan 算法）。扩展方向包括：用优先队列求字典序最小/最大的拓扑序、在拓扑排序过程中同步进行 DAG 上 DP（如最长路、最短路、关键路径）、以及将 Kahn 算法推广到求最小拓扑序约束下的顶点染色等问题。$AKB256$, '图论', array['图论', '拓扑排序', 'Kahn算法', 'BFS', 'DAG', '判环'], null, null, 'knowledge'),
('Fohen', 'col-graph-tree-basic--fenfeng', '树论基础 · Fohen', $AKB257$## 算法原理

树是图论中最特殊、也最重要的一类图。它不仅在算法竞赛中频繁出现，而且很多复杂图论问题（如网络流、树链剖分）的解题起点，就是先把图转化成树来处理。可以说，掌握了树，就掌握了图论的大半。

### 树的定义与性质

**定义**：树是一个**连通且无环**的无向图。这意味着树上任意两个顶点之间有且仅有一条简单路径；若一棵树有 $n$ 个顶点，那么它恰好有 $n-1$ 条边。

由「连通性」和「无环性」可以推出许多重要性质：

- 树是**边数最少的连通图**：再少一条边就不连通了。
- 树是**边数最多的无环图**：再多一条边就会出现环。
- 任意两个顶点之间有且仅有一条简单路径（这是树最核心的性质）。
- 删去一条边会把树分成两个连通块；加一条边会产生唯一一个环。

**有根树与无根树**：若给树指定一个特殊顶点作为「根」，就得到有根树。根的存在引入了父子关系、子树、深度等概念，树形 DP 等大量算法都建立在有根树上。

### 树为什么重要

树本质上是一种特殊的图，因此图上的 DFS、BFS 都能直接用于树上，而且树的结构会让搜索更简单、更高效：

1. 树上 DFS 不会「重复访问」（因为无环），因此不必维护 visited 数组，只需在递归时传入父节点防止往回走。
2. 树的深度优先遍历天然具有「先处理子树、再回溯」的结构，与树形 DP 的「自底向上」过程完美契合。
3. 树上的 BFS 可以快速求出每个节点到根的距离（深度），这也是求边权为 1 时最短路的简单方式。

## 核心公式 / 状态定义与转移方程

### 树的边数与路径

- **边数**：$n$ 个顶点的树恰有 $n-1$ 条边。
- **路径唯一性**：任意两点 $u,v$ 之间存在且仅存在一条简单路径。

### 树的直径

直径是树上最长的简单路径。经典求法是**两次 DFS**：任选一点 $s$ 找最远点 $u$，再从 $u$ 出发找最远点 $v$，则 $u$ 到 $v$ 即为一条直径，长度为 $\text{dist}(u,v)$。第一次找到的点 $u$ 一定是某条直径的端点，该性质只对树成立。

直径的中点称为树的**中心**，它位于直径的正中间（直径长度为奇数时中心是一条边），是所有点中「到最远点距离最小」的平衡点。

### 树的重心

重心是删除后使剩余各连通块中**最大块大小最小**的节点。删去节点 $u$ 后，最大的连通块大小为

$$
\max\Bigl(\max_{v \in \text{child}(u)} sz[v],\ n - sz[u]\Bigr)
$$

使该值取最小的节点即为重心。树最多有两个重心，且若有两个，它们相邻。

### 最近公共祖先（LCA）的树上距离

若记 $\text{dep}[x]$ 为节点 $x$ 的深度（无权树），则

$$
\text{dist}(u,v) = \text{dep}[u] + \text{dep}[v] - 2\,\text{dep}[\text{LCA}(u,v)]
$$

若边带权，只需把 $\text{dep}$ 换成「根到该点的路径总权值」即可。这是处理树上路径问题的核心工具。

### 倍增法递推式

设 $f[u][k]$ 表示节点 $u$ 向上跳 $2^k$ 步到达的祖先，则

$$
f[u][0] = \text{parent}[u],\qquad f[u][k] = f\bigl[f[u][k-1]\bigr][k-1]\quad(k \ge 1)
$$

## 逐行代码解析

以下均为**思想步骤伪代码**，用于说明做法流程，不必与具体实现逐字对应。

### 树的 DFS 遍历

```cpp
void dfs(int u, int fa) {
    dep[u] = dep[fa] + 1;      // 记录深度
    sz[u]  = 1;                // 子树大小初始为 1
    for (int v : G[u]) {
        if (v == fa) continue; // 无环，只需防止走回父节点
        dfs(v, u);             // 递归处理子树
        sz[u] += sz[v];        // 回溯时累计子树大小
    }
}
```

- 由于树无环，不需要 visited 数组；`fa` 用于避免沿来路返回。
- 进入时先处理当前点，回溯时再汇总子树信息，正好对应「自底向上」。

### 求树的直径（两次 DFS）

```cpp
// 第一次：从任意点 s 出发找最远点 u
u = farthest(s);
// 第二次：从 u 出发找最远点 v
v = farthest(u);
// 直径长度 = dist(u, v)
```

- 第一次找到的 $u$ 必是某条直径的一个端点，因此第二次从 $u$ 出发即可得到直径。
- `farthest` 就是一次 DFS/BFS，顺带记录每个点的最远距离与来源。

### 求树的重心

```cpp
void dfs(int u, int fa) {
    sz[u] = 1;
    int big = 0;                    // 删去 u 后最大连通块的大小
    for (int v : G[u]) {
        if (v == fa) continue;
        dfs(v, u);
        sz[u] += sz[v];
        big = max(big, sz[v]);      // 各子树块
    }
    big = max(big, n - sz[u]);      // 上方那一整块
    if (big < ans) {                // ans 为当前最小"最大块"
        ans = big;
        centroid = {u};
    } else if (big == ans) {
        centroid.push_back(u);      // 重心最多两个且相邻
    }
}
```

### LCA 倍增法

```cpp
// 预处理：每个节点向上 2^k 步的祖先
void dfs(int u, int fa) {
    dep[u] = dep[fa] + 1;
    f[u][0] = fa;
    for (int k = 1; k <= LOG; k++)
        f[u][k] = f[f[u][k-1]][k-1];
    for (int v : G[u]) if (v != fa) dfs(v, u);
}

// 查询
int lca(int u, int v) {
    if (dep[u] < dep[v]) swap(u, v);
    for (int k = LOG; k >= 0; k--)       // 第一步：深度对齐
        if (dep[f[u][k]] >= dep[v]) u = f[u][k];
    if (u == v) return u;                // v 恰是 u 的祖先
    for (int k = LOG; k >= 0; k--)       // 第二步：同步上跳
        if (f[u][k] != f[v][k]) u = f[u][k], v = f[v][k];
    return f[u][0];                      // 停在 LCA 的直接子节点上
}
```

## 复杂度分析

树本身是概念，不绑定单一实现；各算法的复杂度如下：

| 操作 / 算法 | 时间复杂度 | 空间复杂度 |
|---|---|---|
| 树的遍历 / 求直径 / 求重心 | $O(n)$ | $O(n)$ |
| LCA 倍增法 | 预处理 $O(n\log n)$，查询 $O(\log n)$ | $O(n\log n)$ |
| LCA Tarjan 离线 | 总 $O(n + q\,\alpha(n))$ | $O(n+q)$ |
| LCA 欧拉序 + ST 表 | 预处理 $O(n\log n)$，查询 $O(1)$ | $O(n\log n)$ |

其中 $n$ 为节点数，$q$ 为询问数，$\alpha$ 为反阿克曼函数（实际可视为常数）。总体上，树的常见基础操作多为 $O(n)$ 或 $O(n\log n)$ 级别。

## 适用场景

- **树形 DP**：树的「先处理子树、再回溯」结构与自底向上 DP 天然契合，广泛用于树上选点、树上背包等问题。
- **路径查询与统计**：借助 LCA 可 $O(\log n)$（或更优）回答树上距离、路径权值和等询问。
- **树上差分**：对路径批量加值后通过子树和还原，需要用 LCA 标记路径端点。
- **点分治 / 树分治**：重心保证每次删点后最大连通块不超过一半，使分治深度为 $O(\log n)$。
- **特殊形态转换**：链可以转成序列用线段树、前缀和处理；满二叉树等平衡形态适合分治与剪枝。
- **判断祖先关系**：$\text{LCA}(u,v)=u$ 当且仅当 $u$ 是 $v$ 的祖先。

## 常见陷阱与注意事项

- **DFS 忘记传父节点**：树虽无环，但若不加 `fa` 判断，会沿来路反复递归导致死循环或重复计数。
- **无根树必须先指定根**：涉及深度、子树大小等概念时，需先任选一个根转化为有根树。
- **两次 DFS 求直径只对树成立**：它依赖「最远点必是直径端点」这一树特有性质，不能直接套用到一般图或带负权图上。
- **重心的两个细节**：重心最多两个且相邻；判断条件可用「删去后各连通块大小均 $\le n/2$」，与「最大块最小」等价。
- **LCA 倍增要先对齐深度**：必须先把较深的节点上跳到同一深度，再同步上跳，顺序不能颠倒。
- **Tarjan 只能离线**：它需要一次性读入所有询问，无法应对动态增加的询问。
- **欧拉序长度为 $2n-1$**：每个节点「进入」「离开」各记录一次，共 $2n-1$ 个位置，不是 $n$。
- **区分重心与中心**：重心最小化「删点后最大连通块」，中心最小化「到所有点的最远距离」，两者含义不同。

## 对比与扩展

### LCA 三种求法对比

| 求法 | 预处理 | 单次查询 | 在线 | 特点 |
|---|---|---|---|---|
| 倍增法 | $O(n\log n)$ | $O(\log n)$ | 是 | 最常用、稳定，可顺带维护路径信息 |
| Tarjan 离线 | $O(n+q\,\alpha(n))$ | 均摊 $O(\alpha(n))$ | 否 | 总时间接近线性，适合询问极多的场景 |
| 欧拉序 + ST 表 | $O(n\log n)$ | $O(1)$ | 是 | 查询最快，但不支持修改 |

### 树的特殊形态对比

| 形态 | 特征 | 典型处理 |
|---|---|---|
| 链 | 每个节点度数最多为 2 | 转为序列问题，用前缀和、线段树处理 |
| 菊花图 | 一个中心节点连接其余所有点 | 贪心、DP 往往有简化性质 |
| 二叉树 | 每个节点最多两个子节点 | 用左右儿子设计状态，降低转移复杂度 |
| 满 / 完全二叉树 | 高度 $O(\log n)$ | 适合分治与搜索剪枝 |

### 树与一般图

树是一般无向图的特例（连通且无环），因此树上算法比一般图更简单、更高效；反过来，很多一般图问题的第一步是**把图转化为树**（如缩点、最小生成树、树链剖分），再在树上求解。

### 可延伸的方向

- **树链剖分**：把树拆成若干重链，配合线段树实现路径与子树的批量修改/查询。
- **点分治 / 边分治**：利用重心递归分治处理树上路径统计。
- **虚树**：在关键点极少时压缩原树，降低 DP 规模。
- **树上差分 / 树上启发式合并（DSU on Tree）**：进一步优化树上路径与子树统计。$AKB257$, '图论', array['图论', '树', '树的直径', '树的重心', '最近公共祖先'], null, null, 'knowledge'),
('Xesir', 'col-graph-tree-basic--xesir', '树论基础 · Xesir', $AKB258$## 算法原理

树是图论里最特殊也最重要的一类图。它不仅在算法竞赛中频繁出现，而且很多复杂图论问题（如网络流、树链剖分）的解题起点就是先把图转化成树来处理。可以说，**搞懂了树，就搞定了一半的图论**。 ~~不是你还二分上了~~

### 树的定义与性质

**定义**：树是一个**连通且无环**的无向图。

也就是说，树上任意两个顶点之间有且仅有一条简单路径。如果一棵树有 $n$ 个顶点，那么它恰好有 $n-1$ 条边。

从连通性和无环性可以推出很多重要性质：

- 树是**边数最少的连通图**（再少一条边就不连通了）。
- 树是**边数最多的无环图**（再多一条边就会出现环）。
- 任意两个顶点之间有且仅有一条简单路径（这是树最核心的性质）。
- 在树中，删去一条边会把树分成两个连通块；加一条边会产生唯一一个环。

**有根树与无根树**：如果给树指定一个特殊的顶点作为“根”，就变成了有根树。根的存在让树有了父子关系、子树、深度等概念，很多树形 DP 和算法都基于有根树。

### 树的相关概念

#### 树的遍历

遍历树是处理树问题的基本功。常见的遍历方式有：

- **深度优先遍历（DFS）**：从根（或无根树的任意点）出发，递归访问子节点。DFS 可以同时记录每个节点的父节点、深度、子树大小等。
- **广度优先遍历（BFS）**：按层逐层访问，可以用来求树的层次结构。

在 OI 中，树的遍历几乎总是用 DFS，因为它能自然地处理递归结构和子树信息。

#### 树的直径

**直径**是树上最长的简单路径的长度（或者路径本身）。求直径的经典方法：**两次 DFS**。

- 任选一个点 $s$，用 DFS 找到离它最远的点 $u$。
- 再从 $u$ 出发，找到离 $u$ 最远的点 $v$。
- 则 $u$ 到 $v$ 的路径就是树的一条直径，路径长度为 $dist(u, v)$。

为什么两次 DFS 能得到直径？可以用反证法证明：第一次找到的点 $u$ 一定是某条直径的端点。这个性质只对**树**成立。

**直径的中点**就是树的**中心**——它位于直径路径的正中间。树的中心可能是一个点或一条边（当直径长度为奇数时）。中心是树的一个“平衡点”，到所有点的最远距离最小，即最小化偏心距。

#### 树的重心

**重心**是树的一个节点，删除它后，剩下的各个连通块中，**节点数最多的那个块的大小最小**。也就是说，重心让树“尽量均匀”地分裂。

求重心的方法：

- 任选根做 DFS，计算出每个节点的子树大小 $sz[u]$。
- 对于每个节点 $u$，删除它后，最大的连通块大小为：

$$
\max_{v \in children(u)} sz[v] \quad \text{和} \quad n - sz[u]
$$

取这些值的**最小值**，对应的节点就是重心。

重心有一个重要性质：**一棵树最多有两个重心，且若有两个，它们相邻**。重心在树分治（点分治）等算法中非常关键。

### 树的特殊形态

在 OI 题目中，树有时候会以某些特殊形态出现，这些形态往往会导致不同的时间复杂度和解题策略：

- **链（Path）**：每个节点的度数最多为 2，整棵树像一条线。链上的问题常常可以转化为序列上的问题，用线段树、前缀和等处理。
- **菊花图（Star）**：有一个中心节点，其余节点都只与中心相连。这类图在贪心和 DP 中往往有简化的性质。
- **二叉树（Binary Tree）**：每个节点最多有两个子节点。树形 DP 中经常会用二叉树来降低转移复杂度，或者利用左右儿子来设计状态。
- **满二叉树 / 完全二叉树**：有特殊的平衡性质，高度 $O(\log n)$，非常适合分治和搜索剪枝。

了解这些特殊形态，可以帮助你在看到题目的树结构时快速判断是否可利用其特殊性进行优化。

### 树与搜索的关系

树本质上就是一种特殊的图，所以图上的 DFS 和 BFS 都能用在树上。但树的结构让搜索变得更简单、更高效：

1. 树上 DFS 不会遇到“重复访问”的问题（因为无环），所以不需要 visited 数组也能放心递归，只要传一个父节点防止往回走即可（对应的代码片段见下方「逐行代码解析」）。
2. 树的深度优先遍历天然具有“先处理子树，再回溯”的结构，这与树形 DP 的“自底向上”过程完美契合。
3. 树上的 BFS 可以快速计算每个节点的深度（到根的距离），这也是求最短路（边权为 1）的简单方式。

另外，搜索剪枝在树形搜索中也经常使用，比如在状态空间是树形结构时，利用当前深度和剩余可行解进行可行性剪枝。

## 逐行代码解析

上面「树与搜索的关系」里那段树上 DFS，就是本节的代码片段：

```cpp
void dfs(int x){
    //TODO
	for(auto j:G1[x]){
		if(j==fa[x]) continue;
        //TODO
		dfs(j);
        //TODO
	}	
    //TODO
    return ;
}
```

- `void dfs(int x)`：以 `x` 为当前节点出发，没有额外参数——因为树上无环，只要用 `fa[x]` 数组判断「来的那个点」即可，不需要 visited。
- `for(auto j:G1[x])`：遍历 `x` 的邻接点（`G1` 是邻接表，片段里假设它已经建好）。
- `if(j==fa[x]) continue;`：跳过父节点，防止顺着来的那条边走回去。
- `dfs(j);`：递归进子节点；`j` 与 `x` 之间的空位就是处理子树信息的位置（比如统计子树大小、更新 DP 值）。
- 几处以 `//` 开头的行内注释是笔记里保留的，分别对应「进入节点前」「处理子树后」「返回前」的时机，按题目填即可。

## 复杂度分析

树的基础操作复杂度都很低，核心原因是**每个节点、每条边都只被处理常数次**：

- **树的遍历（DFS / BFS）**：$O(n)$。$n$ 个节点各访问一次，邻接表每条边访问常数次。
- **两次 DFS 求直径**：第一次 DFS 找到最远点 $O(n)$，第二次 DFS 再找最远点 $O(n)$，合计 $O(n)$。
- **求重心**：一次 DFS 算出所有子树大小 $sz[u]$ 是 $O(n)$，再扫一遍取最小的最大块，合计 $O(n)$。
- **空间**：邻接表存储 $O(n)$（树恰好有 $n-1$ 条边），加上深度、子树大小等数组仍是 $O(n)$。

## 适用场景

- **树上路径 / 距离问题**：用直径、LCA（见下一篇）快速回答。
- **树形 DP**：利用 DFS「先子树后回溯」的结构，自底向上合并答案。
- **树分治（点分治）**：以树的重心为分割点，保证递归深度 $O(\log n)$。
- **序列化处理**：当树退化成链时，前缀和、线段树等序列工具都能直接上场。
- **判定与转化**：很多问题先证明「答案结构是一棵树」，再套用树的性质。

## 常见陷阱与注意事项

1. **无根树要自己定根**：题目没给根时，任选一个点当根，DFS 时传父节点防止走回头路。
2. **递归深度**：树退化成链时递归 DFS 深度可达 $O(n)$，$n$ 很大要开大栈或改迭代。
3. **直径性质只对树成立**：两次 DFS 求直径依赖「树无环」，换成一般图不成立。
4. **重心的判定别漏一半**：删点后最大连通块要同时考虑「各个子树」和「父亲那一侧（$n - sz[u]$）」，只算子树会漏。
5. **特殊形态先识别**：看到链 / 菊花 / 完全二叉树，先想想能不能利用形态直接把复杂度压下去。$AKB258$, '图论', array['图论', '树', '树的遍历', '树的直径', '树的重心'], null, null, 'knowledge'),
('Fohen', 'col-graph-virtual-tree--fenfeng', '虚树 · Fohen', $AKB259$## 算法原理

虚树是解决**树上多组询问动态规划问题**的一种高效技巧，主要用于**树上选点 DP**：当每次询问只涉及整棵树中极少数的「关键点」时，把与询问无关的节点剥掉，只保留关键点以及连接它们所必需的节点，得到一棵规模大幅缩小的树，再在这棵小树上做 DP。

### 问题引入

给定一棵 $n$ 个节点的树，边有边权。有 $q$ 次询问，每次询问给出一个关键点集合 $S$（设大小为 $k$），要求统计 $S$ 中所有点对之间距离的总和。数据保证 $\sum k \le 5 \times 10^5$，$n, q \le 10^5$。

如果对每次询问都在整棵树上暴力跑一遍 $O(n)$ 的树形 DP，总复杂度为 $O(nq)$，无法通过。但注意：每次真正关心的点只有 $k$ 个，其余节点都是「陪跑」。于是可以把这 $k$ 个关键点独立出来单独建一棵树，在这棵小树上 DP，复杂度降为 $O(\sum k)$ 级别。

虚树的核心思想正是：**把每次询问的关键点分离出来，压缩掉无关的树结构，从而减少不必要的遍历。**

### 为什么 LCA 也要加入

为了保证压缩后的结构仍然是一棵「保留了原树祖先关系」的树，只加入 $k$ 个关键点是不够的——还需要加入这些关键点两两之间的 LCA，用来固定它们的相对位置。一个关键结论是：即使是最坏的二叉树情形，加入的节点总数也不超过 $2k-1$ 个，因此虚树的规模始终是 $O(k)$，复杂度不会退化。

### 基于单调栈的建树方法

利用「同一子树内的 DFS 序连续」这一性质，可以用单调栈建出虚树。先把所有关键点按 DFS 序（`dfn`）排序并去重，然后按如下步骤处理：

1. 将根节点压入栈。记栈顶为 $top$，栈顶之下的元素为 $ftop$。
2. 依次遍历排序后的关键点 $u$，求出 $u$ 与栈顶 $top$ 的 LCA，记为 $lca$。
3. 根据 $lca$ 与栈的关系分三种情况：
   - 若 $lca = top$，说明 $u$ 位于当前栈顶所在的子树内，直接把 $u$ 入栈。
   - 若 $lca \ne top$ 且 $dep[lca] < dep[ftop]$，说明 $top$ 这一支已经处理完毕，在虚树上连边 $ftop \to top$ 并弹出 $top$。
   - 若 $lca \ne top$ 且 $dep[lca] \ge dep[ftop]$，说明 $lca$ 是一个尚未进入虚树的中间节点，弹出 $top$，并依次将 $lca$、$u$ 入栈（若与栈顶重复则不再重复入栈）。
4. 处理完所有关键点后，依次弹出栈中剩余元素，每次连边 $ftop \to top$，虚树即建好。

### 如何在虚树上 DP

虚树建好后，就可以在其上做 DP 回答原问题。以「关键点两两距离之和」为例：先用一次 DP 预处理出每个点到根节点的距离 $h[x]$，则虚树上 $u \to v$ 的边权就是 $h[v] - h[u]$；对虚树上的每条边 $u \to v$，设 $v$ 子树内包含的关键点个数为 $cnt$，则该边对答案的贡献为 $w \times cnt \times (k - cnt)$，树形 DP 一次即可求出总和。

> 虚树没有固定的代码模板：具体的建边方式与 DP 需要按题目具体分析，唯一不变的是「按 DFS 序 + 单调栈」的建树过程本身。

## 核心公式 / 状态定义与转移方程

### 规模上界

设一次询问的关键点个数为 $k$，则虚树的节点总数（关键点 + 补充的 LCA）不超过：

$$
2k - 1
$$

因此在虚树上做一次 DP 的复杂度与 $k$ 成正比，而不是与 $n$ 成正比。

### 边权换算

若 $h[x]$ 表示节点 $x$ 到根节点的路径距离，则虚树上一条边 $u \to v$ 的边权为：

$$
w(u \to v) = h[v] - h[u]
$$

### 距离和的贡献式

对于「求关键点两两之间距离总和」这一类问题，设边 $u \to v$ 的边权为 $w$，$v$ 子树内包含的关键点个数为 $cnt$，则这条边被 $cnt \times (k - cnt)$ 对关键点之间的路径经过，因此对答案的贡献为：

$$
w \times cnt \times (k - cnt)
$$

对虚树做一次自底向上的树形 DP 累加即可。

## 逐行代码解析

> 虚树没有固定模板，本节以**思想步骤伪代码**说明建树与 DP 的流程，不要求与某个完整程序逐字对应。

### 模块一：关键点预处理

```cpp
sort(key + 1, key + 1 + k, cmpByDfn);   // 按 DFS 序排序
k = unique(key + 1, key + 1 + k) - key - 1;   // 去重
```

- 排序后相邻的关键点子树关系最接近，单调栈才能按顺序推进。
- 去重不可省：重复的关键点会导致同一节点被重复入栈，破坏建树过程。

### 模块二：单调栈建树（主循环）

```cpp
st[++tp] = 1;                       // 根节点（或 1 号点）入栈作哨兵
for (int i = 1; i <= k; i++) {
    int u = key[i];
    int l = lca(u, st[tp]);         // u 与栈顶的 LCA
    while (tp >= 2 && dep[l] < dep[st[tp - 1]]) {
        add_edge(st[tp - 1], st[tp]);  // 上一支已结束，连边 ftop -> top
        tp--;
    }
    if (st[tp] != l) {              // l 是中间节点，需插入栈中
        add_edge(l, st[tp]);
        st[tp] = l;
    }
    st[++tp] = u;                   // 关键点入栈
}
```

- `while` 循环对应「$dep[lca] < dep[ftop]$」的分支：此时 $top$ 所在的支已经检索完毕，持续弹栈连边，直到 $lca$ 落到 $top$ 与 $ftop$ 之间。
- `if (st[tp] != l)` 对应「$lca$ 是未检索到的中间节点」的分支：用 $l$ 替换栈顶位置（替换前连边 $l \to top$）。
- 若 $lca = top$，两个分支都不触发，直接 `st[++tp] = u` 入栈，对应「$u$ 在 $top$ 子树内」的情形。

### 模块三：收尾清空栈

```cpp
while (tp >= 2) {
    add_edge(st[tp - 1], st[tp]);
    tp--;
}
```

- 处理完所有关键点后，栈里还留着一条从根到最后一个关键点的「链」，需依次弹出连边。
- 清空后栈中剩下的唯一节点就是虚树的根。

### 模块四：虚树上的 DP

```cpp
// 预处理 h[x]：x 到根的距离；cnt[v]：v 子树内关键点个数
void dfs(int u) {
    cnt[u] = is_key[u];             // 关键点自身计数为 1
    for (auto [v, w] : V[u]) {      // V[u] 为虚树邻接表，边权 w = h[v] - h[u]
        dfs(v);
        ans += w * cnt[v] * (k - cnt[v]);
        cnt[u] += cnt[v];
    }
}
```

- 虚树边权 $w = h[v] - h[u]$ 由预处理出的 $h$ 直接相减得到，无需重新遍历原树。
- 贡献式 $w \times cnt[v] \times (k - cnt[v])$ 表示：$v$ 子树内每个关键点都要与子树外 $k - cnt[v]$ 个关键点配对，都要经过这条边。
- 自底向上汇总 `cnt`，一次 DFS 即可得到全部关键点两两距离之和。

## 复杂度分析

设单次询问的关键点个数为 $k$，所有询问的关键点总数为 $K = \sum k_i$。

| 步骤 | 时间复杂度 |
|---|---|
| 关键点按 DFS 序排序 | $O(k \log k)$ |
| 求 LCA（倍增法） | $O(k \log n)$ |
| 单调栈建树 | $O(k)$（每个点至多入栈出栈一次） |
| 虚树上树形 DP | $O(k)$ |
| **单次询问总计** | $O(k \log n)$（取决于 LCA 实现） |
| **所有询问总计** | $O(K \log n)$ 级别 |

空间复杂度：虚树节点数为 $O(k)$，外加原树的 LCA 预处理数组 $O(n \log n)$（若用倍增 LCA）或 $O(n)$（若用其他在线 LCA）；整体空间由 LCA 预处理决定。

由于虚树没有统一实现，frontmatter 中的复杂度记作「视具体实现」；实际使用时，瓶颈通常在 LCA 查询，建树与 DP 本身均与 $k$ 成正比。

## 适用场景

- **树上多组询问**：题目有 $q$ 次询问，每次只关心若干个关键点，且 $\sum k$ 有保证，例如关键点两两距离之和、关键点集合的最小连通子树等。
- **树上选点 DP**：每次询问在关键点集合上做树形 DP，原树规模 $n$ 很大（如 $10^5$），但单次关键点 $k$ 很小。
- **需要频繁构建小规模树**：关键点集合随询问变化，但原树固定不变——此时 LCA 只需预处理一次，建树过程反复执行。
- **配合 LCA / 树形 DP / 单调栈**：虚树依赖这三者，适合已掌握树形 DP 与 LCA 的读者作为进阶工具。

**不适合**的情形：单次询问就涉及整棵树（$k$ 接近 $n$）时，虚树不会带来收益；树结构频繁变化（动态加边删边）时，LCA 预处理难以维护，也不适合直接套用。

## 常见陷阱与注意事项

1. **重复关键点必须去重**：若同一关键点在集合中出现多次，排序后会导致重复入栈，建树结果错误；排序后务必先 `unique` 再去建树。
2. **关键点的 LCA 也要加入虚树**：只保留关键点无法构成一棵保持祖先关系的树，必须补充 LCA 作为「骨架」；好在节点总数有 $2k-1$ 的上界，不会退化。
3. **排序依据必须是原树的 DFS 序**：排序依据是原树的 `dfn`，不是节点编号；用错排序依据会导致建出的树祖先关系错乱。
4. **区分 $top$ 与 $ftop$**：$top$ 是栈顶，$ftop$ 是栈顶之下的元素；判断「这一支是否已处理完」要比较 $dep[lca]$ 与 $dep[ftop]$，不要与 $dep[top]$ 比较。
5. **弹栈连边的方向**：连边方向为 $ftop \to top$（即父指向子），方向反了会破坏虚树的根向结构，DP 时无法自底向上。
6. **虚树边权要靠原树信息换算**：虚树边是「压缩」出来的，边权通常用根到点的距离之差 $h[v] - h[u]$ 表示，不能直接用原树邻接边权拼接。
7. **DP 要从虚树的根开始**：虚树建完后根是栈中最后剩下的节点，DP 需以它作为起点自底向上汇总；直接遍历原树的根会算错。
8. **不要忽略 LCA 的预处理开销**：总复杂度里 LCA 查询往往占主导，别只盯着 $O(k)$ 的建树而忽略 $O(k \log n)$ 的 LCA 开销。

## 对比与扩展

### 虚树与树链剖分 / 树上差分的区别

| 方法 | 核心思想 | 适用情形 |
|---|---|---|
| 虚树 | 把关键点与 LCA 压缩成小树 | 每次只关心少数关键点，多次询问 |
| 树链剖分 | 把树拆成重链映射到序列 | 树上路径/子树的批量修改与查询 |
| 树上差分 | 用端点标记 + 子树和还原 | 对若干条路径做同一种批量加减 |

三者常互补：虚树压缩「点的规模」，树链剖分解决「路径/子树维护」，树上差分优化「批量路径修改」。

### 虚树与点分治的对比

- 虚树针对「关键点稀疏、多次询问」，把规模从 $n$ 压到 $O(k)$，且保留原树的祖先结构，适合做选点 DP。
- 点分治（重心分治）针对「整棵树上的路径统计」，通过重心递归分治把深度压到 $O(\log n)$，不关心关键点是否稀疏。

### 常见的虚树应用变体

- **关键点两两距离之和**：边权 $h[v]-h[u]$，贡献 $w \times cnt \times (k-cnt)$，一次树形 DP。
- **最小连通块 / 关键点 Steiner 树**：虚树建好后求边权和，或统计连通块内的节点数。
- **多组询问的树上背包 / 选点 DP**：在虚树上做状态 DP，状态规模只与 $k$ 有关。
- **结合换根 DP / 树上前缀和**：虚树把关键点之间的路径信息压缩到小树上，再套用常规树上技巧。

### 延伸阅读

虚树是「树上多组询问」类问题的通用压缩手段，通常与 LCA、树形 DP、单调栈搭配出现。进阶方向包括**点分治、边分治、树链剖分、树上启发式合并（DSU on Tree）**等树上优化技巧，它们从不同角度压缩或拆解树结构。$AKB259$, '图论', array['图论', '树', '虚树', '树形DP', '单调栈'], null, null, 'knowledge'),
('Xesir', 'col-graph-virtual-tree--xesir', '虚树 · Xesir', $AKB260$## 算法原理

虚树是用来解决**树上多组询问 DP**（尤其是**树上选点 DP**）的一把利器。核心思想一句话：**每次询问只关心少数几个「关键点」，那就别在整棵大树上来回跑了，把这些关键点单独拎出来建一棵小树，在小树上 DP。**

前置知识：**LCA**、**树形 DP**、**单调栈**。

### 问题长什么样

给定一棵 $n$ 个节点的树，边有边权。有 $q$ 次询问，每次给出一个关键点集合 $S$（大小为 $k_i$），求 $S$ 中所有点对之间距离的总和。保证 $\sum k_i \le 5 \times 10^5$，$n, q \le 10^5$。

对每个询问暴力跑一遍 $O(n)$ 的树形 DP，总复杂度 $O(nq)$，光看就过不了。但注意到每次真正在意的只有 $k_i$ 个关键点，其余节点全在陪跑——于是把这些关键点独立出来单独建树，复杂度就降到 $O(\sum k_i)$ 这一档。

### 关键点还得补上 LCA

要保证小树仍然保留原来的祖先关系，光加 $k$ 个关键点不够，还得把它们两两之间的 **LCA** 也加进去当「骨架」，用来固定关键点的相对位置。好消息是：哪怕树退化成最坏的二叉树，需要补充的节点总数也不超过 $2k-1$，所以虚树的规模始终是 $O(k)$，复杂度不会退化。

### 用单调栈建树

利用「同一子树内 dfs 序连续」的性质，可以用单调栈按 dfs 序把点一个个推进去：

1. 把关键点按 `dfn` 排序并去重。
2. 根节点先压入栈。记栈顶为 $top$，栈顶下面那个元素为 $ftop$。
3. 依次处理排序后的点 $u$，求出 $u$ 与栈顶 $top$ 的 LCA：
   - 若 $lca = top$：说明 $u$ 就在 $top$ 所在的子树里，直接把 $u$ 入栈。
   - 若 $lca \ne top$ 且 $dep[lca] < dep[ftop]$：说明 $top$ 这一支已经查完了，在虚树上连边 $ftop \to top$ 并弹出 $top$（这一步要反复做，直到条件不成立）。
   - 若 $lca \ne top$ 且 $dep[lca] \ge dep[ftop]$：说明 $lca$ 是个还没进栈的中间节点，弹出 $top$，再把 $lca$、$u$ 依次入栈（与栈顶重复的就不入）。
4. 处理完所有点后，把栈里剩下的元素依次弹出、每次连边 $ftop \to top$，虚树就建好了。

### 建完怎么 DP

拿上面那个「两两距离之和」来说：先跑一遍 DP 预处理出每个点到根的距离 $h[x]$，那么虚树上边 $u \to v$ 的边权就是 $h[v] - h[u]$。设 $v$ 子树内有 $cnt$ 个关键点，则这条边会被 $cnt \times (k - cnt)$ 对关键点跨过，贡献为 $w \times cnt \times (k - cnt)$，树形 DP 累加即可。

> 虚树没有固定模板：具体怎么连边、怎么 DP 得看题目，唯一不变的是「按 dfs 序 + 单调栈」的建树过程。

## 逐行代码解析

虚树没有统一模板，这里也不贴完整程序（`noCode`），只把「建树 + DP」的过程写成步骤伪代码。

### 模块一：关键点预处理

```cpp
sort(key + 1, key + 1 + k, cmpByDfn);          // 按原树 dfs 序排序
k = unique(key + 1, key + 1 + k) - key - 1;    // 去重
```

- 排序后相邻关键点的子树关系最接近，单调栈才能顺着 dfs 序推进。
- 去重不能省：重复的关键点会导致同一节点被反复入栈，把建树过程搞坏。

### 模块二：单调栈建树主循环

```cpp
st[++tp] = 1;                       // 根节点入栈作哨兵
for (int i = 1; i <= k; i++) {
    int u = key[i];
    int l = lca(u, st[tp]);         // u 与栈顶的 LCA
    while (tp >= 2 && dep[l] < dep[st[tp - 1]]) {
        add_edge(st[tp - 1], st[tp]);   // top 这一支查完，连边 ftop -> top
        tp--;
    }
    if (st[tp] != l) {              // l 是未进栈的中间节点，插到栈顶
        add_edge(l, st[tp]);
        st[tp] = l;
    }
    st[++tp] = u;                   // 关键点入栈
}
```

- `while` 对应「$dep[lca] < dep[ftop]$」那一支：持续弹栈连边，直到 $lca$ 落到 $top$ 与 $ftop$ 之间。
- `if (st[tp] != l)` 对应「$lca$ 是未检索到的中间节点」：先把 $l$ 与 $top$ 连边，再用 $l$ 顶替栈顶。
- 若 $lca = top$，上面两处都不触发，直接 `st[++tp] = u`，对应「$u$ 在 $top$ 子树内」的情形。

### 模块三：收尾清空栈

```cpp
while (tp >= 2) {
    add_edge(st[tp - 1], st[tp]);
    tp--;
}
```

- 处理完所有关键点后，栈里还留着一条从根到最后一个关键点的「链」，要依次弹出连边。
- 清空后栈里剩下的唯一节点就是虚树的根。

### 模块四：虚树上的树形 DP

```cpp
void dfs(int u) {
    cnt[u] = is_key[u];             // 关键点自身计数为 1
    for (auto [v, w] : V[u]) {      // V[u] 为虚树邻接表，边权 w = h[v] - h[u]
        dfs(v);
        ans += w * cnt[v] * (k - cnt[v]);
        cnt[u] += cnt[v];
    }
}
```

- 虚树边权 $w = h[v] - h[u]$ 由预处理的 $h$ 相减得到，不用再遍历原树。
- 贡献式 $w \times cnt[v] \times (k - cnt[v])$：$v$ 子树内每个关键点都要与子树外其余关键点配对，都要经过这条边。
- 自底向上汇总 `cnt`，一次 DFS 就得到所有关键点两两距离之和。

## 复杂度分析

设单次询问关键点数为 $k$，所有询问关键点总数为 $K = \sum k_i$。

- 关键点按 dfs 序排序：$O(k \log k)$
- 求 LCA：视实现而定，倍增法每次 $O(\log n)$，共 $O(k \log n)$
- 单调栈建树：$O(k)$（每个点至多入栈、出栈一次）
- 虚树上树形 DP：$O(k)$

因此单次询问总计约 $O(k \log n)$（瓶颈在 LCA），所有询问合计 $O(K \log n)$ 级别。空间上虚树本身只有 $O(k)$ 个点，大头是 LCA 的预处理数组（倍增法 $O(n \log n)$）。

由于虚树没有统一实现，frontmatter 里的复杂度记作「视具体实现」；真跑起来瓶颈通常就在 LCA 查询，建树和 DP 本身都跟 $k$ 成正比。

## 适用场景

- **树上多组询问 + 选点 DP**：每次只关心少数关键点，且 $\sum k$ 有保证，比如关键点两两距离之和、关键点集合的最小连通子树（Steiner 树）等。
- **原树固定、关键点随询问变化**：LCA 只需预处理一次，之后反复建小树，非常合适。
- 通常要**配合 LCA / 树形 DP / 单调栈**一起用，适合已经掌握树形 DP 与 LCA 的读者作为进阶工具。

**不适合**的情形：

- 单次询问就涉及整棵树（$k$ 接近 $n$）——那还不如直接在原树上跑，虚树白建。
- 树结构在询问之间频繁变化（动态加边删边）——LCA 预处理维护不动，别硬套。

## 常见陷阱与注意事项

1. **关键点必须去重**：同一关键点出现多次会导致重复入栈，建树结果错误；排序后先 `unique`。
2. **LCA 也要进虚树**：只留关键点无法构成保持祖先关系的树，必须补 LCA 当骨架；好在总数有 $2k-1$ 的上界，不会退化。
3. **排序依据是原树的 `dfn`**：不是节点编号，用错了祖先关系会错乱。
4. **区分 $top$ 与 $ftop$**：判断「这一支是否处理完」要比较 $dep[lca]$ 与 $dep[ftop]$，别跟 $dep[top]$ 比。
5. **弹栈连边方向**：连边方向是 $ftop \to top$（父指向子），反了会破坏根向结构，DP 没法自底向上。
6. **虚树边权要用原树信息换算**：压缩出来的边通常用根到点的距离之差 $h[v] - h[u]$ 表示，不能直接把原树邻接边权拼起来。
7. **DP 从虚树的根开始**：建完后根是栈里最后剩下的节点，DP 要以它自底向上汇总。
8. **别忽略 LCA 的开销**：总复杂度里 LCA 查询往往占主导，别只盯着 $O(k)$ 的建树。$AKB260$, '图论', array['图论', '树', '虚树', '树形DP', '单调栈'], null, null, 'knowledge'),
('world-needs-sunday', 'col-hub-graph-modeling', '图论技巧与建模总述', $AKB261$## 算法原理

建模类图论题的特点是：**题目本身不是图，需要先把条件翻译成点与边**，再套用现成的图算法。本页只收「建模与转化」这一族，成员为：

- **通用建模思路**：把状态、限制、操作抽象成点与边，常见套路是拆点、分层、虚拟源汇（`graph-modeling`）。
- **差分约束**：把 $x_j-x_i\le w$ 转成边 $i\to j$ 权 $w$，用最短路判定可行性（`graph-difference-constraints`）。
- **同余最短路**：把「用若干固定步长能否凑出某个数」转成模意义下的最短路（`graph-congruence-shortest-path`）。

## 核心公式 / 状态定义与转移方程

- 差分约束：$x_j \le x_i + w$ ↔ 边 $i\to j$ 权 $w$；有负环则无解；求最大值跑最短路，求最小值跑最长路（或取反）。
- 同余最短路：以模数 $m$ 为点，加入面额 $a$ 就是边 $u\to(u+a)\bmod m$ 权 $a$，跑最短路得到最小可达值。
- 分层图：把「用了多少次特殊操作」做成层号，层间连边表示一次操作，空间 $O(k\cdot m)$。

## 逐行代码解析

本页是总述页，不附实现。三条子条目各自给出建模过程与对应模板（SPFA/最短路、Dijkstra）；建模题的关键代码往往就是「加边」，难点在建图而不是算法本身。

## 复杂度分析

- 差分约束：点 $n$、边 $m$ 时 $O(nm)$（SPFA 均摊更快）。
- 同余最短路：$O(m\log m)$，$m$ 为模数。
- 分层图：点数乘层数，复杂度按 $O((n k)\log(n k))$ 或 $O(nk\cdot m)$ 估。

## 适用场景

- 题目给的是不等式组 → 差分约束。
- 题目给的是「能否凑出 / 最小凑出多少」且数字很大 → 同余最短路。
- 题目有「最多用 $k$ 次某个操作」→ 分层图。
- 题目要求把限制、冲突、依赖关系表达成图 → 通用建模（拆点、虚拟源汇）。
- 不适合：限制不是可加/可比的不等式，硬建图会得到错误的最短路模型。

## 常见陷阱与注意事项

- 差分约束的边方向写反（$x_j \le x_i+w$ 是从 $i$ 连到 $j$）。
- 求最大/最小值与最短/最长路的对应关系搞混。
- 同余最短路忘记初始化 `dis[0]=0`，或答案统计时把不可达状态算进去。
- 分层图的层数开小；层间连边时把「不用操作」的边漏掉。
- 虚拟源汇加入后没有同步更新点数与数组大小。

## 对比与扩展

建模题最终都会落到最短路、拓扑排序、网络流或差分约束这些标准工具上；差分约束本质是「最短路的不等式形式」，同余最短路是「模结构上的最短路」，分层图是「把状态并入图」。学习顺序建议：先掌握最短路与拓扑排序，再学差分约束，最后做分层图与同余最短路这类转化题。$AKB261$, '图论', array['建模', '分层图', '差分约束', '总述'], null, null, 'knowledge'),
('world-needs-sunday', 'col-hub-graph-tree', '树上问题总述', $AKB262$## 算法原理

树上问题专指**在无向树（或有向树形结构）上**做路径与子树相关的查询与修改。它不包括用线段树维护区间这类与树无关的内容，成员只有图论大类下的树算法：

- **树的表示与性质**：树的定义、度数、深度、子树、直径与重心（`graph-tree-basic`、`graph-centroid`）。
- **最近公共祖先**：倍增（`graph-lca-doubling`）、重链剖分（`graph-lca-hld`）、Tarjan 离线（`graph-lca-tarjan`）。
- **树上路径操作**：重链剖分 + 线段树（`graph-hld-segtree`）、虚树（`graph-virtual-tree`）。
- **特殊树形**：基环树（`graph-cyclic-tree`）。

## 核心公式 / 状态定义与转移方程

- 深度与祖先：`dep[v] = dep[fa[v]] + 1`；倍增表 `up[k][v] = up[k-1][ up[k-1][v] ]`。
- LCA：先把两点抬到同深度，再从高到低同时上跳。
- 重链剖分：`siz[v] = 1 + Σ siz[son]`，重儿子取 `siz` 最大者；`dfn` 保证一条重链连续。
- 路径查询：把路径拆成 $O(\log n)$ 段重链区间，交给线段树。
- 虚树：只保留关键点与它们的 LCA，按 `dfn` 排序后用栈建树。

## 逐行代码解析

本页是总述页，不附实现。倍增 LCA、树链剖分、虚树、基环树的完整模板与逐行注释在各子条目中；它们共用的前置是「一次 DFS 求 `dep` / `fa` / `siz` / `dfn`」。

## 复杂度分析

- 倍增 LCA：预处理 $O(n\log n)$，单次查询 $O(\log n)$。
- 树链剖分：预处理 $O(n)$，单次路径操作 $O(\log^2 n)$。
- Tarjan 离线 LCA：$O(n+q)$。
- 虚树：单次建树 $O(k\log k)$，$k$ 为关键点数。
- 重心：$O(n)$。

## 适用场景

- 需要求两点 LCA、两点距离、路径上的最值/和。
- 需要对路径或子树做整体修改与查询（树链剖分）。
- 多次询问只涉及少量关键点（虚树）。
- 树上恰好有一个环（基环树），需要拆环后分别处理。
- 不适合：图不是树（有多个环）时不能直接套 LCA / 树链剖分。

## 常见陷阱与注意事项

- 倍增上界开小（要开 $\lfloor\log_2 n\rfloor+1$）。
- 树链剖分后把 `dfn` 与原始编号混用。
- 递归 DFS 在深链上爆栈。
- 虚树建树时忘记把 LCA 也加入关键点。
- 基环树找环写错，或多棵基环树森林没有分别处理。

## 对比与扩展

树上问题与数据结构结合最紧的是「树链剖分 + 线段树」；与 DP 结合是树形 DP；与分块结合是树分块。学习顺序建议：树的遍历与性质 → 倍增 LCA → 树链剖分 → 虚树 → 基环树。$AKB262$, '图论', array['树', 'LCA', '树链剖分', '总述'], null, null, 'knowledge'),
('world-needs-sunday', 'col-hub-graph', '图论总述', $AKB263$## 算法原理

图论把对象之间的**关系**抽象成点与边，再在图上求解路径、连通性、生成树、支配关系等问题。解题的第一步不是套算法，而是判断题目属于哪一类图问题：

- **可达与最短路**：BFS、Dijkstra、Bellman-Ford、SPFA、Floyd、Johnson、DAG 最短路。
- **连通性**：并查集、Tarjan 强连通分量、割点与桥、点双/边双、缩点。
- **生成树**：Kruskal、Prim、Boruvka。
- **树结构**：树的遍历、LCA、树链剖分、树的重心、虚树。
- **匹配与流**：二分图匹配、网络流。
- **建模**：把非图问题转成图问题，例如差分约束、2-SAT、拆点、分层图。

图论题的关键往往在建模：点是什么、边是什么、边权是什么、要求的是哪条路径或哪个连通块。

## 核心公式 / 状态定义与转移方程

图算法的统一分析框架：

1. **确定图的规模**：点数、边数、是否有负权、是否带环、是否多测。
2. **选择存储方式**：邻接矩阵适合稠密图，邻接表适合稀疏图，链式前向星适合卡常。
3. **确定不变量**：最短路算法维护“已确定最短距离的集合”，连通性算法维护“已访问/已缩点的集合”，生成树算法维护“已加入的边集无环”。
4. **证明终止与正确性**：Dijkstra 依赖非负边权，Bellman-Ford 依赖松弛轮数，Tarjan 依赖 DFS 时间戳。

树上的问题还要额外确定：以谁为根、信息是自顶向下还是自底向上、是否需要换根。

## 逐行代码解析

本篇是大类总述，不附具体实现。各子分类的模板代码、逐行注释与边界处理在对应知识点页中；最短路、LCA、Tarjan、Kruskal 等条目都给出了可直接复用的骨架。

## 复杂度分析

常见复杂度量级：

- BFS/DFS：$O(n+m)$。
- Dijkstra + 二叉堆：$O((n+m)\log n)$。
- Bellman-Ford：$O(nm)$；SPFA 平均较快但最坏仍为 $O(nm)$。
- Floyd：$O(n^3)$。
- Kruskal：$O(m\log m)$；Prim + 堆：$O((n+m)\log n)$。
- Tarjan：$O(n+m)$。
- 树链剖分：单次路径操作 $O(\log^2 n)$。
- 网络流：取决于增广次数与每次增广的代价，通常写成 $O(V^2E)$ 或更紧的界。

具体量级以各子条目的代码为准。

## 适用场景

- 状态可以表示成点、转移可以表示成边：最短路、拓扑排序、DP on DAG。
- 需要判断连通块、环、割点、桥：并查集与 Tarjan。
- 需要在树上做路径查询或修改：LCA、树链剖分、树上差分。
- 需要匹配、分配、流量约束：二分图匹配与网络流。
- 不适合：状态维度太多、边数爆炸且无法隐式建图（需要先做建模或换算法）。

## 常见陷阱与注意事项

- 无向图存边时忘记建反向边，或反向边编号写错。
- Dijkstra 用于负权图，结果错误；负权要用 Bellman-Ford/SPFA。
- 多测题没有清空邻接表、时间戳、并查集父亲数组。
- Tarjan 的 `dfn/low` 更新条件写错，把横叉边当成返祖边。
- LCA 的深度差与倍增顺序写反，或根节点父亲未初始化。
- 生成树算法没有判重边/自环，或并查集未初始化。
- 递归深度过大导致栈溢出，树链剖分与 DFS 尤其常见。

## 对比与扩展

图论与数据结构的交叉很多：最短路用堆，连通性用并查集，树链剖分用线段树维护区间信息。学习时先掌握图的存储、BFS/DFS、拓扑排序与并查集，再进入最短路、生成树、连通分量与树上结构，最后处理网络流与建模题。$AKB263$, '图论', array['图论', '总述', '学习路线'], null, null, 'knowledge');

